insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a2-e5bc24b894ff', 'en', 'A2', 'A Day at the Market', 'Last Saturday, Maria went to the local market to buy food for the week. She needed some fruit, vegetables, bread, and milk. At the market, she saw many stalls with fresh products. First, she bought some apples and oranges. She also bought a bottle of milk and a loaf of bread. Maria wanted to buy some cheese, but she did not have enough money. She asked the seller, "How much does this cheese cost?" The seller said, "It is ten reais per kilo." Maria thought it was too expensive, so she did not buy any.

After that, Maria saw a stall with different kinds of pasta and rice. She bought two packets of pasta and one bag of rice. She also wanted to buy some chocolate for her brother, but she remembered that he does not like sweets. So she bought some coffee instead.

Maria carried her shopping bags home. She was happy because she had bought everything she needed. She put the food in the kitchen: the fruit in a bowl, the milk in the fridge, and the pasta in the cupboard. She then made a delicious dinner with the ingredients she had.

Maria loves going to the market because she can find fresh food and save money. She always makes a list to remember what to buy. This week, she wrote: apples, oranges, milk, bread, cheese, pasta, rice, and coffee.', '[{"answer_index":0,"explanation_pt_br":"Maria comprou frutas (apples and oranges) e vegetais (vegetables), além de outros itens.","options":["Some fruit and vegetables","Some fruit and bread","Some fruit and milk","Some fruit and cheese"],"prompt":"What did Maria buy at the market?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''Maria wanted to buy some cheese, but she didn''t have enough money.'' e depois ''She thought it was too expensive''.","options":["Because she didn''t like cheese","Because the cheese was too expensive","Because she had no money","Because the seller didn''t have cheese"],"prompt":"Why didn''t Maria buy cheese?"},{"answer_index":0,"explanation_pt_br":"O vendedor disse: ''It''s ten reais per kilo.''","options":["Ten reais per kilo","Five reais per kilo","Twenty reais per kilo","Fifteen reais per kilo"],"prompt":"How much did the cheese cost?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''So she bought some coffee instead.''","options":["Coffee","Tea","Juice","Cake"],"prompt":"What did Maria buy instead of chocolate?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.reading_passages (id, language, level, title, body, questions, sort_order, is_published)
values ('generated-reading-en-a2-11a99ba4b109', 'en', 'A2', 'A Day in the Life of Two Friends', 'Paula and Marcos are students in São Paulo. They like to do different things on weekends. Paula enjoys cooking and often tries new recipes. She loves to bake cakes and cookies for her family. Marcos prefers to play football with his friends. He also likes to watch movies at home.

On Saturday morning, Paula decided to make a chocolate cake. She needed to buy some ingredients, so she went to the market. After shopping, she started to bake. She spent two hours in the kitchen. Marcos, on the other hand, woke up late and went to the park to play football. He played for three hours and felt very tired.

In the afternoon, they met at a café. Paula brought a piece of cake for Marcos. He loved it! They talked about their plans for the next day. Paula wants to visit her grandmother, and Marcos wants to study for his English test. They agreed to meet again on Sunday evening to watch a movie together.

Doing different activities is fun, but sharing time with friends is even better. Paula and Marcos are happy because they can do what they like and still spend time together.', '[{"answer_index":1,"explanation_pt_br":"O texto diz: ''Paula enjoys cooking and often tries new recipes.'' Portanto, ela gosta de cozinhar e assar.","options":["She likes to play football","She likes to cook and bake","She likes to study English","She likes to watch movies"],"prompt":"What does Paula like to do on weekends?"},{"answer_index":2,"explanation_pt_br":"O texto diz: ''Marcos, on the other hand, woke up late and went to the park to play football.''","options":["He went to the market","He visited his grandmother","He played football in the park","He studied for his English test"],"prompt":"What did Marcos do on Saturday morning?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''She needed to buy some ingredients, so she went to the market.''","options":["To buy ingredients for a cake","To meet Marcos","To buy a new book","To visit her grandmother"],"prompt":"Why did Paula go to the market?"},{"answer_index":2,"explanation_pt_br":"O texto diz: ''Marcos wants to study for his English test.''","options":["To bake a cake","To play football again","To study for his English test","To watch a movie with Paula"],"prompt":"What are Marcos''s plans for Sunday?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-bf05383f76d2', 'en', 'A2', 'Present Continuous in English', 'O Present Continuous (ou Present Progressive) é usado para falar sobre ações que estão acontecendo agora, no momento da fala, ou sobre planos futuros já combinados. Nesta lição, você vai aprender como formar essa estrutura e quando usá-la, além de praticar com exercícios.', 'Para formar o Present Continuous, usamos o verbo ''to be'' (am, is, are) + o verbo principal com ''ing''. Exemplos: I am studying, She is working, They are playing. Para negar, adicionamos ''not'' após o verbo ''to be'' (I am not studying). Para perguntar, invertemos o verbo ''to be'' com o sujeito (Are you studying?).', '["Ações que estão acontecendo agora: ''I am reading a book right now.''","Ações temporárias: ''She is living in São Paulo this month.''","Planos futuros já combinados: ''We are meeting friends tomorrow.''","Mudanças ou tendências: ''The weather is getting hotter.''"]'::jsonb, '["Esquecer o verbo ''to be'': ''I working'' (errado) vs. ''I am working'' (correto).","Usar o Present Simple para ações no momento: ''I go to school now'' (errado) vs. ''I am going to school now'' (correto).","Errar a forma do verbo com ''ing'': ''makeing'' (errado) vs. ''making'' (correto).","Usar verbos de estado (like, love, hate) no Present Continuous: ''I am liking this'' (errado) vs. ''I like this'' (correto)."]'::jsonb, '["A contração é comum: ''I''m'', ''she''s'', ''we''re''.","Em perguntas, a entonação sobe no final.","A forma negativa contrata: ''isn''t'', ''aren''t''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

