insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-180fdeabd5a5', 'en', 'A2', 'Comparatives and Superlatives', 'Nesta lição, você vai aprender a comparar pessoas, lugares e coisas usando comparativos e superlativos em inglês. Vamos ver como dizer que algo é ''mais... que'' ou ''o mais... de''.', 'Para formar o comparativo de adjetivos curtos (1 sílaba), adicionamos ''-er'' e usamos ''than''. Para adjetivos longos (2 ou mais sílabas), usamos ''more'' antes do adjetivo. Para o superlativo, usamos ''the'' + ''-est'' para curtos e ''the most'' para longos. Exemplos: ''tall'' -> ''taller than'' (mais alto que) e ''the tallest'' (o mais alto). ''beautiful'' -> ''more beautiful than'' (mais bonito que) e ''the most beautiful'' (o mais bonito).', '["Comparar duas coisas ou pessoas.","Falar sobre a qualidade mais alta ou extrema em um grupo."]'::jsonb, '["Usar ''more'' com adjetivos curtos (ex: ''more tall'').","Esquecer ''the'' antes do superlativo (ex: ''tallest'' em vez de ''the tallest'')."]'::jsonb, '["Alguns adjetivos têm formas irregulares: ''good'' -> ''better'' -> ''the best''; ''bad'' -> ''worse'' -> ''the worst''.","Use ''than'' após o comparativo: ''She is taller than me''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

