insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-6c8c9e6d2dc6', 'en', 'A2', 'Frequency and Manner Adverbs', 'Nesta lição, você vai aprender a usar advérbios de frequência (como ''always'', ''usually'') e de modo (como ''quickly'', ''carefully'') para enriquecer suas frases em inglês. Esses advérbios ajudam a dizer com que frequência algo acontece e como algo é feito.', 'Advérbios de frequência geralmente vêm antes do verbo principal (ex: ''She always drinks coffee'') e depois do verbo ''to be'' (ex: ''He is often late''). Advérbios de modo geralmente vêm depois do verbo ou do objeto (ex: ''She sings beautifully''). Eles são formados frequentemente adicionando ''-ly'' ao adjetivo (ex: ''quick'' vira ''quickly'').', '["Para dizer com que frequência fazemos algo: I always brush my teeth.","Para descrever como uma ação é feita: She speaks softly.","Para responder perguntas como ''How often?'' e ''How?''."]'::jsonb, '["Colocar o advérbio de frequência no lugar errado: ''I drink always coffee'' (incorreto) vs ''I always drink coffee'' (correto).","Esquecer de adicionar ''-ly'' para advérbios de modo: ''He drives careful'' (incorreto) vs ''He drives carefully'' (correto).","Usar adjetivo em vez de advérbio após o verbo: ''She sings beautiful'' (incorreto) vs ''She sings beautifully'' (correto)."]'::jsonb, '["Alguns advérbios de frequência comuns: always, usually, often, sometimes, rarely, never.","Have para ações habituais use o Present Simple com advérbios de frequência.","Alguns advérbios de modo são irregulares: ''well'' (não ''goodly''), ''fast'', ''hard'' (sem ''-ly'')."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

