insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-5f7543954b61', 'en', 'A2', 'Countable and Uncountable Nouns: Using Quantifiers', 'Nesta lição, você vai aprender a diferença entre substantivos contáveis e incontáveis em inglês e como usar quantificadores como ''some'', ''any'', ''much'' e ''many'' corretamente.', 'Substantivos contáveis têm forma plural (ex: apple → apples) e usam ''a/an'' no singular. Incontáveis não têm plural (ex: water). Para quantificar, usamos:
- some: em frases afirmativas (ex: I have some water.)
- any: em negativas e perguntas (ex: Do you have any milk?)
- many: com contáveis (ex: How many apples?)
- much: com incontáveis (ex: How much water?)
- a lot of: com ambos (ex: a lot of friends, a lot of time)', '["Usamos ''some'' em frases afirmativas: I need some water.","Usamos ''any'' em perguntas e negativas: Do you have any sugar?","Usamos ''many'' com contáveis: She has many books.","Usamos ''much'' com incontáveis: There isn''t much time.","Usamos ''a lot of'' em contextos informais: He drinks a lot of coffee."]'::jsonb, '["Usar ''many'' com incontáveis: ''How many water?'' → correto: ''How much water?''","Usar ''much'' com contáveis: ''How much apples?'' → correto: ''How many apples?''","Usar ''any'' em afirmativas: ''I have any money.'' → correto: ''I have some money.''","Esquecer de usar ''a/an'' com contáveis singulares: ''I have apple.'' → correto: ''I have an apple.''","Usar ''much'' em afirmativas comuns: ''I have much friends.'' → correto: ''I have many friends.''"]'::jsonb, '["Alguns substantivos podem ser contáveis e incontáveis com significados diferentes (ex: a coffee = uma xícara de café, coffee = café em geral).","Em perguntas oferecendo algo, usamos ''some'': ''Would you like some tea?''","Em negativas, usamos ''any'': ''I don''t have any money.''","Não use ''a/an'' com incontáveis: ''I need a water'' → ''I need water'' ou ''a glass of water''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

