insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-553ebd154d23', 'en', 'A2', 'Should, Must, Have to, May: Modal Verbs for Advice, Obligation, and Permission', 'Nesta lição, você vai aprender a usar os verbos modais should, must, have to e may. Eles ajudam a dar conselhos, falar sobre obrigações e pedir permissão. Vamos praticar com exercícios!', 'Os modais são seguidos do verbo principal na forma base (sem ''to''): You should study. A forma negativa: should not (shouldn''t), must not (mustn''t), may not. Have to se conjuga: have to/has to, negative: don''t have to/doesn''t have to, past: had to.', '["Should: dar conselho ou recomendação (You should sleep more.)","Must: obrigação forte ou regra (You must stop at the red light.)","Have to: obrigação externa (I have to work tomorrow.)","May: pedir ou dar permissão (May I come in?)","Don''t have to: ausência de obrigação (You don''t have to go.)","Mustn''t: proibição (You mustn''t smoke here.)"]'::jsonb, '["Não use ''to'' depois de should, must ou may: ''I must to go'' é errado.","Não confunda ''mustn''t'' (proibido) com ''don''t have to'' (não precisa).","Não use ''does'' com modal: ''He must goes'' é errado; use ''He must go''.","Não use ''may'' no passado; use ''was allowed to''."]'::jsonb, '["Os modais não mudam com he/she/it.","Em perguntas com modais, inverta a ordem: ''May I...?'', ''Should I...?''.","Have to pode ser usado em todos os tempos; must não tem passado."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

