insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-c123456484a5', 'en', 'A2', 'Relative Clauses with Who, Which, That', 'Aprenda a usar who, which e that para conectar informações sobre pessoas e coisas. Essas palavras ajudam a criar frases mais ricas e naturais em inglês.', 'Quem (who) é usado para pessoas. Qual (which) é usado para coisas ou animais. Que (that) pode ser usado tanto para pessoas quanto para coisas. A oração relativa vem depois do substantivo que ela descreve. Exemplos: The woman who lives next door is a doctor. The book which is on the table is mine. The car that I bought is red.', '["Para identificar ou dar informação extra sobre uma pessoa: who.","Para identificar ou dar informação extra sobre uma coisa ou animal: which ou that.","Para pessoas em situações informais, também podemos usar that.","Quando a informação é essencial para entender a frase, usamos who, which ou that sem vírgulas."]'::jsonb, '["Usar ''which'' para pessoas.","Usar ''who'' para coisas.","Esquecer de colocar o pronome relativo quando necessário.","Usar vírgulas quando a oração relativa é essencial."]'::jsonb, '["Em inglês, who, which e that podem ser omitidos quando são objeto da oração relativa, mas no nível A2 é mais seguro usá-los.","Preste atenção: a oração relativa geralmente vem logo depois do substantivo que ela modifica."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

