insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-96f702d16e29', 'en', 'A2', 'Comparatives and Superlatives in English', 'Nesta lição, você vai aprender a comparar coisas e pessoas em inglês. Vamos ver como falar que algo é ''mais'' ou ''menos'' que outra coisa, e como expressar o ''mais'' de um grupo. Isso ajuda a descrever o mundo ao seu redor e a fazer escolhas.', 'Para comparativos de superioridade com adjetivos curtos (1 sílaba), adicione ''-er'' (ex.: ''tall'' → ''taller''). Com adjetivos longos (2+ sílabas), use ''more'' (ex.: ''beautiful'' → ''more beautiful''). Para superlativos, use ''the'' + ''-est'' para curtos (ex.: ''the tallest'') e ''the most'' para longos (ex.: ''the most beautiful''). Alguns são irregulares: ''good'' → ''better'' → ''the best''; ''bad'' → ''worse'' → ''the worst''.', '["Comparar duas coisas ou pessoas: ''My car is faster than yours.''","Escolher entre opções: ''This one is more interesting.''","Falar sobre o máximo em um grupo: ''She is the smartest student in class.''"]'::jsonb, '["Usar ''more'' com adjetivos curtos: ''more tall'' (errado) → ''taller'' (correto).","Esquecer ''the'' antes do superlativo: ''She is tallest'' (errado) → ''She is the tallest'' (correto).","Confundir ''than'' e ''then'': ''I am taller than you'' (comparação) vs. ''Then I left'' (tempo)."]'::jsonb, '["Adjetivos de 2 sílabas terminados em ''-y'' viram ''-ier'' (ex.: ''happy'' → ''happier'').","Para comparar igualdade, use ''as ... as'' (ex.: ''He is as tall as his brother'').","Não use ''than'' com superlativos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

