insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-2c311260f42e', 'en', 'A2', 'Countable and Uncountable Nouns: Using ''Some'' and ''Any''', 'Nesta lição, você vai aprender a diferença entre substantivos contáveis e incontáveis em inglês. Substantivos contáveis podem ser contados (ex: one apple, two apples), enquanto incontáveis não podem (ex: water, bread). Vamos focar no uso de ''some'' e ''any'' para falar de quantidades indefinidas.', 'Use ''some'' em frases afirmativas e em ofertas/pedidos. Use ''any'' em frases negativas e perguntas. Exemplos: I have some water. (Eu tenho um pouco de água.) There isn''t any milk. (Não há leite.) Do you have any money? (Você tem algum dinheiro?)', '["Falar de quantidades indefinidas: I need some sugar.","Perguntas educadas: Can I have some coffee?","Negativas: We don''t have any oranges.","Perguntas: Do you have any questions?","Ofertas: Would you like some tea?"]'::jsonb, '["Usar ''some'' em perguntas: você deve usar ''any'' na maioria delas. Ex: Do you have any sugar? (não ''some'')","Usar ''any'' em afirmativas: em geral, use ''some''. Ex: I have some friends. (não ''any'')","Contar incontáveis: não diga ''a water'', diga ''some water''."]'::jsonb, '["Substantivos incontáveis geralmente não têm plural.","''Some'' pode ser usado em perguntas quando você espera uma resposta sim.","Com contáveis, use ''some'' com plural: some apples."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

