insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-66d34b393ef3', 'en', 'A2', 'Using Infinitives and Gerunds in English (A2)', 'Nesta lição, você vai aprender a usar o infinitivo (to + verbo) e o gerúndio (verbo + -ing) em inglês. Vamos ver quando usar cada um depois de certos verbos e expressões.', 'Infinitivo: to + forma base do verbo (ex.: to go, to eat). Gerúndio: verbo + -ing (ex.: going, eating). Alguns verbos são seguidos de infinitivo (ex.: want, need, decide), outros de gerúndio (ex.: enjoy, finish, mind). Alguns podem ser seguidos de ambos, mas com significado diferente (ex.: like, love, start).', '["Usamos infinitivo depois de verbos como want, need, decide, hope, plan.","Usamos gerúndio depois de verbos como enjoy, finish, mind, suggest.","Usamos gerúndio depois de preposições, como in, on, at, for, of.","Usamos infinitivo para expressar propósito (I study to learn).","Usamos gerúndio como sujeito da frase (Swimming is fun)."]'::jsonb, '["Dizer ''I enjoy to dance'' em vez de ''I enjoy dancing''.","Dizer ''I want going'' em vez de ''I want to go''.","Usar infinitivo depois de preposição: ''I''m good at to cook'' em vez de ''I''m good at cooking''."]'::jsonb, '["Lembre: depois de preposições, sempre use gerúndio.","Alguns verbos como ''like'', ''love'', ''hate'' podem ser seguidos por infinitivo ou gerúndio com pouca diferença de significado.","Na fala informal, ''going to'' é usado para futuro, mas não confunda com o gerúndio.","Pratique com verbos comuns: like, love, enjoy, want, need, decide, plan."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

