insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-b916a805c48d', 'en', 'A2', 'Relative Clauses: Who, Which, That', 'Vamos aprender a usar ''who'', ''which'' e ''that'' para conectar informações e fazer frases mais interessantes. Essas palavras são usadas para falar de pessoas, coisas e animais.', 'Use ''who'' para pessoas, ''which'' para coisas e animais, e ''that'' pode ser usado para pessoas ou coisas em situações informais. Exemplos: ''The woman who lives next door is nice.'' (A mulher que mora ao lado é simpática.) / ''The book which is on the table is mine.'' (O livro que está na mesa é meu.) / ''The dog that is barking is loud.'' (O cachorro que está latindo é barulhento.)', '["Para identificar uma pessoa: ''The teacher who teaches English is from Canada.''","Para identificar uma coisa: ''The laptop which I bought is fast.''","Para identificar um animal: ''The cat that sleeps all day is lazy.''","Em situações informais, ''that'' pode substituir ''who'' ou ''which''.","Para adicionar informação importante sobre o sujeito ou objeto."]'::jsonb, '["Usar ''which'' para pessoas: ''The man which is tall'' (errado) → ''The man who is tall'' (correto).","Usar ''who'' para coisas: ''The car who is red'' (errado) → ''The car which is red'' (correto).","Esquecer de usar a palavra relativa: ''The woman lives next door is nice'' (errado) → ''The woman who lives next door is nice'' (correto).","Usar ''what'' em vez de ''which'' ou ''that'' em frases relativas."]'::jsonb, '["Não confunda ''that'' com ''what''. ''That'' é usado para conectar ideias, ''what'' é usado em perguntas.","Em frases curtas, você pode omitir ''that'' às vezes, mas para iniciantes é melhor sempre usar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

