insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-398923a95779', 'en', 'A2', 'Basic Connectors: and, but, or, because, so', 'Nesta lição, você vai aprender a usar conectivos básicos em inglês: ''and'', ''but'', ''or'', ''because'' e ''so''. Essas palavras ajudam a conectar ideias e formar frases mais interessantes. Você vai ver como usá-las em situações do dia a dia, como falar sobre rotina, preferências e planos.', 'Conectivos são palavras que ligam duas partes de uma frase. Veja alguns exemplos:
- ''And'' é usado para adicionar informações: ''I like coffee and tea.''
- ''But'' é usado para mostrar contraste: ''I like coffee, but I don''t like tea.''
- ''Or'' é usado para mostrar opções: ''Do you want coffee or tea?''
- ''Because'' é usado para dar uma razão: ''I drink coffee because I need energy.''
- ''So'' é usado para mostrar resultado: ''I was tired, so I went to bed.''', '["Usamos ''and'' para juntar duas coisas: ''I have a car and a bike.''","Usamos ''but'' para mostrar uma diferença: ''The movie was long, but it was good.''","Usamos ''or'' em perguntas e escolhas: ''Do you want pizza or pasta?''","Usamos ''because'' para explicar o motivo: ''I''m learning English because I want to travel.''","Usamos ''so'' para mostrar o resultado de uma ação: ''It was raining, so I took an umbrella.''"]'::jsonb, '["Não confunda ''because'' com ''so'': ''because'' dá o motivo; ''so'' dá o resultado. Exemplo errado: ''I was tired because I went to bed.'' (correto: ''I was tired, so I went to bed.'')","Evite usar ''but'' e ''and'' juntos: ''I like coffee and but I don''t like tea.'' (incorreto)","Lembre-se de colocar uma vírgula antes de ''so'' em frases longas: ''I was hungry, so I made a sandwich.''","Não use ''or'' quando a frase é negativa: use ''and'' em frases negativas: ''I don''t like coffee or tea.'' (não ''or'' sozinho)"]'::jsonb, '["Conectivos são muito comuns em inglês e ajudam a tornar a fala mais natural.","Pratique com frases simples do seu dia a dia para memorizar.","Cuidado com a ordem: o conectivo vem entre as duas ideias que você quer ligar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

