insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-531b60702a6a', 'en', 'A2', 'Going to vs. Will: Making Plans and Predictions', 'Nesta lição, você vai aprender a diferença entre "going to" e "will" para falar sobre o futuro. Usamos "going to" para planos e intenções, e "will" para decisões espontâneas e previsões. Vamos praticar com exercícios!', 'Para formar o futuro com ''going to'', use o verbo ''to be'' (am, is, are) + going to + verbo base. Exemplo: ''I am going to study.'' Para ''will'', use ''will'' + verbo base. Exemplo: ''I will help you.''', '["Planos e intenções: ''I am going to visit my family next weekend.''","Decisões no momento da fala: ''The phone is ringing. I will answer it.''","Previsões com evidências: ''Look at those clouds! It is going to rain.''","Previsões sem evidências: ''I think Brazil will win the game.''","Promessas e ofertas: ''I will help you with your homework.''"]'::jsonb, '["Usar ''going to'' para decisões espontâneas: ''I am going to help you'' (quando você decide na hora, use ''will'').","Esquecer o verbo ''to be'' antes de ''going to'': ''I going to travel'' (correto: ''I am going to travel'').","Usar ''will'' para planos já feitos: ''I will travel to São Paulo next month'' (se o plano já existe, use ''going to'').","Confundir a forma negativa: ''I won''t go'' (não use ''I don''t will go'')."]'::jsonb, '["Na linguagem falada, ''going to'' muitas vezes vira ''gonna''.","''Will'' pode ser contraído para ''ll'' (ex.: ''I''ll'').","Use ''will'' para promessas e ofertas.","Use ''going to'' para planos que você já decidiu antes de falar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

