insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-1411ec550a23', 'en', 'A2', 'Comparatives and Superlatives', 'Nesta lição, você vai aprender a comparar coisas, pessoas e lugares em inglês. Os comparativos são usados para comparar duas coisas, e os superlativos para mostrar que algo é o mais, o maior, etc.', 'Para comparativos de adjetivos curtos (1 sílaba), adicione ''-er'' e use ''than'': ''tall'' → ''taller than''. Para adjetivos longos (2+ sílabas), use ''more'' + adjetivo: ''beautiful'' → ''more beautiful than''. Superlativos: use ''the'' + ''-est'' para curtos: ''tall'' → ''the tallest''. Para longos, use ''the most'' + adjetivo: ''beautiful'' → ''the most beautiful''. Alguns são irregulares: ''good'' → ''better'' → ''the best''; ''bad'' → ''worse'' → ''the worst''.', '["Comparar duas coisas: ''This book is cheaper than that one.''","Mostrar que algo tem a maior qualidade em um grupo: ''This is the best pizza in town.''","Falar sobre mudanças: ''My English is getting better.''","Expressar preferências: ''I like coffee more than tea.''"]'::jsonb, '["Usar ''more'' com adjetivos curtos: ''more tall'' (errado) → ''taller'' (correto).","Esquecer ''the'' antes de superlativos: ''She is best student'' (errado) → ''She is the best student'' (correto).","Usar ''than'' no superlativo: ''He is the tallest than me'' (errado) → ''He is the tallest in the class'' (correto)."]'::jsonb, '["Lembre-se: um adjetivo curto tem uma ou duas sílabas? Normalmente, uma sílaba.","Alguns adjetivos de duas sílabas podem usar as duas formas, por exemplo, ''cleverer'' ou ''more clever''.","Use ''than'' para comparativos, mas não para superlativos.","''The'' é sempre usado com superlativos."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

