insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-3fd47a0d3974', 'en', 'A2', 'Adverbs of Frequency and Manner', 'Nesta lição, você vai aprender a usar advérbios de frequência (como ''always'', ''usually'', ''never'') e advérbios de modo (como ''quickly'', ''carefully'') para falar sobre hábitos e ações. Esses advérbios ajudam a dar mais detalhes sobre como e com que frequência as coisas acontecem.', 'Advérbios de frequência geralmente vêm antes do verbo principal, mas depois do verbo ''to be''. Exemplos: ''She always drinks coffee.'' e ''He is never late.'' Advérbios de modo geralmente vêm depois do verbo principal ou do objeto. Exemplos: ''She sings beautifully.'' e ''He eats quickly.''', '["Para falar de hábitos e rotinas (frequência).","Para descrever como uma ação é feita (modo).","Para responder perguntas como ''How often?'' e ''How?''."]'::jsonb, '["Colocar o advérbio de frequência depois do verbo ''to be'' (ex: ''She is always'') – correto é ''She always is'' não; correto é ''She is always''.","Usar ''never'' e ''not'' juntos (ex: ''I don''t never'') – correto é ''I never''.","Colocar o advérbio de modo no lugar errado (ex: ''He drives carefully'' não ''He carefully drives'' se o foco é o modo e não a frequência).","Confundir ''hardly'' (quase não) com ''hard'' (difícil, com esforço)."]'::jsonb, '["Advérbios de frequência: always, usually, often, sometimes, rarely, never.","Advérbios de modo: quickly, slowly, carefully, well, badly, etc.","Na posição com ''to be'', o advérbio vem depois do verbo: ''He is always happy.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

