insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-4b095fbeb86a', 'en', 'A2', 'Should, Must, Have to, May', 'Nesta lição, você vai aprender a usar os verbos modais should, must, have to e may. Eles ajudam a expressar conselhos, obrigações e permissões. Vamos ver como usá-los no dia a dia!', 'Eles são seguidos pelo verbo principal na forma base (sem ''to''). Exemplos: ''You should study.'' / ''She must go.'' / ''They have to work.'' / ''May I come in?''', '["Should: usado para dar conselhos ou recomendações. Ex: ''You should drink water.''","Must: usado para obrigações fortes ou regras. Ex: ''You must stop at the red light.''","Have to: usado para obrigações externas (por exemplo, leis ou trabalho). Ex: ''I have to wear a uniform.''","May: usado para pedir e dar permissão de forma formal. Ex: ''May I use your phone?''"]'::jsonb, '["Usar ''to'' depois de should, must ou may. Ex: errado ''You should to study.''","Confundir ''must'' e ''have to''. ''Must'' é mais pessoal; ''have to'' é algo de fora.","Usar ''may'' para permissão em situações informais – as vezes ''can'' é mais comum.","Esquecer que para ''he/she/it'', ''have to'' vira ''has to''."]'::jsonb, '["''Should'' é mais suave que ''must''.","''May'' também pode ser usado para possibilidade: ''It may rain.''","A forma negativa de ''must'' (mustn''t) significa ''proibido''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

