insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-e25d8dbb1dba', 'en', 'A2', 'Introduction to Infinitives and Gerunds', 'Nesta lição, você vai aprender sobre o uso do infinitivo (to + verbo) e do gerúndio (verbo + -ing) em inglês. Vamos ver quando usar cada um e como eles são comuns em frases do dia a dia.', 'Infinitivo: to + forma base do verbo (exemplo: to go). Gerúndio: verbo + -ing (exemplo: going). O gerúndio geralmente é usado depois de preposições e como sujeito da frase. O infinitivo é usado depois de certos verbos, como ''want'', ''need'' e ''like'', e depois de adjetivos.', '["Usamos o gerúndio como sujeito, como em ''Swimming is fun.''","Usamos o gerúndio depois de preposições, como em ''I am good at cooking.''","Usamos o infinitivo depois de alguns verbos, como ''want'' e ''need'', como em ''I want to eat.''","Usamos o infinitivo depois de adjetivos, como em ''It is important to study.''"]'::jsonb, '["Usar o infinitivo em vez do gerúndio como sujeito: ''To swim is fun'' (menos comum, mas possível; no dia a dia, use ''Swimming'').","Esquecer de colocar ''to'' no infinitivo depois de alguns verbos: ''I want go'' (errado) em vez de ''I want to go'' (correto).","Usar o gerúndio depois de verbos que pedem infinitivo: ''I enjoy to read'' (errado) em vez de ''I enjoy reading'' (correto)."]'::jsonb, '["Alguns verbos podem ser seguidos por gerúndio ou infinitivo com diferença de significado, como ''stop''.","Para falantes de português, lembre-se de que o gerúndio em inglês não é usado com ''estar'' (I am doing) como no português, mas sim para ações em andamento."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

