insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-74f237747b36', 'en', 'A2', 'Going to vs. Will', 'Nesta lição, você vai aprender a diferença entre ''going to'' e ''will'' para falar sobre o futuro. ''Going to'' é usado para planos e intenções, e também para previsões com evidências. ''Will'' é usado para decisões rápidas, promessas, ofertas e previsões sem evidências.', 'Para formar o futuro com ''going to'', usamos: sujeito + verbo ''to be'' (am, is, are) + ''going to'' + verbo principal. Exemplo: ''I am going to travel.'' Para formar com ''will'', usamos: sujeito + ''will'' + verbo principal. Exemplo: ''I will travel.'' A forma negativa: ''am not going to'' ou ''won''t''.', '["Usamos ''going to'' para planos e intenções: ''I am going to visit my family this weekend.''","Usamos ''going to'' para previsões com evidências: ''Look at those clouds! It is going to rain.''","Usamos ''will'' para decisões rápidas: ''I will have the chicken, please.''","Usamos ''will'' para promessas e ofertas: ''I will help you with your homework.''","Usamos ''will'' para previsões sem evidências: ''I think Brazil will win the game.''"]'::jsonb, '["Não usar o verbo ''to be'' antes de ''going to'': ''I going to study'' → ''I am going to study''.","Usar ''going to'' para decisões rápidas: ''I am going to call him now'' quando a decisão é imediata, mas o correto é ''I will call him now''.","Esquecer de usar o verbo na forma base depois de ''will'': ''She will goes'' → ''She will go''.","Usar ''will'' para planos já decididos: ''I will travel next month'' quando o plano já existe, o certo é ''I am going to travel next month''."]'::jsonb, '["No inglês falado, ''going to'' muitas vezes vira ''gonna'', mas na escrita formal use ''going to''.","''Will'' não muda com o sujeito: he will, she will, they will.","Use contrações: ''I''ll'', ''you''ll'', ''he''ll'', etc."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

