insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-ed4ab5ca8a41', 'en', 'A2', 'Comparatives and Superlatives in English', 'Nesta lição, você vai aprender a comparar pessoas, lugares e coisas em inglês usando comparativos (ex.: ''bigger'') e superlativos (ex.: ''the biggest''). Isso ajuda a falar sobre diferenças e extremos. Vamos focar em adjetivos curtos e longos, e em formas irregulares comuns.', 'Para adjetivos curtos (1 sílaba): adicione ''-er'' para comparativo (ex.: ''fast'' -> ''faster'') e ''-est'' para superlativo (ex.: ''fast'' -> ''the fastest''). Para adjetivos longos (2+ sílabas): use ''more'' + adjetivo (ex.: ''beautiful'' -> ''more beautiful'') e ''the most'' + adjetivo (ex.: ''the most beautiful''). Alguns adjetivos são irregulares: ''good'' -> ''better'' -> ''the best''; ''bad'' -> ''worse'' -> ''the worst''. Use ''than'' depois do comparativo (ex.: ''She is taller than me.'') e ''the'' antes do superlativo (ex.: ''He is the tallest in the class.'').', '["Comparar duas coisas ou pessoas: ''My car is faster than yours.''","Falar sobre o extremo em um grupo: ''This is the most interesting book.''","Expressar preferência: ''I like coffee better than tea.''","Descrever mudanças: ''The weather is getting worse.''"]'::jsonb, '["Usar ''more'' com adjetivos curtos: ''more big'' (errado) -> ''bigger'' (certo).","Esquecer ''the'' antes do superlativo: ''This is biggest city'' (errado) -> ''This is the biggest city'' (certo).","Usar ''than'' após superlativo: ''She is the best than me'' (errado) -> ''She is the best'' (certo).","Esquecer mudanças ortográficas: ''big'' -> ''bigger'' (não ''biger'')."]'::jsonb, '["Adjetivos de duas sílabas terminados em ''-y'' mudam para ''-ier'': ''happy'' -> ''happier''.","Use ''as...as'' para igualdade: ''He is as tall as me.''","O superlativo geralmente usa ''the'' antes: ''the most expensive''.","Com adjetivos curtos que terminam em consoante-vogal-consoante, dobre a consoante: ''big'' -> ''bigger''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

