insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-056aa1734ab5', 'en', 'A2', 'Frequency and Manner Adverbs', 'Nesta lição, você vai aprender a usar advérbios de frequência (como ''always'', ''usually'') e de modo (como ''quickly'', ''carefully'') em inglês. Esses advérbios ajudam a dizer com que frequência você faz algo e como você faz. São muito comuns no dia a dia.', 'Advérbios de frequência geralmente vêm antes do verbo principal, mas depois do verbo ''to be''. Advérbios de modo geralmente vêm depois do verbo ou do objeto, mas antes do particípio passado. Eles são formados frequentemente adicionando ''-ly'' a adjetivos (ex.: ''quick'' -> ''quickly'').', '["Para dizer com que frequência uma ação acontece.","Para descrever como uma ação é feita."]'::jsonb, '["Colocar o advérbio de frequência no lugar errado (ex.: ''I go always'' em vez de ''I always go'').","Esquecer de adicionar ''-ly'' ao formar advérbios de modo (ex.: ''He runs quick'' em vez de ''He runs quickly'')."]'::jsonb, '["''Hard'' e ''fast'' são advérbios irregulares: não usamos ''hardly'' para ''difícil'', usamos ''hard''.","''Hardly'' significa ''quase não''.","Alguns advérbios de frequência: always (sempre), usually (geralmente), often (frequentemente), sometimes (às vezes), rarely (raramente), never (nunca)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

