insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-cd020ba626b3', 'en', 'A2', 'Countable and Uncountable Nouns: How Much vs. How Many', 'Nesta lição, você vai aprender a diferença entre substantivos contáveis e incontáveis em inglês e como usar ''how much'' e ''how many'' para fazer perguntas sobre quantidade. Isso é essencial para conversas do dia a dia, como fazer compras ou pedir comida.', 'Use ''how many'' com substantivos contáveis (ex.: apples, books) e ''how much'' com substantivos incontáveis (ex.: water, money). A estrutura é: How many + substantivo plural + verbo? / How much + substantivo incontável + verbo? Exemplos: ''How many apples do you have?'' e ''How much water is there?''', '["Perguntar sobre números de itens contáveis: How many books are on the table?","Perguntar sobre quantidades de substâncias ou conceitos abstratos: How much sugar do you want?","Em respostas curtas: How many? -> There are three. / How much? -> There is a lot.","Com palavras como some, any, a lot of, much, many para expressar quantidades.","Em compras: How much does this cost? (mas aqui ''how much'' é usado para preço)","Oferecendo coisas: How much rice do you need?"]'::jsonb, '["Usar ''how much'' com substantivos contáveis: Incorreto: How much apples? -> Correto: How many apples?","Usar ''how many'' com substantivos incontáveis: Incorreto: How many water? -> Correto: How much water?","Esquecer de usar a forma plural com ''how many'': Incorreto: How many book? -> Correto: How many books?","Confundir ''much'' e ''many'' em frases afirmativas: É mais comum usar ''a lot of'', não ''much'' ou ''many'' em frases afirmativas informais."]'::jsonb, '["Substantivos contáveis têm forma plural, enquanto incontáveis não têm.","Para perguntar sobre preço, sempre use ''how much''.","Em perguntas, ''much'' e ''many'' são muito comuns; em afirmativas, use ''a lot of''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

