insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-4b195693fe1f', 'en', 'A2', 'Relative Clauses with Who, Which, That', 'As orações relativas (relative clauses) são usadas para dar informações extras sobre uma pessoa, coisa ou lugar. Nesta lição, você vai aprender a usar ''who'' para pessoas, ''which'' para coisas e ''that'' para pessoas ou coisas. Você também vai ver como formar frases com essas palavras.', 'Para formar uma oração relativa, você coloca ''who'', ''which'' ou ''that'' depois do substantivo que você quer descrever. ''Who'' é usado para pessoas, ''which'' para coisas, e ''that'' pode ser usado para ambos. Exemplos: ''The woman who lives next door is a doctor.'' (A mulher que mora ao lado é médica.) ''The book which is on the table is mine.'' (O livro que está na mesa é meu.) ''The car that I bought is red.'' (O carro que comprei é vermelho.)', '["Use ''who'' para pessoas: ''I have a friend who speaks three languages.''","Use ''which'' para coisas e animais: ''This is the house which my grandfather built.''","Use ''that'' para pessoas ou coisas em situações informais: ''The cake that you made is delicious.''","Use orações relativas para identificar ou dar informações extras: ''The students who study hard pass the exam.''"]'::jsonb, '["Usar ''which'' para pessoas: Errado: ''The woman which lives here is nice.'' Certo: ''The woman who lives here is nice.''","Usar ''who'' para coisas: Errado: ''The book who is on the table.'' Certo: ''The book which is on the table.'' ou ''The book that is on the table.''","Esquecer de colocar o pronome relativo: Errado: ''The man is tall is my father.'' Certo: ''The man who is tall is my father.''"]'::jsonb, '["Em inglês, ''that'' é muito comum na fala e na escrita informal.","Em orações relativas com ''which'' e ''that'', a vírgula pode mudar o sentido. Sem vírgula, a oração é essencial; com vírgula, é extra."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

