insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-725cda591ace', 'en', 'A2', 'Present Continuous: Actions Happening Now', 'O Present Continuous (ou Present Progressive) é usado para falar de ações que estão acontecendo no momento da fala. Nesta lição, você vai aprender a formar e usar esse tempo verbal em inglês, com foco em situações do dia a dia.', 'Formação: sujeito + verbo ''to be'' (am/is/are) + verbo principal com -ing. Exemplos: I am studying. / She is reading. / They are playing. Para negativas, adicione ''not'' após o verbo ''to be''. Para perguntas, inverta o sujeito e o verbo ''to be''.', '["Ações que estão acontecendo agora","Ações temporárias ao redor do momento atual","Planos futuros já combinados"]'::jsonb, '["Esquecer o verbo ''to be'' antes do verbo principal","Usar o presente simples em vez do contínuo para ações em progresso","Errar a forma do gerúndio (ex.: ''swiming'' em vez de ''swimming'')"]'::jsonb, '["Verbos que terminam em ''e'' geralmente perdem o ''e'' antes de adicionar -ing (ex.: make -> making).","Verbos monossilábicos com CVC (consoante-vogal-consoante) dobram a última consoante (ex.: run -> running).","Alguns verbos não são usados no contínuo, como ''like'', ''want'', ''know''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

