insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-a76a0ac7d527', 'en', 'A2', 'Going to vs. Will', 'Nesta lição, você vai aprender a diferença entre ''going to'' e ''will'' para falar sobre o futuro. Vamos ver quando usar cada um e como formar frases corretamente.', 'Para formar o futuro com ''going to'', use: sujeito + verbo ''to be'' (am, is, are) + ''going to'' + verbo principal. Exemplo: ''I am going to travel.'' Para ''will'', use: sujeito + ''will'' + verbo principal. Exemplo: ''She will call you.''', '["Usamos ''going to'' para planos e intenções futuras: ''I''m going to visit my family.''","Usamos ''going to'' para previsões baseadas em evidências atuais: ''Look at the clouds! It''s going to rain.''","Usamos ''will'' para decisões espontâneas: ''I''ll have a coffee, please.''","Usamos ''will'' para promessas e ofertas: ''I will help you with your homework.''","Usamos ''will'' para previsões gerais sem evidência: ''I think Brazil will win the game.''"]'::jsonb, '["Esquecer de usar o verbo ''to be'' antes de ''going to'': ''I going to travel'' (errado).","Usar ''will'' com ''going to'' juntos: ''I will going to study'' (errado).","Usar ''going to'' para decisões espontâneas, em vez de ''will''.","Esquecer de usar a forma base do verbo depois de ''will'' e ''going to''."]'::jsonb, '["Em conversas informais, ''going to'' pode ser reduzido para ''gonna'', mas evite isso na escrita formal.","''Will'' pode ser contraído com o sujeito, como em ''I''ll'' ou ''she''ll''.","Ambos ''going to'' e ''will'' podem ser usados para o futuro, mas a escolha depende do contexto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-en-a2-a76a0ac7d527-exercise-01', 'en', 'A2', 'Escolha a opção correta', 'Complete a frase com a forma correta do futuro.', 'I ______ (go) to the beach tomorrow.', 'Qual é a frase correta?', '["I will going to the beach tomorrow.","I am going to go to the beach tomorrow.","I going to go to the beach tomorrow.","I will go to the beach tomorrow."]'::jsonb, 1, 1, true, 'generated-grammar-en-a2-a76a0ac7d527')
on conflict (id) do update set title=excluded.title, explanation=excluded.explanation, example=excluded.example, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, is_published=excluded.is_published, topic_id=excluded.topic_id, updated_at=now();

