insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-037fd43bf32c', 'en', 'A2', 'Comparatives and Superlatives', 'Nesta lição, você vai aprender a comparar pessoas, lugares e coisas em inglês, e também a falar de extremos. Você vai ver como formar comparativos (mais... que) e superlativos (o/a mais...).', 'Para formar o comparativo, use ''er'' em adjetivos curtos (ex: tall -> taller) ou ''more'' em adjetivos longos (ex: beautiful -> more beautiful). Para o superlativo, use ''est'' (the tallest) ou ''most'' (the most beautiful).', '["Comparar duas coisas ou pessoas: ''My brother is taller than me.''","Falar de extremos: ''She is the best student in the class.''","Expressar preferências: ''I like tea more than coffee.''","Descrever mudanças: ''The city is getting more crowded.''"]'::jsonb, '["Usar ''more'' com adjetivos curtos: ''more big'' (errado) -> ''bigger'' (certo).","Esquecer ''the'' antes do superlativo: ''She is best'' -> ''She is the best''.","Confundir ''than'' e ''then'': ''He is taller than me.''","Usar ''more'' em vez de ''er'' para palavras de uma sílaba."]'::jsonb, '["Adjetivos terminados em ''y'' viram ''ier'' (happy -> happier).","Alguns comparativos e superlativos são irregulares: good -> better -> the best; bad -> worse -> the worst.","Use ''as... as'' para comparar igualdade: ''He is as tall as me.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

