insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-7a725cd1bae5', 'en', 'A2', 'Frequency and Manner Adverbs', 'Nesta lição, você vai aprender a usar advérbios de frequência e modo em inglês. Esses advérbios ajudam a dizer com que frequência você faz algo (como ''always'' ou ''sometimes'') e como você faz algo (como ''quickly'' ou ''carefully''). Eles são muito comuns no dia a dia e vão deixar seu inglês mais natural.', 'Advérbios de frequência (always, usually, often, sometimes, rarely, never) geralmente vêm antes do verbo principal, mas depois do verbo ''to be''. Exemplos: She always drinks coffee. (Ela sempre bebe café.) He is usually happy. (Ele geralmente está feliz.) Advérbios de modo (quickly, slowly, carefully, well, badly) geralmente vêm depois do verbo ou depois do objeto. Exemplos: She speaks English well. (Ela fala inglês bem.) He drives carefully. (Ele dirige com cuidado.)', '["Para dizer com que frequência você faz algo: I always brush my teeth.","Para descrever como uma ação é feita: She sings beautifully.","Para perguntar sobre frequência: How often do you exercise?","Para responder sobre frequência: I usually go to the gym twice a week."]'::jsonb, '["Colocar o advérbio de frequência antes do verbo ''to be'' incorretamente: ''She is always late'' (correto) vs ''She always is late'' (errado).","Usar o advérbio de modo entre o verbo e o objeto: ''She speaks well English'' (errado) vs ''She speaks English well'' (correto).","Confundir ''hardly'' (quase não) com ''hard'' (difícil ou intensamente): ''He works hardly'' (errado) vs ''He works hard'' (correto)."]'::jsonb, '["Lembre-se: advérbios de frequência geralmente vão antes do verbo principal, mas depois de ''am'', ''is'', ''are'', ''was'', ''were''.","Advérbios de modo podem vir antes do verbo para dar ênfase: ''She quickly left the room.''","Para fazer perguntas com ''how often'', use: How often + do/does + sujeito + verbo?","A posição do advérbio pode mudar o significado da frase, então preste atenção ao contexto."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

