insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-729037cf8e99', 'en', 'A2', 'Countable and Uncountable Nouns: How Much vs. How Many', 'Nesta lição, você vai aprender a diferença entre substantivos contáveis e incontáveis em inglês e como usar ''how much'' e ''how many'' para fazer perguntas sobre quantidade. Isso é essencial para conversas do dia a dia, como fazer compras ou pedir comida.', 'Use ''how many'' com substantivos contáveis no plural (ex.: apples, bottles). Use ''how much'' com substantivos incontáveis (ex.: water, money). Em frases afirmativas e negativas, use ''some'' e ''any'' respectivamente. Exemplos: ''How many apples do you have?'' e ''How much water is there?''', '["Para perguntar sobre números de itens contáveis: How many books do you have?","Para perguntar sobre quantidades de substâncias ou conceitos incontáveis: How much sugar do you want?","Para oferecer ou pedir coisas: I have some money. Do you have any water?","Para expressar quantidade com palavras como ''a lot of'', ''a little'', ''a few''."]'::jsonb, '["Usar ''how much'' com contáveis: How much apples? (errado) → How many apples?","Usar ''how many'' com incontáveis: How many water? (errado) → How much water?","Usar ''some'' em perguntas: Do you have some money? (informal) → mais comum: any","Esquecer o plural após ''how many'': How many book? (errado) → How many books?"]'::jsonb, '["Lembre-se: ''many'' para coisas que você pode contar (one, two, three...).","''much'' para coisas que você não pode contar individualmente, como líquidos, materiais e abstrações.","Em frases afirmativas, use ''some''; em negativas e perguntas, use ''any''.","Para quantidades grandes, use ''a lot of'' com ambos os tipos.","Pratique com alimentos e bebidas, que são comuns no cotidiano."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

