insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-826adb112601', 'en', 'A2', 'Should, Must, Have to, May', 'Nesta lição, você vai aprender a usar os verbos modais should, must, have to e may em inglês. Eles ajudam a dar conselhos, expressar obrigação e pedir permissão. Vamos ver como usá-los no dia a dia!', 'Os modais são seguidos do verbo principal na forma base, sem ''to'' (exceto ''have to''). Eles não mudam com o sujeito (he, she, it). Exemplos: ''You should study.'' (dar conselho); ''He must go.'' (obrigação); ''We have to work.'' (obrigação externa); ''May I come in?'' (permissão). A forma negativa: ''should not'', ''must not'', ''do not have to'' (não precisa), ''may not''.', '["Should: conselhos e sugestões. Ex: ''You should drink water.''","Must: obrigação forte, regra ou necessidade. Ex: ''You must stop at the red light.''","Have to: obrigação externa (regras, trabalho). Ex: ''I have to wear a uniform at work.''","May: pedir ou dar permissão, ou possibilidade. Ex: ''May I use your phone?'' / ''It may rain today.''"]'::jsonb, '["Não use ''to'' depois de should, must, may. Errado: ''I must to go.''","Não use ''s'' na terceira pessoa com modais. Errado: ''He shoulds study.''","Confundir ''must not'' (proibido) com ''do not have to'' (não é obrigatório).","Usar ''may'' para dar conselhos. Para conselhos, use ''should''."]'::jsonb, '["Para perguntar sobre obrigação, use ''Do I have to...?'' ou ''Must I...?'' (mais formal).","Em inglês britânico, ''shall'' pode ser usado como ''should'', mas em A2 focamos em ''should''.","Lembre-se: ''have to'' é um verbo normal, então precisa de ''do/does'' em perguntas e negativas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

