insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-be9e5933ea30', 'en', 'A2', 'Basic Connectors: and, but, or, so, because', 'Nesta lição, você vai aprender a usar conectores básicos em inglês: ''and'', ''but'', ''or'', ''so'' e ''because''. Essas palavras ajudam a conectar ideias e formar frases mais completas. Você verá como usá-las em situações do dia a dia, como falar sobre rotina, preferências e planos.', 'Os conectores são usados para ligar palavras, frases ou orações. Eles geralmente aparecem no meio da frase, entre duas ideias. ''And'' adiciona informações; ''but'' mostra contraste; ''or'' apresenta alternativas; ''so'' indica consequência; ''because'' dá razão. Exemplo: ''I like coffee, but she likes tea.''', '["Usamos ''and'' para adicionar informações: ''I have a dog and a cat.''","Usamos ''but'' para mostrar contraste: ''He is rich, but he is not happy.''","Usamos ''or'' para apresentar opções: ''Do you want tea or coffee?''","Usamos ''so'' para indicar resultado: ''I was tired, so I went to bed.''","Usamos ''because'' para explicar o motivo: ''I stayed home because it was raining.''"]'::jsonb, '["Confundir ''but'' e ''because'': ''I''m tired but I need to study'' (contraste) vs. ''I''m tired because I studied a lot'' (razão).","Usar ''so'' e ''because'' juntos na mesma frase: ''I was hungry so because I ate.'' (errado) -> ''I was hungry, so I ate.''","Esquecer a vírgula antes do conector quando une duas orações: ''I like music and I play guitar.'' (errado) -> ''I like music, and I play guitar.''","Usar ''or'' em frases negativas: ''I don''t like tea or coffee.'' (certo) e ''I don''t like tea or coffee.'' (certo) mas não ''I don''t like tea nor coffee'' (errado para A2)"]'::jsonb, '["Em inglês, ''because'' pode iniciar a frase: ''Because it was raining, I stayed home.''","Em conversas informais, ''so'' pode ser usado no início para perguntar sobre algo: ''So, what do you think?''","Na linguagem falada, é comum usar contrações como ''don''t'' para ''do not''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

