insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-f6071dcbe40d', 'en', 'A2', 'Present Continuous: Actions Now', 'O Present Continuous (presente contínuo) é usado para falar sobre ações que estão acontecendo agora, no momento da fala, ou sobre planos futuros já combinados. Aprender esse tempo verbal é essencial para descrever o que você e outras pessoas estão fazendo no dia a dia.', 'O Present Continuous é formado com o verbo ''to be'' (am, is, are) + o verbo principal com ''-ing''. Exemplo: ''I am studying'' (Eu estou estudando). Para a forma negativa, adiciona-se ''not'' após o verbo ''to be''. Para perguntas, inverte-se a ordem: ''Are you studying?''.', '["Ações em andamento no momento da fala: ''I am reading a book.''","Ações temporárias: ''She is staying with her sister this week.''","Planos futuros: ''We are traveling to Rio on Saturday.''"]'::jsonb, '["Esquecer o verbo ''to be'': ''I studying'' em vez de ''I am studying''.","Usar o presente simples para ações que estão ocorrendo agora: ''I study'' em vez de ''I am studying''.","Errar a forma do gerúndio: ''writeing'' em vez de ''writing''."]'::jsonb, '["A forma negativa: ''I am not working.''","A forma interrogativa: ''What are you doing?''","Alguns verbos não são usados no contínuo, como ''know'', ''like'', ''want''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

