insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-72e1936ea478', 'en', 'A2', 'Going to vs. Will', 'Nesta lição, você vai aprender a diferença entre ''going to'' e ''will'' para falar sobre o futuro. ''Going to'' é usado para planos e intenções, e ''will'' para decisões espontâneas, previsões e promessas. Vamos ver como formar frases e quando usar cada um.', 'Para formar o futuro com ''going to'', use: sujeito + verbo ''to be'' (am/is/are) + going to + verbo base. Exemplo: ''I am going to travel.'' Para ''will'', use: sujeito + will + verbo base. Exemplo: ''She will call you.''', '["Usamos ''going to'' para planos e intenções já decididos antes de falar.","Usamos ''going to'' para previsões baseadas em evidências visíveis.","Usamos ''will'' para decisões tomadas no momento da fala.","Usamos ''will'' para previsões sem evidência concreta, baseadas em opinião.","Usamos ''will'' para promessas, ofertas e pedidos."]'::jsonb, '["Não use ''going to'' com ''will'' juntos: ''I will going to go'' (errado).","Não esqueça o verbo ''to be'' antes de ''going to'': ''She going to study'' (errado).","Com ''will'', o verbo principal fica na forma base, sem ''to''."]'::jsonb, '["Na fala informal, ''going to'' muitas vezes vira ''gonna''.","Contrações comuns: ''I will'' = ''I''ll'', ''she is going to'' = ''she''s going to''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

