insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-0280f8c21a03', 'en', 'A2', 'Countable and Uncountable Nouns: How Much or How Many?', 'Nesta lição, você vai aprender a diferença entre substantivos contáveis e incontáveis em inglês e como usar ''how much'' e ''how many'' para fazer perguntas sobre quantidade. Isso é essencial para conversas do dia a dia, como fazer compras ou pedir comida.', 'Use ''how many'' com substantivos contáveis (que podem ser contados, como ''apples'') e ''how many'' + substantivo plural. Use ''how much'' com substantivos incontáveis (que não podem ser contados individualmente, como ''water'') e ''how much'' + substantivo no singular. Exemplos: ''How many books do you have?'' e ''How much money do you need?''.', '["Perguntar sobre a quantidade de itens contáveis: How many apples do you want?","Perguntar sobre a quantidade de coisas incontáveis: How much sugar do we have?","Expressar falta ou abundância: There are not many chairs. There is too much noise."]'::jsonb, '["Usar ''how much'' com contáveis: Incorreto: How much bottles? Correto: How many bottles?","Usar ''how many'' com incontáveis: Incorreto: How many water? Correto: How much water?","Esquecer o plural após ''how many'': Incorreto: How many book? Correto: How many books?"]'::jsonb, '["Substantivos como ''bread'', ''cheese'' e ''money'' são incontáveis em inglês, mesmo que em português possam ser contados.","Usamos ''a glass of'', ''a piece of'' etc. para contar incontáveis: ''two glasses of water''.","Em frases negativas, usamos ''not much'' e ''not many''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

