insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-28db803eb053', 'en', 'A2', 'Should, Must, Have to, May: Modals of Advice, Obligation, and Permission', 'Nesta lição, você vai aprender a usar os verbos modais should, must, have to e may. Eles ajudam a dar conselhos, falar de obrigações e pedir permissão. Vamos ver como usá-los no dia a dia.', 'Os modais são seguidos do verbo principal na forma base (sem ''to'' para should, must, may; com ''to'' para have to). Exemplos: You should study. You must pay. You have to go. May I come in?', '["Should: para dar conselhos ou sugestões.","Must: para obrigações fortes, regras ou necessidade.","Have to: para obrigações externas (por exemplo, leis ou trabalho).","May: para pedir ou dar permissão formal."]'::jsonb, '["Usar ''to'' depois de should: ''I should to go'' (errado).","Usar ''must'' com ''to'': ''I must to go'' (errado).","Confundir ''must'' e ''have to'' em contextos informais.","Usar ''may'' em perguntas informais com amigos (mais comum ''can'')."]'::jsonb, '["A forma negativa de must é ''mustn''t'' (proibição).","A forma negativa de have to é ''don''t have to'' (não é necessário).","May é muito formal; no dia a dia, prefira ''can'' para permissão."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

