insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-en-a2-bc338f70d96f', 'en', 'A2', 'Using -ing: Gerunds and Present Participles', 'Nesta lição, você vai aprender sobre o uso de verbos terminados em ''-ing'' em inglês. Vamos ver duas funções principais: quando o ''-ing'' é usado como um substantivo (gerúndio) e quando é usado como parte do presente contínuo. Isso ajudará você a formar frases mais naturais e a entender melhor a estrutura das frases em inglês.', 'Para formar o gerúndio ou o particípio presente, adicione ''-ing'' ao verbo base. Por exemplo, ''work'' vira ''working'', ''play'' vira ''playing''. Se o verbo termina com ''e'', remova o ''e'' e adicione ''-ing'': ''make'' vira ''making'', ''write'' vira ''writing''. Se o verbo tem uma sílaba com padrão consoante-vogal-consoante e é curto, dobre a última consoante: ''sit'' vira ''sitting'', ''run'' vira ''running''.', '["Usamos o gerúndio depois de preposições, como ''interested in'', ''good at''.","Usamos o gerúndio depois de certos verbos como ''enjoy'', ''like'', ''love'', ''hate'', ''finish''.","Usamos o gerúndio como sujeito da frase, como ''Swimming is good for you''.","Usamos o presente contínuo (be + -ing) para ações que estão acontecendo no momento da fala."]'::jsonb, '["Usar o infinitivo em vez do gerúndio: ''I enjoy to read'' (errado) → ''I enjoy reading'' (correto).","Esquecer de usar ''be'' no presente contínuo: ''I working now'' (errado) → ''I am working now'' (correto).","Usar o gerúndio em vez do infinitivo após certos verbos como ''want'': ''I want going'' (errado) → ''I want to go'' (correto)."]'::jsonb, '["Em inglês, o gerúndio e o particípio presente têm a mesma forma (verbo + -ing), mas funções diferentes.","Alguns verbos podem ser seguidos por gerúndio ou infinitivo, mas com mudança de significado, como ''stop'' e ''remember''.","O presente contínuo é usado também para planos futuros, como ''I am meeting my friends tomorrow''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

