insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-9e138fefd288', 'es', 'A2', 'Reflexivos Básicos en Español', 'Nesta lição, você vai aprender a usar os verbos reflexivos básicos em espanhol. Eles são usados para ações que a pessoa faz a si mesma, como lavar-se ou vestir-se. Vamos ver como se formam e quando usá-los no dia a dia.', 'Para formar um verbo reflexivo, usamos o pronome reflexivo antes do verbo conjugado. O pronome muda conforme a pessoa: me (yo), te (tú), se (él/ella/usted), nos (nosotros), os (vosotros), se (ellos/ellas/ustedes). Exemplo: ''yo me lavo'', ''tú te vistes'', ''él se ducha''.', '["Para ações diárias: levantar-se, lavar-se, vestir-se.","Para ações que envolvem o corpo: cortar-se, machucar-se.","Para mudanças de estado ou emoção: enojarse, alegrarse.","Para ações recíprocas (quando duas pessoas fazem algo uma à outra): abrazarse, besarse."]'::jsonb, '["Esquecer de usar o pronome reflexivo: ''yo lavo'' em vez de ''yo me lavo''.","Usar o pronome reflexivo com verbos não reflexivos: ''yo me tengo'' em vez de ''yo tengo''.","Confundir a posição do pronome: ''me lavo yo'' em vez de ''yo me lavo''.","Usar ''se'' para todas as pessoas: ''yo se lavo'' em vez de ''yo me lavo''."]'::jsonb, '["Alguns verbos mudam de significado quando são reflexivos. Por exemplo, ''ir'' (ir) e ''irse'' (ir embora).","Na forma negativa, o pronome fica antes do verbo: ''No me levanto tarde''.","Com o infinitivo, o pronome pode ficar no final: ''Voy a bañarme'' ou ''Me voy a bañar''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

