insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-081c7d7286d7', 'es', 'A2', 'Por vs Para: Uso y Diferencias', 'Nesta lição, você vai aprender a diferença entre ''por'' e ''para'', duas preposições em espanhol que podem ser confusas. Vamos ver os usos principais de cada uma e praticar com exercícios.', 'Ambas são preposições, mas ''por'' é usado para causa, motivo, duração, meio, e troca, enquanto ''para'' é usado para finalidade, destino, prazo e opinião. Memorize as regras e pratique com exemplos.', '["POR: causa ou motivo: ''Lo hice por amor''.","POR: duração de tempo: ''Estudié por dos horas''.","POR: meio de transporte ou comunicação: ''Viajamos por avião''.","POR: troca ou preço: ''Lo compré por diez euros''.","PARA: finalidade ou objetivo: ''Estudio para aprender''.","PARA: destino: ''Este regalo es para ti''.","PARA: prazo: ''La tarea es para mañana''.","PARA: opinião: ''Para mí, es difícil''."]'::jsonb, '["Confundir ''por'' e ''para'' em frases com finalidade: ''Voy por comida'' (errado) vs. ''Voy para comprar comida'' (correto).","Usar ''por'' em vez de ''para'' para indicar prazo: ''Necesito esto por mañana'' (errado) vs. ''Necesito esto para mañana'' (correto).","Usar ''para'' em vez de ''por'' para expressar causa: ''Estoy triste para ti'' (errado) vs. ''Estoy triste por ti'' (correto)."]'::jsonb, '["Lembre que ''para'' também pode indicar direção (ir para) e destinatário.","Em alguns contextos, ''por'' pode ser usado com verbos como ''buscar'', ''preguntar''.","Pratique com frases do dia a dia para fixar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

