insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-9f0c50963109', 'es', 'A2', 'El pretérito indefinido: acciones pasadas completas', 'O pretérito indefinido (ou pretérito perfeito simples) é usado para falar de ações concluídas no passado. Em português, corresponde ao pretérito perfeito, como ''eu comi'', ''você falou''. Nesta lição, você vai aprender a formar e usar esse tempo verbal.', 'Para formar o pretérito indefinido, remova as terminações -ar, -er, -ir do infinitivo e adicione as seguintes terminações: Para verbos -ar: -é, -aste, -ó, -amos, -asteis, -aron. Exemplo: hablar (falar) -> hablé, hablaste, habló, hablamos, hablasteis, hablaron. Para verbos -er/-ir: -í, -iste, -ió, -imos, -isteis, -ieron. Exemplo: comer (comer) -> comí, comiste, comió, comimos, comisteis, comieron; vivir (viver) -> viví, viviste, vivió, vivimos, vivisteis, vivieron. Atenção aos verbos irregulares como ser/ir (fui, fuiste, fue, fuimos, fuisteis, fueron) e estar (estuve, estuviste, estuvo, estuvimos, estuvisteis, estuvieron).', '["Ações concluídas no passado, como ''Ayer comí pizza.''","Sequência de ações no passado, como ''Entré, saludé y me senté.''","Fatos históricos, como ''Colón llegó a América en 1492.''","Ações com duração definida no passado, como ''Viví en Brasil por cinco años.''"]'::jsonb, '["Confundir com o pretérito imperfecto (usado para ações contínuas ou habituais).","Errar nas terminações, como dizer ''yo comió'' em vez de ''yo comí''.","Não usar acentos nas formas como ''habló'', ''comió''."]'::jsonb, '["O pretérito indefinido é comum em narrativas e biografias.","Palavras como ''ayer'', ''anoche'', ''la semana pasada'' são frequentes com esse tempo.","Verbos reflexivos também são conjugados normalmente, como ''me levanté''.","A forma ''vosotros'' é usada na Espanha; na América Latina, usa-se ''ustedes''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

