insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-5edc097eb274', 'es', 'A2', 'El Imperfecto: Hablando del Pasado en Español', 'O pretérito imperfeito é um tempo verbal usado para descrever ações passadas que eram contínuas, habituais ou que serviam de cenário para outras ações. Nesta lição, você vai aprender como formar o imperfeito e quando usá-lo, para poder contar histórias e falar sobre hábitos do passado.', 'Para formar o pretérito imperfeito, pegue o verbo no infinitivo, remova a terminação (-ar, -er, -ir) e adicione as terminações: para verbos -ar: -aba, -abas, -aba, -ábamos, -abais, -aban. Para verbos -er e -ir: -ía, -ías, -ía, -íamos, -íais, -ían. Exemplos: hablar -> hablaba, hablar; comer -> comía, comías; vivir -> vivía, vivíamos. Os verbos irregulares são poucos: ser (era, eras, era), ir (iba, ibas, iba), ver (veía, veías, veía).', '["Descrever ações habituais no passado (ex: ''Cuando era niño, jugaba fútbol todos los días.'')","Descrever ações contínuas no passado (ex: ''Mientras leía, sonaba la música.'')","Descrever características físicas ou emocionais no passado (ex: ''Mi abuela era muy alta.'')","Dar informações de fundo em narrativas (ex: ''Era de noche y llovía.'')"]'::jsonb, '["Confundir o pretérito imperfeito com o pretérito indefinido (ex: usar ''hablé'' em vez de ''hablaba'' para ações repetidas).","Esquecer as formas irregulares de ''ser'', ''ir'' e ''ver''.","Usar a forma de presente do verbo em vez do imperfeito (ex: ''yo hablo'' em vez de ''yo hablaba'').","Adicionar acento na primeira pessoa plural (-ábamos) mas esquecer nas outras pessoas (ex: ''hablabamos'' sem acento)."]'::jsonb, '["O pretérito imperfeito também é usado para expressar idade no passado (ex: ''Tenía diez años cuando...'').","Costuma ser usado com expressões temporais como ''cuando era niño'', ''todos los días'', ''siempre''.","É um tempo verbal muito comum em narrativas e biografias."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

