insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-232f1a29084e', 'es', 'A2', 'Comparações e Quantidade', 'Nesta lição, você vai aprender a comparar pessoas, objetos e lugares, e a falar sobre quantidades. Vamos estudar as formas comparativas e superlativas, e palavras como ''muito'', ''pouco'', ''bastante'', entre outras. Isso vai te ajudar a descrever o mundo ao seu redor com mais precisão.', 'Para comparar, usamos:
- ''más ... que'' para mais: ''Ella es más alta que yo.''
- ''menos ... que'' para menos: ''Este libro es menos interesante que el otro.''
- ''tan ... como'' para igualdade: ''Él es tan inteligente como su hermano.''
- Superlativos: ''el/la más + adjetivo'' ou ''el/la menos + adjetivo'': ''Es el más rápido del equipo.''
Para quantidade, usamos:
- ''muy'' antes de adjetivos/adverbios: ''muy grande'', ''muy rápido''
- ''mucho, mucha, muchos, muchas'' antes de substantivos: ''mucho tiempo'', ''muchas casas''
- ''poco, poca, pocos, pocas'': ''poca agua'', ''pocos amigos''
- ''bastante, bastantes'': ''bastante dinero'', ''bastantes problemas''', '["Comparar duas coisas ou pessoas: ''Mi casa es más grande que la tuya.''","Expressar igualdade: ''Esta película es tan buena como la otra.''","Falar de quantidade: ''Tengo muchos libros en casa.''","Usar superlativos para destacar: ''Ella es la mejor estudiante de la clase.''"]'::jsonb, '["Confundir ''muy'' e ''mucho'': ''muy'' antes de adjetivo, ''mucho'' antes de substantivo.","Esquecer a concordância de gênero e número: ''muchas gracias'' (não ''mucho gracias'').","Usar ''que'' após ''tan'' (deve ser ''como''): ''tan alto como'' (não ''tan alto que'').","Colocar ''más'' e ''menos'' no lugar errado: ''más interesante'' (não ''interesante más'')."]'::jsonb, '["As formas comparativas podem ser usadas com advérbios também: ''corre más rápido que yo''.","Os superlativos podem ser relativos (dentro de um grupo) ou absolutos (muito + adjetivo, como -ísimo).","Cuidado com as irregularidades: ''bueno'' -> ''mejor'', ''malo'' -> ''peor'', ''grande'' -> ''mayor'' (para idade), ''pequeño'' -> ''menor''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

