insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-e1878dd3286e', 'es', 'A2', 'El Imperativo Informal en Español', 'Nesta aula, você vai aprender a dar ordens, fazer pedidos e dar conselhos de forma amigável usando o imperativo informal (tú). Vamos ver como formar os verbos regulares e alguns irregulares comuns, com exemplos do dia a dia.', 'Para formar o imperativo afirmativo com ''tú'', use a terceira pessoa do singular (él/ella) no presente do indicativo. Por exemplo: ''hablar'' → ''habla'', ''comer'' → ''come'', ''escribir'' → ''escribe''. Alguns verbos irregulares: ''tener'' → ''ten'', ''venir'' → ''ven'', ''decir'' → ''di'', ''hacer'' → ''haz'', ''poner'' → ''pon'', ''salir'' → ''sal''. Para a forma negativa, use ''no'' + a forma do presente do subjuntivo: ''no hables'', ''no comas'', ''no escribas''.', '["Dar órdenes claras: ''¡Abre la puerta!''","Fazer pedidos educados: ''Por favor, trae el menú.''","Dar conselhos: ''Descansa un poco.''","Fazer convites: ''Ven a mi casa hoy.''"]'::jsonb, '["''Hablás'' em vez de ''Habla'' – a forma correta é ''habla''.","''Coméis'' em vez de ''Come'' – use ''come'' para tú.","Confundir ''tener'' → ''ten'' com ''tiene'' – no imperativo, use ''ten''.","Usar a forma do subjuntivo no afirmativo: ''hables'' em vez de ''habla''."]'::jsonb, '["O imperativo afirmativo para ''tú'' é igual à terceira pessoa do singular.","Na forma negativa, é obrigatório usar ''no'' antes do verbo.","Alguns verbos têm formas curtas irregulares: ''haz'', ''di'', ''ven''.","O imperativo é muito comum em receitas, instruções e conversas do dia a dia."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

