insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-56dec6f0c975', 'es', 'A2', 'Por vs Para: Usos Esenciales', 'Nesta lição, você vai aprender a diferença entre ''por'' e ''para'', duas preposições em espanhol que muitas vezes confundem os estudantes. Vamos ver os usos mais comuns e como escolher a preposição correta em diferentes situações.', 'Não há uma regra única, mas sim contextos de uso. ''Por'' é usado para causa, motivo, meio, duração, troca e agradecimento. ''Para'' é usado para finalidade, destino, prazo, opinião e destinatário.', '[{"case":"Causa ou motivo","example":"Estudio español por mi trabajo.","explanation_pt_br":"Use ''por'' para indicar a razão ou causa de uma ação."},{"case":"Finalidade ou objetivo","example":"Estudio español para viajar a España.","explanation_pt_br":"Use ''para'' para indicar a finalidade ou objetivo de uma ação."},{"case":"Destino ou direção","example":"Este regalo es para ti.","explanation_pt_br":"Use ''para'' para indicar o destinatário ou o destino de algo."},{"case":"Meio ou forma","example":"Te llamo por teléfono.","explanation_pt_br":"Use ''por'' para indicar o meio ou a forma como algo é feito."},{"case":"Tempo e duração","example":"Trabajé por dos horas.","explanation_pt_br":"Use ''por'' para indicar duração de tempo."},{"case":"Prazo","example":"Necesito el informe para mañana.","explanation_pt_br":"Use ''para'' para indicar um prazo ou ponto limite no tempo."}]'::jsonb, '["Usar ''por'' no lugar de ''para'' para finalidade: ''Compro pan por desayuno'' (o correto é ''Compro pan para el desayuno'').","Usar ''para'' no lugar de ''por'' para causa: ''No fui a trabajar para enfermedad'' (o correto é ''por enfermedad'').","Confundir ''por'' e ''para'' em expressões de agradecimento: ''Gracias por tu ayuda'' (correto) e ''Gracias para tu ayuda'' (incorreto)."]'::jsonb, '["''Por'' também é usado em expressões como ''por ejemplo'', ''por eso'', ''por favor'', ''por fin''.","''Para'' também é usado para expressar opinião: ''Para mí, este libro es interesante''.","Em espanhol, ''por'' e ''para'' não são intercambiáveis; a escolha muda o significado da frase."]'::jsonb, 0, true)
