insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-10cc31bf803e', 'es', 'A2', 'Pretérito Perfecto: Hablar de Experiencias y Acciones Recientes', 'O pretérito perfecto é usado para falar de ações que aconteceram em um tempo passado, mas que têm relação com o presente. Por exemplo, para falar de experiências de vida ou de ações que acabaram de acontecer. Nesta lição, vamos aprender como formar e usar esse tempo verbal, e também vamos praticar com exercícios.', 'Para formar o pretérito perfecto, use o presente do verbo HABER + o particípio passado do verbo principal. O particípio é formado com as terminações -ado para verbos terminados em -ar (hablar → hablado) e -ido para verbos terminados em -er/-ir (comer → comido, vivir → vivido). Também existem particípios irregulares, como: abrir → abierto, decir → dicho, hacer → hecho, poner → puesto, ver → visto, volver → vuelto.', '["Para falar de experiências de vida: ''He visitado España.''","Para falar de ações recentes: ''Hoy he comido pizza.''","Para falar de ações que ainda têm relação com o presente: ''¿Has hecho la tarea?''","Para expressar ações que aconteceram em um período de tempo que ainda não terminou: ''Esta semana he trabajado mucho.''"]'::jsonb, '["Usar o pretérito perfecto com tempo acabado (ex: ''ayer'') - nesse caso, use o pretérito indefinido.","Esquecer de usar o auxiliar ''haber'' - ex: ''Yo comido'' em vez de ''Yo he comido''.","Usar o particípio irregular incorretamente - ex: ''he ponido'' em vez de ''he puesto''."]'::jsonb, '["Em espanhol, o particípio passado também é usado como adjetivo, como em ''la puerta está abierta''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

