insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-7c431c74227f', 'es', 'A2', 'Reflexive Verbs and Basic Reflexive Pronouns in Spanish', 'Os verbos reflexivos são usados quando a ação do verbo recai sobre o próprio sujeito. Por exemplo, em espanhol, ''levantarse'' significa ''levantar a si mesmo''. Nesta lição, você vai aprender como formar e usar os verbos reflexivos em situações do dia a dia, como rotinas matinais e ações pessoais. Vamos ver os pronomes reflexivos e como eles mudam com cada pessoa.', 'Para formar um verbo reflexivo, usamos o pronome reflexivo antes do verbo conjugado. Os pronomes são: me, te, se, nos, os, se. Exemplo com ''levantarse'': yo me levanto, tú te levantas, él/ella/usted se levanta, nosotros/nosotras nos levantamos, vosotros/vosotras os levantáis, ellos/ellas/ustedes se levantan. Na forma negativa, o ''no'' vai antes do pronome: ''No me levanto''. Nas frases com dois verbos, o pronome pode ir antes do primeiro verbo ou no final do infinitivo: ''Voy a levantarme'' ou ''Me voy a levantar''.', '["Rotinas diárias: ''Me despierto a las seis.''","Cuidados pessoais: ''Ella se peina el pelo.''","Mudanças de estado: ''Nos cansamos después del trabajo.''","Ações recíprocas: ''Ellos se llaman por teléfono.''"]'::jsonb, '["Colocar o pronome depois do verbo na conjugação normal: ''Yo levanto me'' (incorreto), o certo é ''Yo me levanto''.","Usar ''se'' para todas as pessoas, mas cada pessoa tem seu pronome: ''Yo se levanto'' (incorreto), o certo é ''yo me levanto''.","Esquecer o pronome: ''Yo levanto'' (sem reflexivo, significa ''eu levanto algo/alguém''), o certo para levantar a si mesmo é ''Me levanto''."]'::jsonb, '["Atenção: alguns verbos mudam de significado quando são reflexivos. Por exemplo, ''dormir'' (dormir) e ''dormirse'' (adormecer).","Em espanhol, o pronome reflexivo vai sempre antes do verbo conjugado, exceto no imperativo afirmativo, onde vai depois e junto: ''Levántate''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

