insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-723723a4c2f8', 'es', 'A2', 'Imperativo Informal: ¡Hazlo Ahora!', 'O imperativo informal (tú) é usado para dar ordens, conselhos ou convites de forma direta e amigável. Nesta lição, você vai aprender a formar e usar o imperativo afirmativo e negativo com os verbos regulares e alguns irregulares comuns, como ''ir'', ''hacer'', ''poner'' e ''tener''.', 'Para a maioria dos verbos, o imperativo afirmativo para ''tú'' é igual à forma do presente do indicativo para ''él/ella/usted''. Por exemplo: ''hablar'' → ''habla'', ''comer'' → ''come'', ''escribir'' → ''escribe''. Para o imperativo negativo, use ''no'' + a forma do presente do subjuntivo para ''tú'': ''no hables'', ''no comas'', ''no escribas''.', '["Dar instruções: ''Abre la puerta, por favor.''","Dar conselhos: ''Descansa un poco.''","Fazer convites: ''Ven a mi casa esta noche.''","Dar ordens: ''Haz tu tarea ahora.''","Fazer pedidos: ''Pásame la sal, por favor.''"]'::jsonb, '["Confundir a forma de ''tú'' com a de ''usted'': ''Habla'' (tú) vs ''Hable'' (usted).","Usar o infinitivo em vez do imperativo: ''Hablar'' em vez de ''Habla''.","Esquecer o ''no'' no imperativo negativo: ''No habla'' em vez de ''No hables''.","Confundir verbos irregulares: ''Hacer'' → ''Haz'', não ''Hace''.","Usar o imperativo de ''tú'' para situações formais, onde se deve usar ''usted''."]'::jsonb, '["O imperativo afirmativo para ''tú'' é igual à terceira pessoa do singular do presente do indicativo.","Os verbos irregulares mais comuns no imperativo afirmativo: ''ir'' → ''ve'', ''hacer'' → ''haz'', ''poner'' → ''pon'', ''tener'' → ''ten'', ''salir'' → ''sal'', ''venir'' → ''ven''.","Para o imperativo negativo, use a forma do presente do subjuntivo.","Em situações informais, é comum usar ''tú'' no Brasil? Não, mas no espanhol, para amigos e família, use ''tú''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

