insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-8b2dc291304c', 'es', 'A2', 'El Pretérito Indefinido: Ações Concluídas no Passado', 'O pretérito indefinido (também chamado de pretérito perfecto simple) é um tempo verbal usado para expressar ações passadas que foram concluídas em um momento específico ou em um período de tempo delimitado. É muito comum em narrativas, biografias e relatos de experiências. Nesta lição, você aprenderá a formar e usar corretamente esse tempo verbal, além de evitar erros comuns.', 'Para verbos regulares, a formação é:
- Verbos terminados em -ar: radical + -é, -aste, -ó, -amos, -asteis, -aron (ex: hablar -> hablé, hablaste, habló, hablamos, hablasteis, hablaron)
- Verbos terminados em -er/-ir: radical + -í, -iste, -ió, -imos, -isteis, -ieron (ex: comer -> comí, comiste, comió, comimos, comisteis, comieron; vivir -> viví, viviste, vivió, vivimos, vivisteis, vivieron)
Atenção: alguns verbos são irregulares, como ser/ir (fui, fuiste, fue, fuimos, fuisteis, fueron), estar (estuve, estuviste, estuvo, estuvimos, estuvisteis, estuvieron) e hacer (hice, hiciste, hizo, hicimos, hicisteis, hicieron).', '["Ações pontuais no passado: Ayer compré un libro.","Ações que ocorrem em um período de tempo delimitado: El año pasado viajé a Brasil.","Narrativas de eventos passados: Primero desayuné, luego salí de casa.","Biografias e fatos históricos: Picasso nació en 1881.","Sequências de ações concluídas: Entré, saludé y me senté."]'::jsonb, '["Confundir com o pretérito imperfecto: ''Ayer comí'' (ação pontual) vs. ''Cuando era niño, comía mucho'' (habitual).","Usar o indefinido para ações que ainda continuam: ''Viví aquí por mucho tiempo'' (se ainda vive, deve usar ''he vivido'').","Errar a escrita em verbos com irregularidades, como ''hacer'' que na terceira pessoa é ''hizo'', não ''hacío''.","Usar ''hubo'' no lugar de ''había'' para situações não concluídas: ''Hubo una fiesta'' (evento) vs. ''Había mucha gente'' (estado).","Esquecer de usar o indefinido com expressões de tempo passado específico: ''La semana pasada visité a mis padres'' (não ''visitaba'')."]'::jsonb, '["Lembre-se de que o indefinido é usado para ações terminadas, enquanto o imperfecto descreve ações contínuas ou habituais no passado.","Verbos irregulares comuns: tener (tuve), poder (pude), poner (puse), saber (supe), querer (quise) e vir (vine).","Em frases negativas, o indefinido ainda é usado: No comí ayer.","Na América Latina, o pretérito indefinido é mais frequente que o perfeito composto para ações passadas recentes: ''Ya comí'' em vez de ''ya he comido''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

