insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-9c7f8f42cbbc', 'es', 'A2', 'Introducción al Pretérito Imperfecto', 'O pretérito imperfecto é usado para descrever ações habituais no passado, ações em progresso, ou características e estados. Nesta lição, você vai aprender a formar e usar esse tempo verbal.', 'Para verbos regulares, remova a terminação -ar, -er, -ir e adicione as terminações: para -ar: -aba, -abas, -aba, -ábamos, -abais, -aban; para -er/-ir: -ía, -ías, -ía, -íamos, -íais, -ían. Exemplos: hablar → hablaba, comer → comía, vivir → vivía.', '["Descrever hábitos ou rotinas no passado: ''Cuando era niño, jugaba al fútbol todos los días.''","Descrever ações em andamento no passado: ''Mientras cocinaba, sonó el teléfono.''","Descrever características físicas, estados emocionais ou idade no passado: ''Mi abuela tenía ojos azules.''","Descrever o cenário ou contexto de uma história: ''Era una noche oscura y llovía.''","Expressar ações simultâneas no passado: ''Mientras estudiaba, escuchaba música.''"]'::jsonb, '["Usar o pretérito indefinido em vez do imperfecto para ações habituais: ''Cuando era niño, jugué al fútbol'' (deveria ser ''jugaba'').","Confundir as terminações de -ar e -er/-ir: ''comaba'' em vez de ''comía''.","Esquecer o acento em formas como ''hablábamos'' e ''comíamos''.","Usar o imperfecto para ações pontuais: ''Ayer comía una manzana'' (deveria ser ''comí'')."]'::jsonb, '["O imperfecto é equivalente ao pretérito imperfeito do português, então você já conhece o conceito.","Verbos irregulares: só três (ir, ser, ver).","O imperfecto é usado para descrever o fundo de uma história, enquanto o indefinido apresenta os eventos principais."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

