insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-18b9e86e3c43', 'es', 'A2', 'Comparações e Quantidade em Espanhol', 'Nesta lição, você vai aprender a fazer comparações de igualdade, superioridade e inferioridade, e a usar expressões de quantidade em espanhol. Essas estruturas são essenciais para descrever pessoas, objetos e situações do dia a dia.', 'Para comparar, usamos:
- Igualdade: tan + adjetivo + como (tão... quanto) ou tanto/a/os/as + substantivo + como (tanto... quanto).
- Superioridade: más + adjetivo/substantivo + que (mais... do que).
- Inferioridade: menos + adjetivo/substantivo + que (menos... do que).
- Superlativos: el/la más + adjetivo (o/a mais...).
Para quantidade, usamos: mucho/a/os/as (muito), poco/a/os/as (pouco), bastante (bastante), suficiente (suficiente), demasiado/a/os/as (demasiado).
Exemplos:
- Juan es tan alto como Pedro. (João é tão alto quanto Pedro.)
- Tengo más libros que tú. (Eu tenho mais livros do que você.)
- Hay menos gente que ayer. (Há menos gente do que ontem.)', '["Fazer comparações de igualdade, superioridade e inferioridade.","Expressar quantidades exatas ou aproximadas.","Usar superlativos para destacar algo ou alguém.","Comparar ações com verbos usando ''más que'', ''menos que''.","Indicar quantidades com ''mucho'', ''poco'', ''bastante''."]'::jsonb, '["Confundir ''tan'' com ''tanto'': ''tan'' é usado antes de adjetivos, ''tanto'' antes de substantivos.","Usar ''que'' em vez de ''como'' em comparações de igualdade.","Concordância incorreta de gênero e número em expressões de quantidade (ex.: ''muchas'' com substantivo feminino plural).","Usar ''más'' sem ''que'' em comparações de superioridade (ex.: ''más alto'' em vez de ''más alto que'').","Não usar o artigo definido em superlativos (ex.: ''el más alto'' não ''más alto'' quando referindo a um grupo)."]'::jsonb, '["Em comparações de igualdade com adjetivos, use ''tan... como''.","Para quantidade, ''mucho'' e ''poco'' variam em gênero e número: mucho, mucha, muchos, muchas.","''Bastante'' é invariável, mas pode significar ''suficiente'' ou ''considerável''.","Em superlativos, use ''el/la/los/las más + adjetivo''.","Atenção: ''más'' leva acento, ''mas'' (porém) é diferente."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

