insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-773047fbe32b', 'es', 'A2', 'Perífrasis Verbales Frecuentes (A2)', 'As perífrases verbais são combinações de dois ou mais verbos que funcionam juntos para expressar nuances de tempo, aspecto ou modo. Neste nível, estudamos as mais comuns: ''ir a + infinitivo'' (futuro próximo), ''estar + gerúndio'' (ação em andamento), ''acabar de + infinitivo'' (ação recém-concluída), ''tener que + infinitivo'' (obrigação) e ''poder + infinitivo'' (possibilidade/permissão). Entender essas estruturas ajuda você a se comunicar com mais naturalidade em espanhol.', '1. **Ir a + infinitivo**: verbo ''ir'' conjugado + ''a'' + infinitivo. Exemplo: ''Voy a comer.'' (Vou comer.)
2. **Estar + gerúndio**: verbo ''estar'' conjugado + gerúndio (-ando, -iendo). Exemplo: ''Estoy comiendo.'' (Estou comendo.)
3. **Acabar de + infinitivo**: verbo ''acabar'' conjugado + ''de'' + infinitivo. Exemplo: ''Acabo de comer.'' (Acabei de comer.)
4. **Tener que + infinitivo**: verbo ''tener'' conjugado + ''que'' + infinitivo. Exemplo: ''Tengo que comer.'' (Tenho que comer.)
5. **Poder + infinitivo**: verbo ''poder'' conjugado + infinitivo. Exemplo: ''Puedo comer.'' (Posso comer.)', '["Para falar de planos futuros: ''Mañana voy a viajar.''","Para descrever ações em andamento: ''Estoy estudiando ahora.''","Para expressar ações recentes: ''Acabo de llegar a casa.''","Para indicar obrigação: ''Tienes que hacer la tarea.''","Para expressar habilidade ou permissão: ''¿Puedo usar tu teléfono?''"]'::jsonb, '["Usar ''ir a'' com presente do subjuntivo em vez de infinitivo: ''Voy a que estudie'' (errado) -> ''Voy a estudiar'' (correto).","Esquecer a preposição ''de'' em ''acabar de'': ''Acabo comer'' (errado) -> ''Acabo de comer'' (correto).","Confundir ''tener que'' com ''hay que'': ''tener que'' indica obrigação pessoal, enquanto ''hay que'' é impessoal.","Usar o gerúndio após ''poder'': ''Puedo comiendo'' (errado) -> ''Puedo comer'' (correto)."]'::jsonb, '["Em espanhol, o gerúndio não varia em gênero ou número.","Na linguagem coloquial, é comum usar o presente simples no lugar de ''ir a + infinitivo''.","Para falar de ações futuras, além de ''ir a'', também se pode usar o futuro simples, mas este é menos comum na fala."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

