insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-4b95b4be05ad', 'es', 'A2', 'Por vs Para: Uso y Diferencias', 'Nesta lição, você vai aprender a diferença entre ''por'' e ''para'', duas preposições em espanhol que muitas vezes confundem os estudantes. Vamos ver os usos principais e praticar com exercícios.', 'As preposições ''por'' e ''para'' são usadas em contextos diferentes. ''Por'' é usado para causa, motivo, troca, duração, meio, entre outros. ''Para'' é usado para finalidade, destino, prazo, opinião, entre outros. Vamos ver cada uso com exemplos.', '["Por: causa ou motivo (ex.: ''Lo hice por ti'' - Eu fiz isso por você).","Por: meio ou transporte (ex.: ''Viajamos por avião'' - Viajamos de avião).","Por: troca ou substituição (ex.: ''Te doy 10 dólares por el libro'' - Te dou 10 dólares pelo livro).","Para: finalidade (ex.: ''Este regalo es para ti'' - Este presente é para você).","Para: direção ou destino (ex.: ''Salimos para Madrid'' - Saímos para Madri).","Para: prazo (ex.: ''Necesito el informe para mañana'' - Preciso do relatório para amanhã)."]'::jsonb, '["Usar ''para'' em vez de ''por'' para causa: ''Estoy triste para mi amigo'' (errado) - correto: ''Estoy triste por mi amigo'' (Estou triste pelo meu amigo).","Usar ''por'' em vez de ''para'' para finalidade: ''Estudio por aprender'' (errado) - correto: ''Estudio para aprender'' (Estudo para aprender).","Usar ''por'' em vez de ''para'' para prazo: ''Necesito el trabajo por mañana'' (errado) - correto: ''Necesito el trabajo para mañana'' (Preciso do trabalho para amanhã)."]'::jsonb, '["''Por'' pode aparecer em expressões como ''por favor'', ''por ejemplo'' (por exemplo), ''por eso'' (por isso).","''Para'' não é usado sozinho; sempre acompanha um verbo no infinitivo quando indica finalidade."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

