insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-95d1ae1901c7', 'es', 'A2', 'Conectores y Pronombres Relativos Simples', 'Nesta lição, você vai aprender a usar conectores simples (y, pero, porque, entonces) e pronomes relativos (que, quien, donde) para formar frases mais claras e naturais em espanhol. Esses elementos ajudam a conectar ideias e a dar mais informações sobre pessoas, objetos ou lugares sem repetir palavras.', 'Conectores: ''y'' (e) une ideias semelhantes; ''pero'' (mas) contrasta ideias; ''porque'' (porque) explica causa; ''entonces'' (então) indica consequência.
Pronomes relativos: ''que'' (que) refere-se a pessoas ou coisas; ''quien'' (quem) refere-se a pessoas (geralmente após preposição); ''donde'' (onde) refere-se a lugares.
Exemplos: ''Compré pan y leche.'' / ''Quiero ir, pero estoy cansado.'' / ''Estudio español porque me gusta.'' / ''Pienso, entonces existo.'' / ''La chica que vive aquí es simpática.'' / ''La persona con quien hablo es mi amiga.'' / ''La ciudad donde nací es pequeña.''', '["Usamos ''y'' para adicionar informações: ''Me gusta el café y el té.''","Usamos ''pero'' para mostrar contraste: ''Quiero salir, pero llueve.''","Usamos ''porque'' para explicar o motivo: ''No vengo porque estoy enfermo.''","Usamos ''entonces'' para indicar consequência: ''Estudias mucho, entonces apruebas.''","Usamos ''que'' para falar de pessoas ou coisas: ''El libro que leo es interesante.''","Usamos ''quien'' para pessoas (mais formal): ''La mujer con quien trabajo es doctora.''","Usamos ''donde'' para lugares: ''La casa donde vivo es antigua.''"]'::jsonb, '["Confundir ''porque'' (porque) com ''por qué'' (por quê): ''No sé por qué vino.'' (separado) e ''No vino porque estaba ocupado.'' (junto).","Usar ''que'' no lugar de ''quien'' para pessoas: correto: ''La amiga que tengo'' ou ''La amiga con quien hablo''.","Esquecer de usar ''donde'' para lugares: ''El parque donde jugamos'' e não ''El parque que jugamos''.","Esquecer a vírgula antes de ''pero'' e ''entonces'' em frases compostas: ''Quiero ir, pero no puedo.''"]'::jsonb, '["No nível A2, ''que'' é o pronome relativo mais comum e pode ser usado para pessoas e coisas.","''Donde'' é usado para lugares e não leva preposição quando o verbo indica movimento: ''La tienda donde voy''.","''Quien'' é mais formal e frequentemente usado após preposições: ''El hombre de quien hablo''.","Conectores como ''y'', ''pero'', ''porque'' são invariáveis e fáceis de usar."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

