insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-49631352550b', 'es', 'A2', 'Introducción al Pretérito Imperfecto', 'O pretérito imperfecto é um tempo verbal usado para descrever ações habituais ou contínuas no passado. Nesta lição, você vai aprender a formar e usar esse tempo no espanhol.', 'Para verbos regulares, adicione as seguintes terminações às raízes: para verbos -ar: -aba, -abas, -aba, -ábamos, -abais, -aban. Para verbos -er/-ir: -ía, -ías, -ía, -íamos, -íais, -ían. Exceções: ser (era, eras, era, éramos, erais, eran), ir (iba, ibas, iba, íbamos, ibais, iban) e ver (veía, veías, veía, veíamos, veíais, veían).', '["Descrever ações habituais no passado (ex: ''Cuando era niño, jugaba fútbol todos los días.'')","Descrever ações em andamento no passado (ex: ''Estaba leyendo cuando sonó el teléfono.'')","Descrever características físicas, estados emocionais ou idade no passado (ex: ''Tenía diez años.'')","Descrever o cenário ou o clima em uma narrativa passada (ex: ''Hacía sol y las aves cantaban.'')"]'::jsonb, '["Confundir com pretérito indefinido (ex: ''Yo comía'' vs ''Yo comí'').","Usar a forma incorreta para ''nosotros'': ''hablábamos'' em vez de ''hablabamos'' (sem acento).","Aplicar terminações de -ar a verbos -er/-ir (ex: ''comaba'' em vez de ''comía'').","Esquecer as irregularidades de ser, ir e ver."]'::jsonb, '["O pretérito imperfecto é usado para ações que não têm um fim específico no passado.","Muitas vezes é usado com expressões como ''antes'', ''cuando era niño'', ''siempre''.","Em espanhol, o pretérito imperfecto também é usado para descrever ações em segundo plano em narrativas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

