insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-4f51e8c8444e', 'es', 'A2', 'Comparativos y Cuantificadores en Español', 'Nesta lição, você vai aprender a comparar coisas e pessoas usando formas comparativas e a falar sobre quantidades com palavras como ''muy'', ''mucho'', ''poco'' e ''bastante''.', 'Para comparar, usamos ''más + adjetivo + que'' (ex: más alto que), ''menos + adjetivo + que'' (ex: menos caro que), e ''tan + adjetivo + como'' para igualdade (ex: tan rápido como). Para quantidades, usamos ''muy'' + adjetivo, ''mucho'' + substantivo, ''poco'' + substantivo, e ''bastante'' + substantivo.', '["Comparar características: ''María es más alta que Pedro.''","Comparar igualdade: ''Este libro es tan interesante como la película.''","Falar sobre quantidade: ''Tengo mucho trabajo hoy.''","Expressar insuficiência: ''Hay poca comida en la nevera.''"]'::jsonb, '["Usar ''muy'' com substantivos: ''muy libros'' (errado) em vez de ''muchos libros'' (correto).","Confundir ''más'' e ''mas'': ''más'' é comparação, ''mas'' é ''porém''.","Esquecer a palavra ''que'' na comparação: ''Pedro es más alto Juan'' (errado) em vez de ''Pedro es más alto que Juan'' (correto).","Usar ''tan'' antes de substantivo: ''tan casa'' (errado) em vez de ''tan grande casa'' (correto)."]'::jsonb, '["Lembre-se: ''muy'' modifica adjetivos e advérbios; ''mucho'' modifica substantivos e verbos.","Para igualdade com adjetivos, use ''tan + adjetivo + como''.","Os comparativos irregulares: ''bueno'' -> ''mejor'', ''malo'' -> ''peor'', ''grande'' -> ''mayor'', ''pequeño'' -> ''menor'' (para idade e tamanho)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

