insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-7cddc513a21b', 'es', 'A2', 'Imperativo Informal: Dando Órdenes y Consejos', 'Nesta lição, você vai aprender a usar o imperativo informal (tú) para dar ordens, conselhos e fazer pedidos. Vamos focar nos verbos regulares e em alguns irregulares comuns. Você vai praticar com exercícios para usar no dia a dia.', 'Para formar o imperativo afirmativo com tú, use a forma de ''usted'' do presente do indicativo, mas sem o ''s'' final. Por exemplo: ''hablar'' -> ''usted habla'' -> ''¡Habla!''. Para verbos irregulares, como ''decir'', ''hacer'', ''poner'', ''salir'', ''tener'', ''venir'', use as formas especiais: ''di'', ''haz'', ''pon'', ''sal'', ''ten'', ''ven''. Para o negativo, use ''no'' + a forma de ''tú'' do presente do subjuntivo, como ''No hables''.', '["Para dar ordens diretas, por exemplo, ''¡Come verduras!''","Para dar conselhos, por exemplo, ''Descansa un poco.''","Para fazer pedidos educados, por exemplo, ''Pásame la sal, por favor.''","Para dar instruções, por exemplo, ''Gira a la derecha en el semáforo.''"]'::jsonb, '["Confundir as formas de ''tú'' e ''usted'': ''¡Coma!'' é para ''usted'', não para ''tú''.","Esquecer as formas irregulares como ''haz'' e ''di''.","Usar o infinitivo em vez do imperativo: ''¡Comer!'' em vez de ''¡Come!''.","Esquecer o ''no'' no imperativo negativo: ''No hables'' e não ''No habla''."]'::jsonb, '["O imperativo é usado principalmente na forma afirmativa com amigos e familiares.","Em situações formais, use ''usted'' e o imperativo correspondente.","Os pronomes reflexivos e objetos podem ser anexados ao imperativo afirmativo, como ''Siéntate'' ou ''Lávalo''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

