insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-2151054bcc56', 'es', 'A2', 'Conectores y relativos simples', 'Nesta lição, você vai aprender a usar conectores simples (y, pero, porque, entonces) e pronomes relativos básicos (que, quien) para criar frases mais longas e interessantes. Esses elementos ajudam a conectar ideias e a dar mais detalhes sobre pessoas e coisas.', 'Conectores: ''y'' junta ideias similares; ''pero'' contrasta; ''porque'' dá razão; ''entonces'' indica consequência. Pronomes relativos: ''que'' se refere a coisas ou pessoas (ex: El libro que leo es bueno); ''quien'' se refere a pessoas (ex: La chica quien habla es mi hermana).', '["Para adicionar informações: ''Compro pan y leche.''","Para contrastar: ''Quiero salir, pero llueve.''","Para explicar razões: ''Estudio porque quiero aprender.''","Para mostrar consequência: ''Estoy cansado, entonces duermo.''","Para descrever pessoas: ''El hombre que vive aquí es simpático.''"]'::jsonb, '["Confundir ''porque'' (porque) com ''por qué'' (por que).","Usar ''que'' para pessoas em vez de ''quien'' (embora ''que'' também seja aceito informalmente).","Esquecer a vírgula antes de ''pero'' e ''entonces'' em frases compostas."]'::jsonb, '["''Quien'' é mais formal; no dia a dia, muitos usam ''que'' para pessoas também.","Nas perguntas, use ''por qué'' separado e com acento.","''Entonces'' pode vir no início ou no meio da frase."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

