insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-11f0d40f23b2', 'es', 'A2', 'Pretérito Indefinido: Ações Concluídas no Passado', 'O pretérito indefinido (também chamado de pretérito perfecto simple) é usado para falar de ações passadas que já terminaram, em um momento específico.', 'Para verbos regulares, a formação é: para -ar: -é, -aste, -ó, -amos, -asteis, -aron. Para -er/-ir: -í, -iste, -ió, -imos, -isteis, -ieron. Existem também verbos irregulares, como ''ser/ir'' (fui, fuiste, fue, fuimos, fuisteis, fueron), ''hacer'' (hice, hiciste, hizo, hicimos, hicisteis, hicieron) e ''estar'' (estuve, estuviste, estuvo, estuvimos, estuvisteis, estuvieron).', '["Ações concluídas no passado com tempo definido.","Narrar eventos em sequência.","Falar de experiências passadas com marcadores como ''ayer'', ''el año pasado'', ''en 2010''."]'::jsonb, '["Usar pretérito indefinido para ações em andamento (usar pretérito imperfecto).","Confundir as formas irregulares de ''ser'' e ''ir'' (fui, fue, etc.)","Esquecer o acento nas formas de yo e él/ella/usted: ''hablé'', ''habló''."]'::jsonb, '["Em espanhol, o pretérito indefinido é frequentemente usado em biografias e relatos de eventos históricos.","No espanhol da América Latina, a forma ''vosotros'' é pouco usada; usamos ''ustedes''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

