insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-dffdbc7c51f8', 'es', 'A2', 'Objetos directos e indirectos en español', 'En esta lección, vamos a aprender sobre los objetos directos e indirectos en español. El objeto directo recibe la acción del verbo directamente, mientras que el objeto indirecto indica a quién o para quién se hace la acción. Usaremos pronombres como ''lo'', ''la'', ''los'', ''las'' para el objeto directo, y ''le'', ''les'' para el indirecto.', 'Para usar los pronombres de objeto directo e indirecto, seguimos esta estructura: [Objeto indirecto] + [Objeto directo] + [Verbo]. Por ejemplo: ''Te lo doy'' (Te = indirecto, lo = directo). Si ambos están en tercera persona, ''le'' se convierte en ''se'': ''Se lo doy a él''.', '["Para evitar repetir el nombre de una persona o cosa.","Para indicar a quién se dirige la acción (indirecto) y qué se da o hace (directo).","En preguntas y respuestas cortas.","Con verbos como dar, enviar, decir, comprar, etc."]'::jsonb, '["Confundir ''le'' y ''lo'' (usar ''lo'' para indirecto).","Olvidar cambiar ''le'' a ''se'' antes de ''lo/la/los/las''.","Colocar los pronombres después del verbo en presente (ej. ''doy lo'' en vez de ''lo doy'').","Usar el pronombre correcto pero en posición incorrecta con gerundios o imperativos."]'::jsonb, '["Cuando el objeto directo es una persona, se usa ''a'' antes (Ej: Veo a María -> La veo).","El orden de los pronombres es fijo: indirecto antes que directo.","En imperativos afirmativos, los pronombres van después del verbo (Ej: Dame lo)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

insert into public.grammar_exercises (id, language, level, title, explanation, example, question, options, answer_index, sort_order, is_published, topic_id)
values ('generated-grammar-es-a2-dffdbc7c51f8-exercise-01', 'es', 'A2', 'Identifica el objeto directo', 'El objeto directo responde a la pregunta ''¿qué?'' o ''¿a quién?'' después del verbo.', 'Juan compra un libro.', '¿Cuál es el objeto directo en esta oración?', '["Juan","compra","un libro","no hay"]'::jsonb, 2, 1, true, 'generated-grammar-es-a2-dffdbc7c51f8')
