insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-459967c67c35', 'es', 'A2', 'Reflexivos y verbos básicos', 'Nesta aula, você vai aprender a usar os verbos reflexivos em espanhol, como ''llamarse'', ''levantarse'' e ''vestirse''. Esses verbos são muito comuns na vida diária e ajudam a falar sobre rotinas e ações pessoais. Vamos ver como eles se formam e quando usá-los, com atenção especial às diferenças com o português.', 'Para formar um verbo reflexivo, usamos o pronome reflexivo antes do verbo conjugado. O pronome muda de acordo com a pessoa: yo me, tú te, él/ella/usted se, nosotros/nosotras nos, vosotros/vosotras os, ellos/ellas/ustedes se. Exemplo: ''Yo me llamo Ana.'' (Eu me chamo Ana). O verbo é conjugado normalmente, mas sempre acompanhado do pronome. Alguns verbos reflexivos comuns: llamarse (chamar-se), levantarse (levantar-se), ducharse (tomar banho), vestirse (vestir-se), sentirse (sentir-se) e acostarse (deitar-se).', '["Para falar sobre ações que a pessoa faz em si mesma: Yo me levanto temprano.","Para expressar rotinas diárias: Él se ducha todas las mañanas.","Para usar verbos como ''llamarse'' e ''sentirse'': Ella se siente bien.","Para ações recíprocas (um ao outro): Ellos se escriben cartas."]'::jsonb, '["Não esquecer o pronome reflexivo: ''Yo levanto temprano'' está incorreto; o correto é ''Yo me levanto temprano''.","Confundir o pronome ''se'' com ''te'': ''Él se llama Juan'' (não ''te llama'').","Usar o reflexivo com verbos que não são reflexivos: ''Tú bañas el perro'' (banhar o cachorro) é diferente de ''Tú te bañas'' (tomar banho)."]'::jsonb, '["Em espanhol, alguns verbos são sempre reflexivos, como ''arrepentirse'' (arrepender-se) e ''quejarse'' (queixar-se).","O pronome reflexivo pode ficar antes do verbo ou unido ao infinitivo: ''me voy a vestir'' ou ''voy a vestirme''.","Quando o sujeito é plural e a ação é mútua, usamos ''se'' para ''ellos/ellas/ustedes'' e ''nos'' para ''nosotros''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

