insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-8b939fc77e2f', 'es', 'A2', 'Perífrasis Verbales Frecuentes (A2)', 'As perífrases verbais são combinações de dois verbos que expressam uma ideia única. Nesta lição, você vai aprender as mais comuns: ir a + infinitivo (futuro próximo), estar + gerúndio (ação em andamento), acabar de + infinitivo (ação recém-concluída), e tener que + infinitivo (obrigação).', 'As perífrases são formadas por um verbo conjugado (auxiliar) + uma forma não pessoal (infinitivo, gerúndio ou particípio). Exemplos: ir a + infinitivo: Yo voy a comer. / estar + gerúndio: Ella está hablando. / acabar de + infinitivo: Acabo de llegar. / tener que + infinitivo: Tienes que estudiar.', '["Ir a + infinitivo: para falar de planos e intenções futuras.","Estar + gerúndio: para descrever ações que estão acontecendo no momento da fala.","Acabar de + infinitivo: para indicar que algo aconteceu há pouco tempo.","Tener que + infinitivo: para expressar obrigação ou necessidade."]'::jsonb, '["Confundir ''ir a + infinitivo'' com ''ir + gerúndio'' (não existe).","Usar ''estar + infinitivo'' em vez de ''estar + gerúndio''.","Esquecer de conjugar o verbo auxiliar corretamente.","Usar ''acabar de'' no presente para ações futuras."]'::jsonb, '["Observe que ''acabar de'' é usado principalmente no presente e no pretérito perfeito.","A perífrase ''estar + gerúndio'' também é usada para ações temporárias.","Pratique a conjugação dos auxiliares no presente do indicativo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

