insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-es-a2-6f8d88aafa94', 'es', 'A2', 'Conectores y relativos simples: que, donde, cuando', 'Nesta lição, você vai aprender a usar os pronomes relativos e conectores básicos em espanhol: que, donde e cuando. Essas palavras ajudam a conectar ideias e informações, tornando suas frases mais claras e fluidas. Vamos ver como usá-las em situações do dia a dia.', '1. Que: usado para pessoas, coisas ou animais. Exemplo: ''El libro que leo es interesante.''
2. Donde: usado para lugares. Exemplo: ''La casa donde vivo es pequeña.''
3. Cuando: usado para tempo. Exemplo: ''Recuerdo cuando fuimos a la playa.''', '["Que: para conectar uma pessoa ou coisa a uma informação adicional. Exemplo: ''La chica que canta es mi hermana.''","Donde: para indicar lugar. Exemplo: ''La tienda donde compro pan está cerca.''","Cuando: para indicar tempo. Exemplo: ''Cuando era niño, jugaba fútbol.''","Que também pode ser usado como conjunção para unir frases. Exemplo: ''Creo que tienes razón.''"]'::jsonb, '["Usar ''donde'' para tempo: ''El año donde nací'' é incorreto. O correto é ''El año en que nací''.","Esquecer o ''que'' quando é necessário: ''La casa es bonita'' em vez de ''La casa que es bonita''.","Confundir ''cuando'' com ''cuánto'': ''Cuando'' significa ''quando'' e ''cuánto'' significa ''quanto''.","Usar ''que'' após preposição: ''La persona a que hablé'' é incorreto. O correto é ''La persona a la que hablé''."]'::jsonb, '["Que pode ser sujeito ou objeto: ''El hombre que habla'' (sujeito) e ''El hombre que veo'' (objeto).","Donde não leva preposição quando significa ''onde'': ''La ciudad donde vivo''.","Quando é usado para perguntas: ''¿Cuándo vienes?'' e como conector: ''Cuando llegues, llama.''","Em espanhol, o ''que'' relativo é invariável: não muda de forma."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

