insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a2-c373841007a7', 'es', 'A2', 'La cocina de mi abuela', 'Mi abuela Carmen tiene una cocina muy especial. Ella prepara la comida para toda la familia. Ayer, mi abuela hizo una paella. Primero, ella compró los ingredientes en el mercado. Luego, me pidió ayuda. Ella me dijo: "Pon la mesa, por favor". Yo puse los platos y los vasos. Después, ella sirvió la paella en una fuente grande. Mi abuela me dio un plato de paella y me preguntó: "¿Te gusta la paella?". Yo le respondí: "Sí, me encanta". Ella sonrió y me dio más. También, ella le dio una porción a mi padre. A mi madre, ella le ofreció una ensalada. Finalmente, todos comimos juntos. La paella estaba deliciosa. Mi abuela ama cocinar. Ella siempre nos prepara platos ricos. ¡Qué suerte tenemos!', '¿Qué le dio la abuela a mi padre?', '["Una paella","Un plato de paella","Una porción de paella","Una ensalada"]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A abuela deu uma porção de paella ao pai. A frase: ''Ella le dio una porción a mi padre'' confirma isso. As outras opções não estão corretas porque ela deu uma porção, não um prato inteiro, e a ensalada foi para a mãe.","options":["Una paella","Un plato de paella","Una porción de paella","Una ensalada"],"prompt":"¿Qué le dio la abuela a mi padre?"},{"answer_index":2,"explanation_pt_br":"A avó pediu: ''Pon la mesa, por favor''. Isso significa colocar a mesa. As outras ações foram feitas por ela mesma ou não foram mencionadas como pedidos.","options":["Comprar os ingredientes","Cozinhar a paella","Pôr a mesa","Servir a comida"],"prompt":"O que a abuela pediu para o neto fazer?"},{"answer_index":2,"explanation_pt_br":"A avó ofereceu uma salada à mãe: ''A mi madre, ella le ofreció una ensalada''. As outras opções não aparecem no texto.","options":["Una paella","Una porción de paella","Una ensalada","Un vaso de vino"],"prompt":"¿Qué le regaló la abuela a la madre?"}]'::jsonb, 0, true)
