insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a2-c06885f58b21', 'es', 'A2', 'Mi Rutina Diaria', 'Cada mañana, me despierto a las seis y media. Primero, me levanto de la cama y voy al baño. Allí, me ducho con agua caliente. Después, me seco el pelo y me visto para el trabajo. A las siete y cuarto, desayuno en la cocina. Normalmente, como pan con mantequilla y bebo café con leche. A las ocho, salgo de casa y voy a la oficina en autobús. El viaje dura treinta minutos. En el trabajo, uso el ordenador y hablo con mis compañeros. A las dos, como en un restaurante cerca de la oficina. Por la tarde, sigo trabajando hasta las seis. Cuando llego a casa, me siento en el sofá y veo la televisión. A veces, leo un libro o escucho música. A las diez, me preparo para dormir: me pongo el pijama y me acuesto. Así es mi rutina diaria. Es sencilla pero me gusta.', '¿A qué hora se despierta la persona?', '["A las seis y media","A las siete","A las ocho","A las diez"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz: ''me despierto a las seis y media''.","options":["A las seis y media","A las siete","A las ocho","A las diez"],"prompt":"¿A qué hora se despierta la persona?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''Después, me seco el pelo y me visto para el trabajo''.","options":["Se viste","Desayuna","Va al trabajo","Ve la televisión"],"prompt":"¿Qué hace la persona después de ducharse?"},{"answer_index":0,"explanation_pt_br":"O texto diz: ''voy a la oficina en autobús''.","options":["En autobús","En coche","A pie","En metro"],"prompt":"¿Cómo va la persona al trabajo?"}]'::jsonb, 0, true)
