insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a2-4a74b5edd343', 'es', 'A2', '¿Qué has hecho hoy?', 'Hoy es un día especial para Laura. Ella ha tenido un día muy ocupado y quiere contarle a su amigo Miguel todo lo que ha hecho. Por la mañana, Laura ha desayunado con su familia y después ha ido al mercado. En el mercado, ha comprado frutas y verduras frescas. También ha visitado a su abuela, que vive cerca del mercado. Han hablado y han tomado un café juntos. Después, Laura ha vuelto a casa y ha preparado una paella para la cena. Ha usado arroz, pollo, y verduras. La paella ha quedado muy rica. Por la tarde, ha limpiado su apartamento y ha lavado la ropa. También ha regado las plantas. Al final, ha visto una película en la televisión. Ahora, Laura está cansada pero contenta. Ella ha hecho muchas cosas hoy y quiere descansar. Mañana va a visitar a su amigo Miguel y le va a contar todo. Miguel también ha tenido un día ocupado: ha trabajado en la oficina y ha enviado muchos correos electrónicos. Los dos amigos tienen mucho que contarse.', '¿Qué ha comprado Laura en el mercado?', '["Frutas y verduras","Pan y leche","Pescado y carne","Dulces y pasteles"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Laura comprou frutas e verduras frescas no mercado, como diz o texto: ''ha comprado frutas y verduras frescas''.","options":["Frutas y verduras","Pan y leche","Pescado y carne","Dulces y pasteles"],"prompt":"¿Qué ha comprado Laura en el mercado?"},{"answer_index":1,"explanation_pt_br":"Laura preparou uma paella para o jantar: ''ha preparado una paella para la cena''.","options":["Una ensalada","Una paella","Una sopa","Un pastel"],"prompt":"¿Qué ha preparado Laura para la cena?"},{"answer_index":1,"explanation_pt_br":"Miguel trabalhou no escritório e enviou muitos e-mails: ''ha trabajado en la oficina y ha enviado muchos correos electrónicos''.","options":["Ha viajado a otra ciudad","Ha trabajado en la oficina y ha enviado correos","Ha visitado a su abuela","Ha limpiado su casa"],"prompt":"¿Qué ha hecho Miguel hoy?"}]'::jsonb, 0, true)
