insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a2-c3c489efe1b9', 'es', 'A2', 'Mi Rutina Diaria con Verbos Reflexivos', 'Hola, soy Marta y vivo en São Paulo. Todos los días me levanto a las seis y media de la mañana. Primero, me ducho con agua caliente y luego me visto rápidamente. Después, me desayuno: como pan con mantequilla y bebo café con leche. A las siete y media, me voy al trabajo en autobús. Mi trabajo es en una oficina, y allí me siento frente a la computadora. Durante el día, me concentro en mis tareas y ayudo a mis compañeros. Al mediodía, como en un restaurante cerca de la oficina. Por la tarde, tengo una reunión importante, y me preparo con anticipación. Termino de trabajar a las seis de la tarde. Cuando llego a casa, me relajo un poco: veo la televisión o leo un libro. Luego, me preparo la cena y ceno con mi familia. Después de cenar, me cepillo los dientes y me pongo el pijama. Finalmente, me acuesto a las diez y media y duermo bien. Los fines de semana, me divierto con mis amigos: paseamos y hablamos mucho. Me gusta mi rutina porque me siento tranquila y organizada.', '¿A qué hora se levanta Marta?', '["A las seis y media","A las siete","A las ocho","A las diez"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, Marta diz: ''Todos os dias me levanto a las seis y media de la mañana.'' Portanto, ela se levanta às seis e meia.","options":["A las seis y media","A las siete","A las ocho","A las diez"],"prompt":"¿A qué hora se levanta Marta?"},{"answer_index":0,"explanation_pt_br":"No texto, depois de tomar banho, Marta diz: ''luego me visto rápidamente''. Ou seja, ela se veste.","options":["Se viste","Desayuna","Se va al trabajo","Se cepilla los dientes"],"prompt":"¿Qué hace Marta después de ducharse?"},{"answer_index":0,"explanation_pt_br":"Marta menciona: ''Cuando llego a casa, me relajo un poco: veo la televisión o leo un libro.'' Portanto, ela assiste TV ou lê um livro.","options":["Ve la televisión o lee un libro","Cocina la cena","Habla con amigos","Trabaja en la computadora"],"prompt":"¿Cómo se relaja Marta cuando llega a casa?"}]'::jsonb, 0, true)
