insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-es-a2-548db1be19ee', 'es', 'A2', 'Mi Rutina Diaria', 'Hola, soy Marta y vivo en São Paulo. Todos los días me levanto temprano, a las seis y media. Primero, me ducho con agua caliente y luego me visto rápido. Después, voy a la cocina y preparo el desayuno: café con leche y pan. A las siete y media, me voy al trabajo. Trabajo en una oficina cerca de mi casa, así que voy a pie. En el trabajo, me siento frente al ordenador y contesto correos. A mediodía, como con mis compañeros en una cafetería. Me gusta comer ensalada y beber agua. Por la tarde, me concentro en mis tareas. A las seis de la tarde, vuelvo a casa. Una vez en casa, me cambio de ropa y me relajo un poco. A veces veo la televisión o leo un libro. A las nueve, ceno con mi familia. Después, me lavo los dientes y me acuesto. Me duermo rápido porque estoy cansada. Los fines de semana, me levanto más tarde y hago actividades diferentes. Me gusta pasear por el parque o visitar a mis amigos. También me gusta cocinar platos especiales. Así es mi semana, pero cada día es especial. ¿Y tú? ¿Cómo es tu rutina diaria?', '¿A qué hora se levanta Marta?', '["A las seis y media","A las siete y media","A las nueve","A las seis"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"O texto diz ''me levanto temprano, a las seis y media''.","options":["A las seis y media","A las siete y media","A las nueve","A las seis"],"prompt":"¿A qué hora se levanta Marta?"},{"answer_index":2,"explanation_pt_br":"O texto diz ''voy a pie''.","options":["En coche","En autobús","A pie","En metro"],"prompt":"¿Cómo va Marta al trabajo?"},{"answer_index":0,"explanation_pt_br":"O texto diz ''Después, me lavo los dientes y me acuesto''.","options":["Se lava los dientes y se acuesta","Ve la televisión","Lee un libro","Se ducha"],"prompt":"¿Qué hace Marta después de cenar?"}]'::jsonb, 0, true)
