insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-7b9168ab65eb', 'fr', 'A2', 'Introducing Yourself and Asking Questions in French', 'Neste tópico, você vai aprender a usar ''y'' para falar de lugares e a fazer perguntas com ''est-ce que'' e inversão. Vamos focar em situações do dia a dia, como falar sobre onde você mora, trabalha ou estuda. Ao final, você será capaz de se apresentar e perguntar informações básicas a outras pessoas.', 'O pronome ''y'' substitui um lugar já mencionado (ex: ''Je vais à Paris'' → ''J''y vais''). Ele vem antes do verbo. Para perguntas, use ''Est-ce que'' + frase afirmativa (ex: ''Est-ce que tu habites ici?'') ou a inversão (ex: ''Habites-tu ici?'').', '["Falar sobre lugar: ''J''y vais demain.''","Perguntar sobre lugar: ''Y a-t-il un métro?''","Responder usando ''y'': ''Oui, j''y vais.''","Perguntar com ''est-ce que'': ''Est-ce que tu aimes le café?''"]'::jsonb, '["Esquecer de usar ''y'' depois de verbos como ''aller'', ''être'', ''habiter'': ''Je vais à Paris'' → ''J''y vais''.","Colocar ''y'' depois do verbo: ''Je vais y'' (errado), o correto é ''J''y vais''.","Usar ''est-ce que'' com inversão ao mesmo tempo: ''Est-ce que vas-tu?'' (errado)."]'::jsonb, '["''Y'' é usado para lugares, não para pessoas.","Nas perguntas informais, ''est-ce que'' é mais comum.","Na negativa, ''y'' vem antes do verbo: ''Je n''y vais pas.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

