insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-c380a9088351', 'fr', 'A2', 'Les verbes pronominaux', 'Os verbos pronominais em francês são verbos acompanhados de um pronome reflexivo (me, te, se, nous, vous). Eles são usados para ações que a pessoa faz em si mesma (ex: se laver - lavar-se) ou para ações recíprocas entre pessoas (ex: se parler - falar um com o outro). Nesta lição, você vai aprender a formar e usar esses verbos no presente do indicativo.', 'Para formar um verbo pronominal no presente, você coloca o pronome reflexivo antes do verbo, e o pronome concorda com o sujeito. Exemplo com ''se laver'': je me lave, tu te laves, il/elle/on se lave, nous nous lavons, vous vous lavez, ils/elles se lavent. Atenção: com ''nous'', repetimos ''nous'' (nous nous...). Com ''vous'', repetimos ''vous'' (vous vous...). Os verbos pronominais são conjugados com o verbo ''être'' nos tempos compostos (ex: je me suis lavé).', '["Ações reflexas: o sujeito faz a ação em si mesmo (ex: Je me lève - Eu me levanto).","Ações recíprocas: duas ou mais pessoas fazem a ação uma na outra (ex: Ils se regardent - Eles se olham).","Mudança de estado ou rotina (ex: se coucher - deitar-se).","Uso idiomático: alguns verbos têm sentido diferente quando pronominais (ex: aller - ir; s''en aller - ir embora)."]'::jsonb, '["Esquecer o pronome reflexivo (ex: ''Je lève'' em vez de ''Je me lève'').","Usar o pronome errado (ex: ''Il me lave'' em vez de ''Il se lave'').","Esquecer a concordância do particípio passado nos tempos compostos (ex: ''elle s''a lavée'' em vez de ''elle s''est lavée'').","Colocar o pronome após o verbo (ex: ''Lave je me'' em vez de ''Je me lave'')."]'::jsonb, '["Os pronomes reflexivos em francês são: me, te, se, nous, vous.","Com ''nous'' e ''vous'', o pronome é repetido (nous nous, vous vous).","Na negativa, o ''ne'' vem antes do pronome e o ''pas'' depois do verbo (ex: Je ne me lave pas).","Na inversão (perguntas), o pronome vem antes do verbo (ex: Te lèves-tu ?).","Alguns verbos pronominais são sempre pronominais (ex: s''ennuyer - entediar-se)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

