insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-a92251b8d4c1', 'fr', 'A2', 'Les verbes pronominaux', 'Os verbos pronominais em francês são acompanhados de um pronome reflexivo (me, te, se, nous, vous, se) que indica que a ação é feita por e para o próprio sujeito. Nesta lição, você vai aprender a formar e usar esses verbos no presente do indicativo.', 'Para conjugar um verbo pronominal no presente, coloque o pronome reflexivo antes do verbo e concorde-o com o sujeito. Exemplo: se laver (lavar-se). Je me lave, tu te laves, il/elle/on se lave, nous nous lavons, vous vous lavez, ils/elles se lavent. Atenção: com nous e vous, o pronome reflexivo é nous e vous, respectivamente, e o verbo concorda com o sujeito.', '["Ações da rotina diária: se lever (levantar-se), se laver (lavar-se)","Sentimentos e estados: se sentir (sentir-se), s''ennuyer (entediar-se)","Mudanças de estado: se fâcher (zangar-se), se dépêcher (apressar-se)","Ações recíprocas (no plural): se parler (falar um com o outro), se regarder (olhar um para o outro)"]'::jsonb, '["Esquecer o pronome reflexivo: ''Je lève'' em vez de ''Je me lève''.","Usar o pronome errado: ''Je te lève'' (incorreto) em vez de ''Je me lève''.","Concordância errada no plural: ''Ils se lavent'' (correto) e não ''Ils se lave''.","Confundir verbos pronominais com verbos não pronominais: ''Je repose'' (repouso algo) vs. ''Je me repose'' (eu descanso).","Em negação, esquecer a estrutura: ''Je ne me lève pas'' (correto) e não ''Je ne lève pas''."]'::jsonb, '["Alguns verbos pronominais têm sentido diferente dos verbos não pronominais: ''aller'' (ir) vs. ''s''en aller'' (ir embora).","Na negação, o ''ne'' vem antes do pronome reflexivo: ''Je ne me lave pas''.","Na forma interrogativa, o pronome reflexivo permanece antes do verbo: ''Te lèves-tu ?'' ou ''Est-ce que tu te lèves ?''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

