insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-20cdb4ea700e', 'fr', 'A2', 'Les pronoms relatifs : qui, que, où', 'Nesta lição, você vai aprender a usar os pronomes relativos ''qui'', ''que'' e ''où'' para conectar ideias e formar frases mais complexas. Esses pronomes são essenciais para enriquecer seu francês e tornar sua comunicação mais natural.', 'Qui é usado como sujeito da oração relativa (ex.: ''Le livre qui est sur la table est à moi.''). Que é usado como objeto direto (ex.: ''Le livre que je lis est intéressant.''). Où indica lugar ou tempo (ex.: ''La ville où je vis est belle.'').', '["Qui: substitui o sujeito (pessoa ou coisa) da oração relativa.","Que: substitui o objeto direto da oração relativa.","Où: indica lugar ou tempo, significando ''onde'' ou ''quando''.","Use qui quando o pronome é seguido por um verbo.","Use que quando o pronome é seguido por um sujeito + verbo.","Use où para lugares e expressões de tempo como ''le jour où''."]'::jsonb, '["Confundir qui e que: qui é sujeito, que é objeto.","Usar où para pessoas: onde é para lugares e tempo, não para pessoas.","Esquecer de usar o pronome relativo em frases que precisam dele."]'::jsonb, '["Qui e que são invariáveis (não mudam de forma).","Où também é usado para tempo: ''le moment où''.","Pratique com frases do cotidiano para fixar o uso."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

