insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-feb3bc1f6e0b', 'fr', 'A2', 'Futur Simple: Introduction', 'O futur simple é um tempo verbal usado para expressar ações que acontecerão no futuro. Nesta introdução, vamos aprender como formar o futuro simples regular e quando usá-lo.', 'Para formar o futuro simples em francês, usamos o infinitivo do verbo (para verbos terminados em -er, removemos o ''e'' final) e adicionamos as terminações: -ai, -as, -a, -ons, -ez, -ont. Por exemplo: parler -> je parlerai, tu parleras, il/elle parlera, nous parlerons, vous parlerez, ils/elles parleront.', '["Para expressar ações futuras: ''Demain, je voyagerai à Paris.'' (Amanhã, viajarei a Paris.)","Para fazer previsões: ''Il fera beau demain.'' (Fará bom tempo amanhã.)","Para expressar promessas: ''Je t''appellerai ce soir.'' (Te ligarei esta noite.)"]'::jsonb, '["Esquecer de remover o ''e'' dos verbos em -er: ''je parlerai'' (não ''je parlereai'')","Usar o futuro simples após ''si'' (se) em frases condicionais: ''Si j''ai le temps, je viendrai.'' (não ''Si j''aurai le temps'')","Confundir com o futuro imediato ''aller + infinitivo'': ''Je vais manger'' (presente) vs. ''Je mangerai'' (futuro simples)"]'::jsonb, '["O futuro simples é frequentemente usado em francês escrito e formal.","Na linguagem falada, o futuro imediato (aller + infinitivo) é mais comum para ações próximas.","Alguns verbos são irregulares no futuro simples, como ''être'' (ser/estar) -> je serai, ''avoir'' (ter) -> j''aurai."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

