insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-b2ace600db71', 'fr', 'A2', 'Comparatif et superlatif (A2)', 'Nesta lição, você vai aprender a comparar pessoas, objetos e ideias usando o comparativo e o superlativo. Vamos focar nas formas regulares e em alguns casos irregulares comuns. Ao final, você será capaz de fazer comparações simples no dia a dia.', 'Para formar o comparativo de superioridade, usamos ''plus'' + adjetivo + ''que''. Ex.: ''Marie est plus grande que Pierre.'' Para o comparativo de inferioridade, usamos ''moins'' + adjetivo + ''que''. Ex.: ''Ce film est moins intéressant que le livre.'' Para igualdade, usamos ''aussi'' + adjetivo + ''que''. Ex.: ''Il est aussi fort que son frère.'' O superlativo expressa a maior ou menor qualidade: ''le/la/les plus'' + adjetivo para superioridade, e ''le/la/les moins'' + adjetivo para inferioridade. Ex.: ''C''est le plus beau tableau.''', '["Comparar duas pessoas ou coisas: ''Paul est plus grand que Marie.''","Comparar ações: ''Elle parle plus vite que moi.''","Expressar igualdade: ''Ce gâteau est aussi bon que l''autre.''","Superlativo para destacar algo: ''C''est la plus belle ville de France.''"]'::jsonb, '["Confundir ''que'' (comparação) com ''qu'' (antes de vogal): ''plus grand qu''elle''.","Usar ''plus'' sem ''que'' na comparação.","Esquecer a concordância do adjetivo no superlativo: ''les plus belles fleurs''.","Usar ''aussi'' com ''que'' invertido: ''aussi que'' em vez de ''aussi ... que''."]'::jsonb, '["Lembre-se que ''bon'' tem comparativo irregular: ''meilleur''.","Com adjetivos de duas sílabas, algumas vezes usamos ''plus'' mesmo para inferioridade.","O superlativo concorda em gênero e número com o substantivo."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

