insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-7e665eb798aa', 'fr', 'A2', 'La quantité avec « de » et la négation', 'Nesta lição, você vai aprender a expressar quantidade em francês usando artigos partitivos (du, de la, de l'', des) e como eles mudam na forma negativa. Isso é essencial para falar sobre comida, compras e preferências no dia a dia.', 'Para quantidades indefinidas, usamos: du (masculino), de la (feminino), de l'' (antes de vogal), des (plural). Exemplos: Je mange du pain. Elle boit de l''eau. Ils achètent des légumes. Na negativa, esses artigos mudam para ''de'' (ou d'' antes de vogal): Je ne mange pas de pain. Elle ne boit pas d''eau. Ils n''achètent pas de légumes.', '["Para falar de uma quantidade não específica de algo: Je voudrais du café.","Para expressar preferências com verbos como aimer, adorer: J''aime le chocolat (mas com ''de'' na negativa: Je n''aime pas le chocolat).","Com expressões de quantidade como beaucoup de, un peu de, trop de: beaucoup de temps, un peu de sucre.","Na negativa, para dizer que não há algo ou que não se consome algo: Il n''y a pas de lait."]'::jsonb, '["Usar ''des'' na negativa: Errado: Je n''ai pas des frères. Certo: Je n''ai pas de frères.","Esquecer de usar ''de'' após expressões de quantidade: Errado: beaucoup des amis. Certo: beaucoup d''amis.","Confundir ''du'' com ''de la'': Use ''du'' para masculino, ''de la'' para feminino. Exemplo: du fromage (masculino), de la salade (feminino).","Usar ''de'' na afirmativa: Na afirmativa, use os artigos partitivos, não ''de''. Errado: Je mange de pain. Certo: Je mange du pain."]'::jsonb, '["Os artigos partitivos não são usados com verbos como ''aimer'' na afirmativa (J''aime le chocolat), mas na negativa usamos ''de'' (Je n''aime pas le chocolat).","Com ''ne... plus'' (não mais) também se usa ''de'': Je ne bois plus de café.","Atenção: com ''être'' + nacionalidade ou profissão, não se usa artigo: Je suis brésilien."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

