insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-0ffc74dbdd5e', 'fr', 'A2', 'Conectores Básicos em Francês (A2)', 'Os conectores básicos são palavras ou expressões que ligam ideias, frases ou parágrafos, tornando o discurso mais claro e coeso. Nesta lição, você aprenderá a usar alguns conectores essenciais: ''et'' (e), ''mais'' (mas), ''ou'' (ou), ''parce que'' (porque) e ''donc'' (portanto). Eles são fundamentais para falar e escrever em francês no nível A2.', 'Para usar os conectores corretamente, observe a estrutura:
- ''et'' liga palavras ou ideias semelhantes: Ex: ''J''aime le café et le thé.'' (Eu gosto de café e chá.)
- ''mais'' introduz uma oposição: ''Il est petit mais fort.'' (Ele é pequeno, mas forte.)
- ''ou'' indica uma escolha: ''Tu préfères le chocolat ou la vanille?'' (Você prefere chocolate ou baunilha?)
- ''parce que'' introduz uma causa: ''Je reste à la maison parce que il pleut.'' (Fico em casa porque chove.)
- ''donc'' introduz uma consequência: ''Il a faim, donc il mange.'' (Ele está com fome, portanto ele come.)', '["Para adicionar informações: ''Je parle français et anglais.'' (Falo francês e inglês.)","Para expressar contraste: ''Je voudrais sortir, mais je suis fatigué.'' (Gostaria de sair, mas estou cansado.)","Para oferecer opções: ''Tu veux du café ou du thé?'' (Você quer café ou chá?)","Para explicar o motivo: ''Je suis content parce que j''ai une bonne nouvelle.'' (Estou feliz porque tenho uma boa notícia.)","Para indicar conclusão: ''Il fait beau, donc nous allons à la plage.'' (Faz sol, portanto vamos à praia.)"]'::jsonb, '["Confundir ''et'' (e) com ''est'' (é), que têm pronúncias próximas.","Usar ''mais'' para adicionar ideias em vez de ''et''.","Esquecer de usar ''parce que'' antes da causa, às vezes separando com vírgula incorretamente.","Usar ''donc'' no início de uma frase sem contexto adequado.","Não usar ''ou'' para excluir, pensando que é inclusivo como em português."]'::jsonb, '["Na pronúncia, ''et'' soa como ''e'' e ''est'' soa como ''é''.","Em francês, muitas vezes se usa ''mais'' no início de resposta: ''Mais oui!'' (Mas sim!)","Cuidado: em linguagem informal, ''parce que'' pode ser reduzido a ''parce que'' ou ''pcq''.","''Donc'' é usado para consequência lógica, similar ao ''então'' em português."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

