insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-3ea631df8c18', 'fr', 'A2', 'Le Passé Composé', 'O passé composé é um tempo verbal usado para falar de ações passadas e concluídas. Em francês, é muito comum na conversa do dia a dia. Para formar o passé composé, usamos o presente do indicativo dos auxiliares être ou avoir, seguido do particípio passado do verbo principal. Nesta lição, você vai aprender a formar e usar o passé composé com exemplos práticos.', 'Para formar o passé composé, use: sujeito + auxiliar (avoir ou être) no presente + particípio passado. A maioria dos verbos usa avoir: j''ai parlé, tu as fini. Os verbos de movimento e pronominais usam être: je suis allé(e), elle est partie. O particípio passado dos verbos regulares em -er é formado substituindo -er por -é: parler -> parlé. Em -ir, substitui-se -ir por -i: finir -> fini. Em -re, substitui-se -re por -u: vendre -> vendu. Verbos irregulares têm formas próprias: avoir -> eu, être -> été, faire -> fait.', '["Ações concluídas no passado: Hier, j''ai mangé une pizza.","Uma série de ações no passado: Je me suis levé, j''ai pris une douche, et je suis sorti.","Com marcadores temporais: hier, ce matin, l''année dernière.","Para narrar eventos em uma história ou conversa."]'::jsonb, '["Esquecer de usar o auxiliar: ''Je mangé'' em vez de ''J''ai mangé''.","Usar o auxiliar errado: ''Je suis mangé'' em vez de ''J''ai mangé''.","Esquecer a concordância do particípio com être: ''Elle est allé'' em vez de ''Elle est allée''.","Confundir com o imparfait: o passé composé é para ações pontuais, o imparfait para ações contínuas."]'::jsonb, '["Com être, o particípio concorda em gênero e número com o sujeito.","Verbos pronominais sempre usam être: je me suis lavé.","Na negação, ne e pas contornam o auxiliar: Je n''ai pas mangé."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

