insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-7223beaf0e67', 'fr', 'A2', 'Comparativo e Superlativo em Francês', 'Nesta lição, você vai aprender a comparar coisas e pessoas em francês, usando o comparativo e o superlativo. Essas estruturas são muito úteis para falar sobre preferências, tamanhos, qualidades e mais.', 'Para formar o comparativo, use:
- plus + adjetivo/adverbo + que (mais...do que)
- moins + adjetivo/adverbo + que (menos...do que)
- aussi + adjetivo/adverbo + que (tão...quanto)
Para o superlativo, use:
- le/la/les plus + adjetivo/adverbo (o/a mais)
- le/la/les moins + adjetivo/adverbo (o/a menos)
Exemplos: Pierre est plus grand que Marie. (Pierre é mais alto que Marie.) C''est le plus grand. (É o maior.)', '["Para comparar qualidades ou ações entre duas pessoas ou coisas.","Para indicar que algo é superior, inferior ou igual.","Para destacar o máximo ou mínimo de um grupo."]'::jsonb, '["Esquecer de usar ''que'' no comparativo: ''Il est plus grand de moi'' (errado) → ''Il est plus grand que moi''.","Confundir ''plus'' (mais) com ''plu'' (chuva) ou ''pleut'' (chove).","Usar ''plus mieux'' em vez de ''mieux'' (melhor) para comparativos irregulares."]'::jsonb, '["Os adjetivos concordam em gênero e número com o substantivo: ''plus grande'', ''plus grands''.","Use ''que'' para comparações: ''plus grand que'', ''moins cher que''.","Para verbos, use ''plus de'' + substantivo, mas para adjetivos, apenas ''plus'' + adjetivo.","Atenção aos irregulares: ''bon'' → ''meilleur'' (melhor), ''mauvais'' → ''pire'' (pior), ''bien'' → ''mieux'' (melhor)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

