insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-1b3a7c2ec8b9', 'fr', 'A2', 'Les pronoms relatifs : qui, que, où', 'Os pronomes relativos ''qui'', ''que'' e ''où'' são usados para conectar orações e evitar repetições. ''Qui'' substitui o sujeito, ''que'' substitui o objeto direto, e ''où'' indica lugar ou tempo. Nesta lição, você aprenderá a usá-los corretamente em frases simples.', 'Formação: Em francês, usamos ''qui'' quando o pronome refere-se ao sujeito da oração relativa. Exemplo: ''La femme qui parle'' (A mulher que fala). Usamos ''que'' quando refere-se ao objeto direto. Exemplo: ''Le livre que je lis'' (O livro que eu leio). Usamos ''où'' para lugar ou tempo. Exemplo: ''La ville où j''habite'' (A cidade onde eu moro).', '["Qui: substitui o sujeito. Ex: ''Le chat qui dort'' (O gato que dorme).","Que: substitui o objeto direto. Ex: ''Le film que nous regardons'' (O filme que nós assistimos).","Où: indica lugar. Ex: ''Le parc où je joue'' (O parque onde eu brinco).","Où: indica tempo. Ex: ''Le jour où je suis né'' (O dia em que eu nasci)."]'::jsonb, '["Usar ''que'' em vez de ''qui'' quando o pronome é sujeito: ''La femme que parle'' (incorreto) → ''La femme qui parle'' (correto).","Usar ''qui'' em vez de ''que'' quando é objeto: ''Le livre qui je lis'' (incorreto) → ''Le livre que je lis'' (correto).","Confundir ''où'' (lugar/tempo) com ''que'' ou ''qui'': ''La ville que j''habite'' (incorreto) → ''La ville où j''habite'' (correto).","Esquecer de usar o pronome relativo, repetindo o substantivo: ''J''ai un ami. Il habite à Paris'' (repetição) → ''J''ai un ami qui habite à Paris'' (correto)."]'::jsonb, '["''Qui'' é sempre sujeito, mesmo que a palavra seja plural ou feminina.","''Que'' é sempre objeto direto, e pode ser contraído com ''ce'' para formar ''ce que''.","''Où'' é usado tanto para lugar quanto para tempo, e não pode ser substituído por ''que''.","Em frases com preposição, use ''qui'' ou ''lequel'' (ex: ''à qui'', ''avec qui'') – mas isso é mais avançado.","Os pronomes relativos são invariáveis, não mudam de forma."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

