insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-d1a5a1b60edb', 'fr', 'A2', 'Conectores Básicos em Francês (et, ou, mais, parce que)', 'Nesta lição, você vai aprender a usar conectores básicos em francês: ''et'' (e), ''ou'' (ou), ''mais'' (mas) e ''parce que'' (porque). Esses conectores ajudam a ligar ideias e formar frases mais completas.', 'Os conectores são palavras invariáveis que ligam palavras ou frases. ''Et'' une elementos semelhantes, ''ou'' indica alternância, ''mais'' expressa oposição, e ''parce que'' introduz uma causa ou explicação.', '["Et: para adicionar informações (ex: J''aime le café et le thé.)","Ou: para dar opções (ex: Tu veux du café ou du thé ?)","Mais: para mostrar contraste (ex: Il est petit mais il est fort.)","Parce que: para explicar o motivo (ex: Je reste à la maison parce que il pleut.)"]'::jsonb, '["Usar ''mais'' quando deveria usar ''et'' (ex: J''aime le chat mais le chien, em vez de et).","Confundir ''ou'' com ''où'' (onde): ''ou'' sem acento é ''ou'', ''où'' com acento é ''onde''.","Esquecer de usar ''parce que'' após uma pergunta com ''pourquoi'' (porquê).","Colocar vírgula antes de ''que'' em ''parce que'' indevidamente."]'::jsonb, '["''Parce que'' pode ser abreviado para ''parce qu'''' antes de vogal ou h mudo.","Em francês, a vírgula antes de ''et'' geralmente não é usada como em português.","Para perguntas, use ''pourquoi'' no início e ''parce que'' na resposta."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

