insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-fr-a2-21dcc91eb7c7', 'fr', 'A2', 'Pronomes COI e COD: Objetos Diretos e Indiretos', 'Nesta lição, você vai aprender a usar os pronomes de objeto direto (me, te, le, la, nous, vous, les) e indireto (me, te, lui, nous, vous, leur) para substituir nomes em frases. Isso torna a comunicação mais natural e evita repetições.', 'Para formar frases com objetos diretos e indiretos, coloque o pronome antes do verbo. O objeto direto responde à pergunta ''quê?'' ou ''quem?'', enquanto o indireto responde ''a quem?'' ou ''para quem?''. Exemplos: ''Je vois Paul'' -> ''Je le vois'' (direto), ''Je parle à Paul'' -> ''Je lui parle'' (indireto).', '["Substituir um objeto direto: Je mange la pomme -> Je la mange.","Substituir um objeto indireto: Je téléphone à Marie -> Je lui téléphone.","Usar ''me'' e ''te'' para objetos diretos e indiretos: Il me voit (direto), Il me parle (indireto).","Substituir nomes de pessoas em situações formais: Vous lui écrivez (a ele/ela)."]'::jsonb, '["Confundir ''le'' e ''lui'' para objetos diretos e indiretos: ''Je le parle'' é errado, o correto é ''Je lui parle''.","Esquecer de colocar o pronome antes do verbo: ''Je vois le'' em vez de ''Je le vois''.","Usar ''lui'' para o plural: ''leur'' é o plural de ''lui''.","Esquecer a concordância do particípio passado com o objeto direto em tempos compostos: ''Je les ai vus'' (com ''s'')."]'::jsonb, '["Os pronomes ''me'', ''te'', ''nous'', ''vous'' são usados para ambas as funções.","Em frases negativas, o pronome fica entre ''ne'' e o verbo: ''Je ne le vois pas''.","Com verbos como ''penser à'' e ''songer à'', o objeto indireto é substituído por ''y''.","Com verbos como ''parler à'' e ''téléphoner à'', usa-se ''lui'' ou ''leur''."]'::jsonb, 0, true)
