insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-fr-a2-c16acee0494c', 'fr', 'A2', 'Quand j''étais enfant...', 'Quand j''étais enfant, j''habitais à la campagne avec ma famille. Nous avions une petite maison avec un grand jardin. Chaque matin, je me réveillais tôt pour aider mon père. Il travaillait dans les champs et ma mère préparait le petit-déjeuner. Nous mangions ensemble et puis j''allais à l''école. L''école était loin, alors je marchais une heure. Mais j''aimais marcher parce que je voyais les animaux et les arbres. Pendant la récréation, mes amis et moi jouions au football. Nous courions et riions beaucoup. Après l''école, je rentrais à la maison et je faisais mes devoirs. Le soir, nous dînions et puis je lisais un livre. Je lisais souvent des histoires d''aventures. Maintenant, je vis en ville et ma vie est différente. Mais parfois, je pense à mon enfance et je souris. J''étais heureux et insouciant. La vie était simple et belle.', 'Où est-ce que je vivais quand j''étais enfant ?', '["dans une ville","à la campagne","près de la mer","dans un appartement"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"No texto, dizemos ''j''habitais à la campagne'', que significa ''eu morava no campo''.","options":["dans une ville","à la campagne","près de la mer","dans un appartement"],"prompt":"Où est-ce que je vivais quand j''étais enfant ?"},{"answer_index":2,"explanation_pt_br":"O texto afirma ''je marchais une heure'', ou seja, ''eu andava uma hora'', indicando que íamos a pé.","options":["en bus","en vélo","à pied","en voiture"],"prompt":"Comment est-ce que j''allais à l''école ?"},{"answer_index":1,"explanation_pt_br":"No texto: ''mes amis et moi jouions au football'', ou seja, ''meus amigos e eu jogávamos futebol''.","options":["je lisais","je jouais au football","je dormais","je mangeais"],"prompt":"Qu''est-ce que je faisais pendant la récréation ?"}]'::jsonb, 0, true)
