insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-58fa16be7299', 'it', 'A2', 'Il Futuro Semplice', 'O futuro semplice é usado para falar de ações que acontecerão no futuro. É um tempo verbal muito comum na língua italiana e é fácil de formar. Nesta lição, você vai aprender a conjugar verbos regulares e irregulares no futuro, e também vai praticar com exercícios.', 'Para formar o futuro simples de verbos regulares, pegue o infinitivo do verbo e adicione as terminações: -ò, -ai, -à, -emo, -ete, -anno. Por exemplo: parlare (falar) → parlerò, parlerai, parlerà, parleremo, parlerete, parleranno. Para verbos terminados em -care e -gare, adiciona-se um ''h'' antes das terminações, como in ''cercherete'' (de cercare).', '["para falar de ações futuras: Domani andrò al mare.","para expressar suposições ou hipóteses sobre o presente: Sarà a casa? (Será que ele está em casa?)","para fazer promessas: Ti chiamerò più tardi.","para expressar uma certeza sobre o futuro: L''anno prossimo compreremo una casa."]'::jsonb, '["Usar o presente do indicativo para expressar futuro em vez do futuro simples.","Confundir as terminações do futuro com as do condicional.","Esquecer de adicionar o ''h'' em verbos como ''cercare''."]'::jsonb, '["Os verbos modais (dovere, potere, volere) têm formas irregulares no futuro: dovrò, potrò, vorrò.","O futuro simples de ''essere'' e ''avere'' são irregulares: sarò, avrò.","Em italiano, o futuro pode ser usado para expressar probabilidade de forma educada."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

