insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-b557fbf07418', 'it', 'A2', 'Pronomi Diretti e Indiretti', 'Nesta lição, você vai aprender a usar os pronomes diretos e indiretos em italiano. Esses pronomes substituem nomes para evitar repetições, tornando a comunicação mais fluida e natural. Vamos focar nos pronomes de objeto direto e indireto no presente do indicativo.', 'Os pronomes diretos substituem o objeto direto (responde ''o quê?'' ou ''quem?''): mi, ti, lo/la, ci, vi, li/le. Os pronomes indiretos substituem o objeto indireto (responde ''a quem?''): mi, ti, gli/le, ci, vi, gli. No presente, eles vêm antes do verbo. Exemplo: ''Vedo Marco'' -> ''Lo vedo''; ''Parlo a Maria'' -> ''Le parlo''.', '["Usamos pronomes diretos para substituir objetos diretos.","Usamos pronomes indiretos para substituir objetos indiretos (pessoas).","Os pronomes podem ser usados com verbos comuns como ''vedere'', ''mangiare'', ''chiamare'', ''dare'', etc."]'::jsonb, '["Confundir ''lo'' e ''gli''.","Esquecer de concordar o pronome com o gênero (lo/la, li/le).","Colocar o pronome depois do verbo no presente (forma correta: antes)."]'::jsonb, '["No italiano informal, ''gli'' pode ser usado para ''loro'' também, mas no nível A2 aprendemos ''gli'' para ''a lui'' e ''le'' para ''a lei''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

