insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-84a522f207fc', 'it', 'A2', 'Verbi Riflessivi', 'Os verbos reflexivos são verbos usados com um pronome reflexivo (mi, ti, si, ci, vi) para indicar que a ação é feita por si mesmo. São muito comuns em italiano e usados para falar de ações da vida diária.', 'A formação é: pronome reflexivo + verbo no presente. O pronome reflexivo muda de acordo com a pessoa: mi (io), ti (tu), si (lui/lei), ci (noi), vi (voi), si (loro). No infinitivo, o pronome é ''si'' e o verbo termina em ''-si'', por exemplo: ''lavarsi'' (lavar-se).', '["Ações da rotina diária, como acordar, lavar-se, vestir-se.","Ações que envolvem o próprio corpo, como penteado ou barbear-se.","Ações de movimento, como sentir-se ou chamar-se.","Ações recíprocas, quando duas pessoas fazem algo juntas, como ''abbracciarsi'' (se abraçam)."]'::jsonb, '["Esquecer o pronome reflexivo: ''''Io lavo'''' em vez de ''''Io mi lavo''''.","Usar o pronome errado para a pessoa: ''''Loro si chiama'''' em vez de ''''Loro si chiamano''''.","Colocar o pronome depois do verbo no presente: ''''Io lavo mi'''' em vez de ''''Io mi lavo''''."]'::jsonb, '["O pronome reflexivo vem antes do verbo no presente do indicativo.","No passato prossimo, o verbo usare o auxiliar ''essere'' e o particípio passado concorda com o sujeito.","Alguns verbos podem ser reflexivos ou não, mudando o significado: ''lavare'' (lavar) vs ''lavarsi'' (lavar-se).","No imperativo, o pronome é colocado depois do verbo: ''Alzati!'' (Levante-se!)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

