insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-dd4abd9941ab', 'it', 'A2', 'Comparativo di Uguaglianza e Maggioranza', 'Nesta lição, você vai aprender a comparar pessoas, lugares e coisas em italiano. Vamos ver como dizer que algo é igual ou mais do que outra coisa, usando ''così ... come'' e ''più ... di''.', 'Para comparar igualdade, usamos ''così + aggettivo + come'' (ex.: ''Marco è così alto come Paolo''). Para comparar superioridade, usamos ''più + aggettivo + di'' (ex.: ''Roma è più grande di Firenze''). O segundo termo de comparação pode ser um nome, pronome, ou verbo.', '["Confrontare persone o cose: ''Questo libro è più interessante di quello.''","Confrontare azioni: ''Lei parla più velocemente di me.''","Confrontare quantità: ''Ho più amici di te.''","Esprimere uguaglianza: ''Questo caffè è così buono come quello.''"]'::jsonb, '["Usar ''che'' em vez de ''di'' para comparar aggettivi: ''più grande che'' (errado) vs. ''più grande di'' (correto).","Confundir ''così ... come'' com ''tanto ... quanto'' (que também é correto, mas menos comum).","Esquecer de usar ''di'' antes de pronomes pessoais (io, tu, lui/lei, noi, voi, loro)."]'::jsonb, '["Com números e quantità, ''di'' é usado: ''più di dieci''.","Com nomes próprios, ''di'' é usado: ''più di Maria''.","Quando a comparação é entre duas cláusulas, use ''che'': ''È meglio uscire che restare a casa.'' (mas isso é avançado; para A2, fique com ''di'' para palavras simples)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

