insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-fd4addead1ee', 'it', 'A2', 'Partitivi e Quantità: Un po'' di Pratica', 'Nesta lição, você vai aprender a usar palavras como ''un po'' di'', ''molto'', ''poco'', ''tanto'' e outras para falar de quantidades em italiano. Isso ajuda a expressar quanto de uma coisa você tem ou quer, por exemplo, quando você faz compras, cozinha ou planeja uma festa.', 'Use ''di'' antes de um substantivo para formar expressões de quantidade: ''un po'' di pane'', ''molta acqua'', ''pochi amici''. ''Di'' pode se combinar com artigos: ''del'', ''dello'', ''della'', ''dei'', ''degli'', ''delle''. Exemplos: ''un po'' di pane'', ''molto zucchero'', ''poche mele''.', '["Falar sobre comida: ''Vorrei un po'' di pane.''","Explicar quanto você tem: ''Ho pochi soldi.''","Pedir algo em uma loja: ''Mi dia un chilo di mele.''","Falar sobre tempo: ''Ho molto tempo libero.''"]'::jsonb, '["Esquecer de usar ''di'' antes do substantivo: ''un po'' pane'' (errado), mas ''un po'' di pane'' (certo).","Usar ''molto'' com substantivos contáveis no plural (ex.: ''molti amici''), não ''molto amici''.","Confundir ''poco'' (pouco) com ''un po'' (um pouco).","Esquecer a concordância: ''molta acqua'' (feminino singular), ''molti libri'' (masculino plural)."]'::jsonb, '["Lembre-se: ''un po'' di'' é usado com substantivos não contáveis e também com contáveis no plural, mas não com singulares contáveis.","Para perguntar sobre quantidade, use ''quanto/quanta/quanti/quante''.","Na forma negativa, use ''non... molto/poco''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

