insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-098113827751', 'it', 'A2', 'Relative Pronouns: che e cui', 'Nesta lição, você vai aprender a usar os pronomes relativos ''che'' e ''cui'' para conectar frases e dar mais informações sobre pessoas, coisas e lugares. Vamos ver quando usar cada um e como evitar erros comuns.', 'O pronome relativo ''che'' é invariável e pode ser usado como sujeito ou objeto direto. Exemplos: ''Il libro che leggo è interessante.'' (O livro que leio é interessante). Já ''cui'' é usado depois de preposições (di, a, da, in, con, su, per, tra/fra). Exemplos: ''La persona a cui parlo è mia madre.'' (A pessoa com quem falo é minha mãe).', '["Usamos ''che'' para pessoas, animais ou coisas, como sujeito ou objeto.","Usamos ''cui'' depois de preposições, como ''a cui'', ''di cui'', ''con cui''.","''Che'' nunca é precedido por preposição; nesse caso, usamos ''cui''."]'::jsonb, '["Usar ''che'' depois de preposição (ex: ''il libro a che penso'' – errado; correto: ''il libro a cui penso'').","Confundir ''che'' como sujeito e ''cui'' como possessivo (não confunda com ''il cui'' que é possessivo).","Esquecer a preposição antes de ''cui'' quando necessária."]'::jsonb, '["''Cui'' não muda de forma, mesmo com preposições compostas (es. ''per cui'', ''senza cui'').","Em frases com ''cui'', a preposição é obrigatória."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

