insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-6216d2dab199', 'it', 'A2', 'Il Futuro Semplice', 'O futuro semplice é usado para falar de ações que acontecerão no futuro. É um tempo verbal muito comum em italiano, especialmente para planos, previsões e promessas. Nesta lição, você aprenderá como formar e usar o futuro semplice.', 'Para formar o futuro semplice, você adiciona as terminações -ò, -ai, -à, -emo, -ete, -anno ao infinitivo do verbo. Para verbos da primeira conjugação (-are), a vogal temática ''a'' muda para ''e'' (ex: parlare -> parlerò). Para verbos da segunda (-ere) e terceira (-ire), basta adicionar as terminações diretamente (ex: credere -> crederò; dormire -> dormirò). Alguns verbos são irregulares, como ''essere'' (sarò) e ''avere'' (avrò).', '["Para expressar ações futuras: Domani andrò al mercato.","Para fazer previsões: Secondo me, domani pioverà.","Para expressar promessas: Ti prometto che lo farò.","Para expressar suposições sobre o presente: Chi sarà alla porta?"]'::jsonb, '["Confundir as terminações do futuro com as do condicional (ex: ''parlerei'' em vez de ''parlerò'').","Esquecer de mudar ''a'' para ''e'' nos verbos -are (ex: ''parlarò'' em vez de ''parlerò'').","Usar o presente em vez do futuro para ações futuras (ex: ''domani vado'' em vez de ''domani andrò'').","Formar o futuro de verbos irregulares como se fossem regulares (ex: ''essarò'' em vez de ''sarò'')."]'::jsonb, '["O futuro semplice é frequentemente usado com expressões de tempo como ''domani'', ''la settimana prossima'', ''tra un anno''.","Na linguagem falada, às vezes o presente é usado no lugar do futuro para expressar ações futuras já planejadas.","Para verbos que terminam em -care e -gare, adiciona-se um ''h'' antes da terminação (ex: cercare -> cercherò; pagare -> pagherò)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

