insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-9837ccb0444d', 'it', 'A2', 'Pronomi diretti e indiretti (A2)', 'Nesta lição, você vai aprender a usar os pronomes diretos e indiretos em italiano. Esses pronomes substituem nomes e ajudam a evitar repetições, tornando a comunicação mais natural. Vamos focar no uso com verbos no presente e no passato prossimo, nível A2.', 'Os pronomes diretos (mi, ti, lo/la, ci, vi, li/le) substituem o objeto direto (quem? o quê?). Exemplos: ''Vedo Marco'' → ''Lo vedo''. Os pronomes indiretos (mi, ti, gli, le, ci, vi, gli) substituem o objeto indireto (a quem?). Exemplos: ''Parlo a Maria'' → ''Le parlo''. No passato prossimo, o particípio passado concorda com o pronome direto: ''Ho visto Marco'' → ''L''ho visto''. Com pronomes indiretos, não há concordância: ''Ho parlato a Maria'' → ''Le ho parlato''.', '["Substituir um objeto direto para evitar repetição: ''Compro il pane'' → ''Lo compro''.","Substituir um objeto indireto (pessoa) para evitar repetição: ''Telefono a Luca'' → ''Gli telefono''.","Usar com verbos modais: ''Posso aiutarti'' (posso + aiutare + ti).","No passato prossimo, com pronome direto: ''Ho comprato la mela'' → ''L''ho comprata''.","No passato prossimo, com pronome indireto: ''Ho scritto a Maria'' → ''Le ho scritto''."]'::jsonb, '["Confundir pronomes diretos e indiretos: ''Vedo lei'' (errado) vs ''La vedo'' (certo).","Errar a concordância do particípio passado: ''Ho comprato la mela'' → ''L''ho comprato'' (errado) vs ''L''ho comprata'' (certo).","Usar o pronome sujeito no lugar do objeto: ''Io vedo lui'' (errado) vs ''Lo vedo'' (certo).","Esquecer de colocar o pronome antes do verbo: ''Vedo lo'' (errado) vs ''Lo vedo'' (certo)."]'::jsonb, '["Os pronomes diretos e indiretos têm a mesma forma para a primeira e segunda pessoa do singular e plural (mi, ti, ci, vi).","Para a terceira pessoa, o direto (lo/la/li/le) é diferente do indireto (gli/le).","Com os verbos modais (potere, dovere, volere), o pronome pode vir antes do verbo modal ou ligado ao infinitivo: ''Ti posso aiutare'' ou ''Posso aiutarti''.","No imperativo, os pronomes são ligados ao verbo: ''Compra il pane!'' → ''Compralo!''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

