insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-cc24b0dffe34', 'it', 'A2', 'Comparativo in Italiano', 'Nesta lição, você vai aprender a comparar pessoas, lugares e coisas em italiano usando as formas do comparativo. Vamos ver como dizer que algo é ''mais... do que'', ''menos... do que'' e ''tão... quanto''. Essas estruturas são muito úteis no dia a dia para expressar preferências, opiniões e diferenças.', 'Para formar o comparativo, usamos ''più'' (mais), ''meno'' (menos) e ''così... come'' ou ''tanto... quanto'' (tão... quanto). Estrutura: [soggetto] + verbo + ''più/meno'' + aggettivo/avverbio + ''di'' + secondo termine di confronto. Exemplos: ''Maria è più alta di Luca.'' (Maria é mais alta do que Luca). Para comparar quantità: ''Ho più libri di te.'' (Tenho mais livros do que você).', '["Comparar características de pessoas: ''Giovanni è più giovane di Marco.''","Comparar lugares: ''Roma è più grande di Firenze.''","Comparar quantidades: ''Questo negozio ha meno clienti di quello.''","Expressar igualdade: ''Questo libro è così interessante come quello.''"]'::jsonb, '["Usar ''che'' em vez de ''di'' com adjetivos: ''Lei è più alta *che* Marco'' → correto: ''Lei è più alta di Marco''.","Usar ''di'' com números em vez de ''che'': ''Ci sono più di dieci persone'' é correto, mas ''Ci sono più di dieci *che* venti'' é errado; use ''che'' para comparar quantidades: ''Ho più mele che pere''.","Confundir ''più'' com ''molto'': ''più'' é para comparativo, ''molto'' significa ''muito''.","Esquecer a concordância em gênero e número: ''Le ragazze sono più alte dei ragazzi'' (não ''alto'')."]'::jsonb, '["Lembre-se: use ''di'' antes de nomes, pronomes e números.","Use ''che'' quando comparar duas qualidades do mesmo sujeito: ''È più intelligente che simpatico'' (Ele é mais inteligente do que simpático).","O comparativo de igualdade pode ser formado também com ''tanto... quanto'', mas ''così... come'' é mais comum na fala."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

