insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-fea326e5439a', 'it', 'A2', 'Partitivi e Quantità', 'Nesta lição, você vai aprender a usar palavras como ''un po'' di'', ''molto'', ''troppo'' e ''abbastanza'' para falar de quantidades no dia a dia. Essas palavras são muito úteis para fazer compras, cozinhar e conversar sobre comida e outras coisas.', 'Em italiano, usamos ''di'' depois de expressões de quantidade, mas com palavras como ''molto'', ''troppo'' e ''abbastanza'', usamos ''di'' apenas se a palavra seguinte for um artigo definido (il, lo, la, i, gli, le). Por exemplo: ''molto pane'' (não ''molto di pane''), mas ''molto del pane'' (quando falamos de uma parte específica). Com ''un po'' di'', sempre usamos ''di''.', '["Per offrire qualcosa: ''Vuoi un po'' di caffè?''","Per fare la spesa: ''Compro un chilo di mele.''","Per parlare di quantità generiche: ''C''è molto traffico oggi.''","Per esprimere necessità: ''Ho bisogno di un po'' di riposo.''","Per descrivere abitudini: ''Mangio troppa pasta.''"]'::jsonb, '["Dire ''molto di pane'' invece di ''molto pane''.","Dimenticare l''articolo dopo ''molto'' quando serve: ''molto del pane'' (per una parte specifica).","Confondere ''un po'''' (un poco) con ''un po'' di'' seguito da un nome.","Usare ''di'' dopo ''abbastanza'' davanti a un nome senza articolo: ''abbastanza di zucchero'' (errato), corretto ''abbastanza zucchero''.","Dimenticare l''accordo di ''molto/troppo'' con il nome: ''molta pazienza'' (non ''molto pazienza'')."]'::jsonb, '["Usamos ''un po'' di'' com substantivos incontáveis: ''un po'' di zucchero''.","Com substantivos contáveis, use ''qualche'' + singular: ''qualche amico''.","Para perguntar sobre quantidade, use ''quanto/quanta'': ''Quanto pane vuoi?''","Na forma negativa, ''non... molto'' pode significar ''pouco''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

