insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-3f150c251afa', 'it', 'A2', 'I pronomi relativi: che e cui', 'Nesta lição, você vai aprender a usar os pronomes relativos ''che'' e ''cui'' para conectar frases e dar mais informações sobre pessoas, coisas ou lugares. Esses pronomes são muito úteis para falar de maneira mais natural e evitar repetições.', '**Che** é invariável e pode ser sujeito ou objeto direto. Exemplo: ''Il libro che leggo è interessante.'' (O livro que leio é interessante). **Cui** é usado depois de preposições (di, a, da, in, con, su, per, tra, fra). Exemplo: ''La città in cui vivo è grande.'' (A cidade em que vivo é grande).', '["Usamos ''che'' para pessoas, animais ou coisas, como sujeito ou objeto.","Usamos ''cui'' depois de preposições, como ''a cui'', ''con cui'', ''in cui''.","Com ''cui'', a preposição é obrigatória.","Podemos usar ''cui'' para possessão com ''il cui'', ''la cui'', etc."]'::jsonb, '["Usar ''che'' depois de preposição (ex: ''la persona a che parlo'' – errado).","Esquecer a preposição antes de ''cui'' (ex: ''la città cui vivo'' – errado).","Confundir ''che'' e ''cui'' quando o antecedente é uma pessoa.","Usar ''che'' como possessivo (ex: ''il ragazzo che la macchina è rossa'' – errado)."]'::jsonb, '["''Che'' é invariável, não muda para gênero ou número.","''Cui'' também é invariável.","Em linguagem formal, podemos usar ''il quale/la quale'' no lugar de ''che'', mas é menos comum.","Pratique com frases do dia a dia para ganhar confiança."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

