insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-5bc979376ec2', 'it', 'A2', 'Passato Prossimo: Il Tempo del Passato', 'O passato prossimo é usado para falar de ações completas no passado, com relevância no presente. É formado com o verbo avere ou essere + particípio passado do verbo principal.', 'Para formar o passato prossimo, usamos o presente de avere ou essere como auxiliar, seguido do particípio passado. Com avere, o particípio é invariável (parlato, mangiato). Com essere, o particípio concorda em gênero e número com o sujeito (andato/andata/andati/andate). Verbos que usam essere: andare, venire, nascere, morire, partire, arrivare, etc. Verbos que usam avere: mangiare, parlare, vedere, etc.', '["Ações concluídas no passado: ''Ieri ho mangiato una pizza.''","Ações recentes: ''Stamattina ho bevuto un caffè.''","Experiências de vida: ''Ho già visto questo film.''","Mudanças de estado ou movimento com essere: ''Sono andato a Roma.''"]'::jsonb, '["Usar o auxiliar errado: ''Ho andato'' em vez de ''Sono andato''.","Não concordar o particípio com o sujeito quando usa essere: ''Maria è andato'' em vez de ''Maria è andata''.","Usar o passato prossimo para ações habituais no passado (usar imperfetto).","Confundir o particípio passado de verbos irregulares: ''faccio'' -> ''fatto'', non ''facito''."]'::jsonb, '["Com avere, o particípio passado não muda: ''ho mangiato'', ''hai mangiato''.","Com essere, o particípio concorda: ''sono andato'' (masculino singular), ''sono andata'' (feminino singular), ''sono andati'' (masculino plural), ''sono andate'' (feminino plural).","Verbos reflexivos usam sempre essere: ''mi sono svegliato''.","Alguns verbos usam essere para movimento ou mudança, mas avere para outros sentidos: ''ho corso'' (corsa) vs ''sono corso'' (correre nel senso di muoversi verso un luogo)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

