insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-9ae22ed982be', 'it', 'A2', 'Il Futuro Semplice', 'O futuro semplice é um tempo verbal usado para expressar ações que acontecerão no futuro. Neste nível, você vai aprender a conjugar verbos regulares e alguns irregulares comuns, e a usar esse tempo para falar de planos, previsões e promessas.', 'Para formar o futuro simples, tire as terminações -are, -ere, -ire do infinitivo e adicione: -erò, -erai, -erà, -eremo, -erete, -anno (para verbos em -are e -ere); para verbos em -ire, use -irò, -irai, -irà, -iremo, -irete, -iranno. Exemplos: parlare -> parlerò; credere -> crederò; partire -> partirò. Alguns verbos irregulares: avere -> avrò, essere -> sarò, fare -> farò, andare -> andrò.', '["Para falar de ações futuras: Domani andrò al mare.","Para expressar previsões: Secondo me, pioverà.","Para fazer promessas: Ti prometto che lo farò.","Para expressar suposições sobre o presente: Sarà a casa ora?"]'::jsonb, '["Erro: Usar o presente para futuro, ex: ''Domani vado'' em vez de ''Domani andrò''.","Erro: Esquecer o ''h'' em ''avrò'', ''avrai'' etc.","Erro: Inverter as terminações -are e -ire: dizer ''partirò'' corretamente, mas ''dormirò'' em vez de ''dormirò'' (na verdade ''dormirò'' é incorreto; o correto é ''dormirò''? Não, ''dormire'' -> ''dormirò'', que é correto. Esclarecer: muitos confundem a terminação de -ere e -ire, mas são as mesmas: -irò, -irai, -irà, etc.)"]'::jsonb, '["Atenção: as terminações do futuro são as mesmas para verbos em -are e -ere.","Verbos em -care e -gare acrescentam ''h'' para manter o som: cercare -> cercherò, pagare -> pagherò.","O futuro pode ser usado para fazer suposições sobre o presente: ''Che ore saranno?''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

