insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-7807b70d5b88', 'it', 'A2', 'Comparativo di maggioranza e uguaglianza', 'Nesta lição, você vai aprender a comparar pessoas, lugares e coisas em italiano usando o comparativo di maggioranza (mais do que) e o comparativo di uguaglianza (tão... quanto). Isso é útil para descrever diferenças e semelhanças no dia a dia.', 'Formação: 1) Comparativo di maggioranza: ''più + aggettivo/avverbio + di'' (com nomi o pronomi) ou ''più + aggettivo/avverbio + che'' (com verbi, preposizioni, o due aggettivi). Exemplo: ''Maria è più alta di Anna.'' / ''È più facile andare in treno che in auto.'' 2) Comparativo di uguaglianza: ''(così) + aggettivo/avverbio + come'' ou ''tanto + aggettivo/avverbio + quanto''. Exemplo: ''Paolo è (così) alto come Luca.'' / ''Studio tanto quanto lavoro.''', '["Para comparar características físicas ou de personalidade: ''Luca è più simpatico di Marco.''","Para comparar preços, quantidades: ''Questo libro è più caro di quello.''","Para comparar ações: ''Correre è più faticoso che camminare.''","Para dizer que duas coisas são iguais: ''La mia casa è (così) grande come la tua.''"]'::jsonb, '["Usar ''di'' com verbos: ''È più facile di andare'' (errado). O correto é ''che'' antes de verbo: ''È più facile andare che correre.''","Esquecer ''come'' no comparativo de igualdade: ''Maria è così alta quanto Anna.'' (errado). O correto é ''così... come''.","Confundir ''di'' e ''che'': ''più... di'' é usado com nomes, pronomes, números; ''più... che'' com verbos, adjetivos, advérbios ou preposições."]'::jsonb, '["No comparativo de maioria, ''di'' pode ser seguido por articolo partitivo (del, della) quando comparamos quantidades: ''Ho più libri di te.''","Com ''che'' também se compara dois aggettivi: ''È più simpatico che bello.''","O ''così'' no comparativo de igualdade é opcional: ''Maria è alta come Anna.'' tem o mesmo significado."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

