insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-459ed3c34c52', 'it', 'A2', 'Partitivi e Quantità', 'Nesta lição, você vai aprender a usar palavras para falar de quantidades em italiano. Vamos ver os partitivos como ''del'', ''della'', ''dello'', e também palavras como ''un po'' di'', ''molto'', ''poco'' e ''troppo''. Essas palavras ajudam a dizer quanto de alguma coisa você tem ou quer. Por exemplo, ''Vorrei del pane'' significa ''Eu gostaria de um pouco de pão''.', 'Os partitivos são formados pela preposição ''di'' + artigo definido. Veja: ''di'' + ''il'' = ''del'', ''di'' + ''lo'' = ''dello'', ''di'' + ''la'' = ''della'', ''di'' + ''i'' = ''dei'', ''di'' + ''gli'' = ''degli'', ''di'' + ''le'' = ''delle''. Eles são usados com substantivos incontáveis ou plurais para indicar uma quantidade indefinida. Na forma negativa, usamos ''non... mica'' ou simplesmente ''nessun''. Palavras como ''molto'', ''poco'', ''troppo'' concordam em gênero e número com o substantivo.', '["Para oferecer algo: ''Vuoi del caffè?'' (Você quer um pouco de café?)","Para pedir algo: ''Posso avere dell''acqua?'' (Posso ter um pouco de água?)","Para falar de quantidades: ''Ho molti amici.'' (Tenho muitos amigos.)","Para negar quantidade: ''Non ho tempo.'' (Não tenho tempo.)","Para falar de comida: ''Mangio della pasta.'' (Eu como massa.)"]'::jsonb, '["Usar ''di'' sozinho em vez de partitivo: ''Ho di pane'' (errado) vs ''Ho del pane'' (certo).","Esquecer a concordância: ''Molto amici'' (errado) vs ''Molti amici'' (certo).","Usar partitivo com substantivos contáveis singulares: ''Ho del libro'' (errado) vs ''Ho un libro'' (certo).","Confundir ''poco'' e ''piccolo'': ''Un poco caffè'' (errado) vs ''Un po'' di caffè'' (certo)."]'::jsonb, '["O partitivo é usado principalmente em frases afirmativas. Em perguntas, muitas vezes usamos ''qualche'' ou ''alcuni''.","A forma ''un po'' di'' é invariável e significa ''um pouco de''.","Lembre-se: ''molto'' pode ser advérbio (não muda) ou adjetivo (concorda com o substantivo)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

