insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-8f2ee6fb01a7', 'it', 'A2', 'Introduzione alla CI: ''C''è'' e ''Ci sono''', 'Nesta lição, você vai aprender a usar ''c''è'' e ''ci sono'', que são essenciais para falar sobre a existência de pessoas, lugares e objetos. ''C''è'' significa ''há'' (singular) e ''ci sono'' significa ''há'' (plural). Vamos praticar com exemplos do dia a dia, como descrever uma casa, uma cidade ou uma festa.', 'Para formar frases com ''c''è'' e ''ci sono'', usamos:
- ''C''è'' + substantivo singular (ex: C''è un libro sul tavolo.)
- ''Ci sono'' + substantivo plural (ex: Ci sono due libri sul tavolo.)
A negativa é formada com ''non'' antes: ''non c''è'' e ''non ci sono''.
Para perguntas, basta inverter a ordem ou usar entonação: ''C''è un libro?'' / ''Ci sono libri?''.', '["Para dizer que algo existe em um lugar: C''è un parco in centro.","Para descrever o que tem em um ambiente: Nella mia camera ci sono un letto e una scrivania.","Para perguntar sobre a existência: C''è un supermercato qui vicino?","Para negar a existência: Non c''è latte in frigo.","Para falar sobre eventos: Stasera c''è una festa."]'::jsonb, '["Usar ''c''è'' com plural: Errado: C''è due libri. Certo: Ci sono due libri.","Usar ''ci sono'' com singular: Errado: Ci sono un libro. Certo: C''è un libro.","Esquecer o ''non'' na negativa: Errado: C''è nessun problema. Certo: Non c''è nessun problema.","Confundir ''c''è'' com ''ecco'': ''Ecco'' significa ''aqui está'', não ''há''."]'::jsonb, '["''C''è'' e ''ci sono'' são usados apenas para existência, não para posse (usamos ''avere'').","Em perguntas, a entonação é importante: ''C''è un bar?'' (com voz ascendente).","Lembre-se de que ''c''è'' é a contração de ''ci'' + ''è''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

