insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-a718a0f9173f', 'it', 'A2', 'Basic Connectors in Italian', 'Nesta lição, você vai aprender a usar conectores básicos em italiano, como ''e'', ''ma'', ''o'', ''perché'' e ''quindi''. Esses conectores ajudam a unir ideias e construir frases mais complexas, essenciais para a comunicação do dia a dia.', 'Os conectores são palavras invariáveis que ligam palavras ou frases. Os principais são: ''e'' (e), ''ma'' (mas), ''o'' (ou), ''perché'' (porque) e ''quindi'' (portanto). Eles são usados no meio da frase ou no início, dependendo do sentido.', '["''e'' para adicionar informações: ''Io mangio pane e formaggio.''","''ma'' para contrastar: ''Voglio uscire, ma piove.''","''o'' para alternativas: ''Preferisci tè o caffè?''","''perché'' para explicar causa: ''Studio italiano perché lavoro in Italia.''","''quindi'' para conclusão: ''Sono stanco, quindi vado a casa.''"]'::jsonb, '["Confundir ''perché'' com ''perciò'': ''perché'' explica causa, ''perciò'' indica consequência.","Usar ''ma'' no início de frase em contextos formais.","Esquecer a vírgula antes de ''ma'' e ''quindi'' em frases longas.","Trocar ''e'' por ''ed'' antes de vogal (ed è correto, mas não obrigatório)."]'::jsonb, '["Os conectores são invariáveis, ou seja, não mudam de forma.","Em italiano, ''perché'' também pode ser usado em respostas curtas, como ''Perché sì''.","Pratique a entonação: conectores geralmente têm pausa antes."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

