insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-f83a3a89b60c', 'it', 'A2', 'L’imperfetto: introduzione', 'Nesta lição, você vai aprender o imperfetto, um tempo verbal do passado muito usado em italiano para descrever ações contínuas, hábitos e estados no passado. Vamos ver como formar o imperfetto dos verbos regulares e quando usá-lo.', 'Para formar o imperfetto, pegue o radical do verbo (infinitivo sem -are, -ere, -ire) e adicione as terminações: -avo, -avi, -ava, -avamo, -avate, -avano para verbos em -are (ex: parlare -> parlavo); -evo, -evi, -eva, -evamo, -evate, -evano para verbos em -ere (ex: credere -> credevo); -ivo, -ivi, -iva, -ivamo, -ivate, -ivano para verbos em -ire (ex: dormire -> dormivo).', '["Descrever ações em progresso no passado: ''Mentre mangiavo, è arrivato Marco.''","Expressar hábitos no passado: ''Da bambino, giocavo a calcio ogni giorno.''","Descrever pessoas, lugares ou situações no passado: ''La casa era grande e luminosa.''","Falar de duas ações simultâneas no passado: ''Lei leggeva mentre lui cucinava.''"]'::jsonb, '["Confundir imperfetto com passato prossimo: imperfetto para ações contínuas/hábitos, passato prossimo para ações pontuais.","Usar a forma do presente no lugar do imperfetto: ''io parlo'' em vez de ''io parlavo''.","Esquecer de adaptar a terminação para cada pessoa: ''io parlava'' (errado), ''io parlavo'' (correto)."]'::jsonb, '["O imperfetto é um tempo simples, não precisa de verbo auxiliar.","Existem apenas três verbos irregulares no imperfetto: essere, fare, dire.","As terminações são sempre as mesmas para os verbos regulares das três conjugações."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

