insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-a83413894eac', 'it', 'A2', 'Futuro Semplice', 'O futuro semplice é usado para falar de ações que acontecerão no futuro. É um tempo verbal importante para planejar, prometer e prever. Em italiano, o futuro simples é formado de maneira regular para a maioria dos verbos, com algumas exceções.', 'Para formar o futuro simples, pegue o infinitivo do verbo (por exemplo, parlare, vedere, partire) e adicione as seguintes terminações: -ò, -ai, -à, -emo, -ete, -anno. Para verbos da primeira conjugação (-are), a vogal ''a'' muda para ''e'' antes das terminações (exemplo: parlerò). Verbos da segunda (-ere) e terceira (-ire) conjugação mantêm a vogal temática (exemplo: vedrò, partirò). Alguns verbos irregulares, como ''essere'' (sarò), ''avere'' (avrò), ''fare'' (farò), ''andare'' (andrò), ''venire'' (verrò), têm formas especiais.', '["Para expressar ações futuras planejadas ou previstas.","Para fazer promessas ou previsões.","Para expressar suposições ou hipóteses sobre o presente ou o futuro.","Em frases condicionais com ''se'' + futuro simples."]'::jsonb, '["Confundir o futuro simples com o presente do indicativo.","Usar o futuro simples em contextos onde o presente é mais comum (ex: após ''se'').","Esquecer de mudar ''a'' para ''e'' em verbos -are.","Aplicar as terminações erradas aos verbos irregulares."]'::jsonb, '["Em italiano, o futuro simples também pode ser usado para expressar incerteza ou probabilidade sobre algo no presente.","Muitas vezes, o futuro simples é usado com expressões de tempo como ''domani'', ''la prossima settimana'', ''tra due anni''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

