insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-21748144e98c', 'it', 'A2', 'Pronomi Diretti e Indiretti', 'Nesta lição, você vai aprender a usar os pronomes diretos (mi, ti, lo, la, ci, vi, li, le) e indiretos (mi, ti, gli, le, ci, vi, loro) em italiano. Esses pronomes substituem nomes e evitam repetições, tornando a comunicação mais natural.', 'Os pronomes diretos respondem à pergunta ''o quê?'' ou ''quem?'' e substituem o objeto direto. Por exemplo: ''Compro il pane'' -> ''Lo compro''. Os pronomes indiretos respondem à pergunta ''a quem?'' e substituem o objeto indireto. Por exemplo: ''Parlo a Maria'' -> ''Le parlo''. No presente, eles vêm antes do verbo: ''Mi piace'', ''Ti chiamo'', ''Gli do un libro''. No passato prossimo, o particípio passado concorda com o pronome direto: ''L''ho comprato'' (masculino), ''L''ho comprata'' (feminino).', '["Substituir objetos diretos: ''Vedo il film'' -> ''Lo vedo''.","Substituir objetos indiretos: ''Scrivo a Paolo'' -> ''Gli scrivo''.","Com verbos modais (potere, dovere, volere): ''Devo comprare il giornale'' -> ''Lo devo comprare'' ou ''Devo comprarlo''.","Com o imperativo: ''Compralo!'' (compre-o), ''Scrivile!'' (escreva para ela)."]'::jsonb, '["Confundir ''lo'' e ''la'' com o gênero do substantivo.","Usar ''gli'' para feminino plural (deve-se usar ''loro'' ou ''a loro'').","Colocar o pronome depois do verbo no presente do indicativo (exceto em imperativo ou infinitivo)."]'::jsonb, '["Os pronomes diretos e indiretos são frequentemente usados em situações cotidianas, como fazer compras, pedir informações ou falar sobre preferências.","No passato prossimo, o particípio passado concorda em gênero e número com o pronome direto.","Para reforçar o pronome, pode-se usar ''a me'', ''a te'', etc., após o verbo: ''A me piace''."]'::jsonb, 0, true)
