insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-6693a165cf9e', 'it', 'A2', 'Comparativo di uguaglianza: ''così ... come'' e ''tanto ... quanto''', 'Nesta unidade, vamos aprender a comparar pessoas, objetos ou situações que são iguais ou semelhantes. Em italiano, usamos ''così ... come'' e ''tanto ... quanto'' para formar o comparativo de igualdade.', 'Para formar o comparativo de igualdade em italiano, usamos duas estruturas principais: 1) ''così'' + adjetivo/advérbio + ''come'' (ex.: ''Marco è così alto come Luca.''). 2) ''tanto'' + substantivo/adjetivo/advérbio + ''quanto'' (ex.: ''Ho tanto lavoro quanto te.''). A escolha entre elas é muitas vezes de estilo, mas ''così...come'' é mais usado com adjetivos, e ''tanto...quanto'' pode ser usado com substantivos também.', '["Para comparar características de pessoas ou coisas: ''Questo libro è così interessante come quel film.''","Para comparar quantidades: ''Ho tanto tempo quanto te.''","Para comparar ações: ''Luca corre così veloce come Marco.''","Para expressar igualdade de nível: ''Lei è tanto gentile quanto sua sorella.''"]'::jsonb, '["Errado: ''Marco è così alto *quanto* Luca.'' – use ''come'' com ''così''.","Errado: ''Ho tanto amici *come* te.'' – com ''tanto'' use ''quanto''.","Errado: ''Questo è così buono *di* quello.'' – não use ''di'' no comparativo de igualdade."]'::jsonb, '["Preste atenção: ''come'' e ''quanto'' são invariáveis.","Com ''tanto'' para substantivos no plural, use ''tanti'' e ''quanti'' (mas o uso é mais comum no singular).","Na fala informal, às vezes ''come'' e ''quanto'' são trocados, mas para o exame use a forma correta.","O comparativo de igualdade é usado também para perguntas: ''Sei così bravo come lui?''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

