insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-a8b9b3942bf4', 'it', 'A2', 'Pronomi Relativi: Che e Cui', 'Nesta lição, você vai aprender a usar os pronomes relativos ''che'' e ''cui'' para conectar frases e dar mais informações sobre pessoas, coisas e lugares. Isso vai deixar seu italiano mais natural e fluente.', 'O pronome ''che'' é usado como sujeito ou objeto direto, e não muda de forma. Por exemplo: ''La persona che parla è mia sorella'' (A pessoa que fala é minha irmã). O pronome ''cui'' é usado depois de preposições, como ''di'', ''a'', ''da'', ''in'', ''con'', ''su''. Por exemplo: ''La città in cui vivo è grande'' (A cidade em que vivo é grande).', '["Usamos ''che'' para pessoas e coisas, como sujeito ou objeto.","Usamos ''cui'' depois de preposições: ''di cui'', ''a cui'', ''con cui''.","Usamos ''cui'' para lugares e tempo, com preposições: ''in cui'', ''da cui''.","Podemos usar ''che'' para substituir ''il quale'', ''la quale'', etc."]'::jsonb, '["Usar ''che'' depois de preposição. Errado: ''La persona a che parlo''. Certo: ''La persona a cui parlo''.","Usar ''cui'' sem preposição. Errado: ''La persona cui parla''. Certo: ''La persona che parla'' ou ''La persona a cui parlo''.","Esquecer a preposição antes de ''cui''. Errado: ''La città cui vivo''. Certo: ''La città in cui vivo''.","Confundir ''che'' e ''cui'' com ''chi'' (quem). ''Che'' e ''cui'' são relativos; ''chi'' é usado para ''a pessoa que''."]'::jsonb, '["Lembre-se: ''che'' é invariável, não muda para masculino/feminino ou singular/plural.","''cui'' também é invariável.","Quando ''cui'' é usado com preposição ''di'', pode significar ''cujo'' em português: ''Il libro di cui parlo'' = ''O livro do qual falo''.","Na fala informal, às vezes omitimos a preposição com ''cui'', mas na escrita formal é importante usá-la."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

