insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-9c65394c5726', 'it', 'A2', 'Connettori di Base: e, ma, perché, quindi', 'Nesta lição, você vai aprender a usar conectores básicos em italiano para unir ideias e dar mais fluência às suas frases. Esses conectores são essenciais para falar e escrever de forma mais natural.', 'Os conectores básicos são palavras que ligam frases ou partes de frases. Veja como usá-los:

- **e** (e): une ideias semelhantes. Exemplo: ''Mario e Laura sono amici.''
- **ma** (mas): indica contraste. Exemplo: ''Voglio uscire, ma piove.''
- **perché** (porque): explica a causa. Exemplo: ''Studio italiano perché mi piace.''
- **quindi** (portanto): indica conclusão. Exemplo: ''Ho fame, quindi mangio.''', '["Unire due informazioni simili: ''Oggi è caldo e soleggiato.''","Mostrar contraste: ''Vorrei comprare la macchina, ma non ho soldi.''","Explicar uma razão: ''Non esco perché sono stanco.''","Concluir algo: ''Piove, quindi prendo l''ombrello.''","Falar de ações em sequência: ''Mi sveglio e faccio colazione.''"]'::jsonb, '["Confundir ''e'' com ''è'' (verbo ser): ''La pizza e buona'' é incorreto. O correto é ''La pizza è buona''.","Usar ''ma'' no lugar de ''perché'': ''Non vengo ma sono malato'' é incorreto. O correto é ''Non vengo perché sono malato''.","Colocar ''quindi'' no lugar de ''perché'': ''Piove quindi ho l''ombrello'' não expressa causa, e sim conclusão."]'::jsonb, '["Os conectores são invariáveis, ou seja, não mudam de forma.","Na fala, ''e'' pode ser pronunciado como ''è'' em algumas regiões, mas a escrita é diferente.","Pratique os conectores em frases curtas antes de formar frases mais longas."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

