insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-8fcec614cc7a', 'it', 'A2', 'Pronomi Diretti e Indiretti (Direct and Indirect Pronouns)', 'Neste tópico, você vai aprender a usar os pronomes diretos e indiretos em italiano. Os pronomes diretos (mi, ti, lo, la, ci, vi, li, le) substituem objetos diretos, enquanto os indiretos (mi, ti, gli, le, ci, vi, loro) substituem objetos indiretos. Eles são essenciais para evitar repetições e tornar a conversa mais natural.', 'Os pronomes diretos e indiretos são colocados antes do verbo. Por exemplo: ''Maria compra il pane'' → ''Maria lo compra'' (direto). ''Parlo a Luca'' → ''Gli parlo'' (indireto). Com infinitivo, podem ser ligados ao verbo: ''Voglio comprarlo'' ou ''Lo voglio comprare''. Preste atenção nas formas: diretos: mi, ti, lo/la, ci, vi, li/le; indiretos: mi, ti, gli/le, ci, vi, loro.', '["Usar ''lo'', ''la'', ''li'', ''le'' para substituir objetos diretos (pessoa ou coisa).","Usar ''gli'' para ''a lui'' e ''le'' para ''a lei''.","Usar ''ci'' e ''vi'' como pronomes diretos ou indiretos para ''noi'' e ''voi''.","Colocar o pronome antes do verbo conjugado: ''Ti chiamo domani''.","Com infinitivo, pode juntar o pronome ao final: ''Devo chiamarti''."]'::jsonb, '["Confundir ''lo'' e ''gli'': ''lo'' é direto, ''gli'' é indireto.","Esquecer a concordância: ''Li'' para masculino plural, ''Le'' para feminino plural.","Inverter a ordem: ''Chiamo ti'' em vez de ''Ti chiamo''.","Usar ''gli'' para feminino plural: use ''loro'' ou ''a loro''."]'::jsonb, '["Em italiano, o pronome direto concorda com o gênero e número do objeto substituído.","''Lei'' é formal para ''você'', mas o pronome indireto ''le'' pode ser ambíguo; no contexto, é claro.","Os pronomes diretos e indiretos são átonos e nunca recebem acento tônico."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

