insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-8b4cc8b049de', 'it', 'A2', 'Comparativo di maggioranza e uguaglianza', 'Nesta lição, você vai aprender a comparar pessoas, objetos e situações em italiano usando o comparativo di maggioranza (mais... do que) e il comparativo di uguaglianza (tão... quanto). Vamos ver como formar frases comparativas e como usá-las no dia a dia.', 'Per il comparativo di maggioranza si usa: più + aggettivo/avverbio + di (se il secondo termine è un nome o pronome) oppure che (se il secondo termine è un verbo, una preposizione, o un''intera frase). Esempio: ''Marco è più alto di Luca'' (nome) / ''È più facile uscire che restare a casa'' (verbo). Per il comparativo di uguaglianza si usa: (così) + aggettivo/avverbio + come. Esempio: ''Maria è (così) alta come Lucia''.', '["Confrontare due persone o cose: ''Questo libro è più interessante di quello''","Confrontare due azioni: ''Correre è più faticoso che camminare''","Esprimere uguaglianza: ''Questa pizza è buona come quella di ieri''","Confrontare quantità con nomi: ''Ho più amici che tempo''","Confrontare con avverbi: ''Luca parla più lentamente di Marco''","Confrontare età, prezzo, distanza: ''Il treno è più veloce dell''autobus''"]'::jsonb, '["Usare ''di'' invece di ''che'' prima di un verbo o di una preposizione: ''È meglio partire di aspettare'' (sbagliato) -> ''È meglio partire che aspettare'' (corretto)","Scambiare ''che'' e ''di'' con nomi: ''Sono più alto che te'' (sbagliato) -> ''Sono più alto di te'' (corretto)","Usare ''come'' invece di ''di/che'' nel comparativo di maggioranza: ''Luca è più alto come Marco'' (sbagliato) -> ''Luca è più alto di Marco'' (corretto)","Dimenticare l''accordo dell''aggettivo con il nome: ''Le case sono più grandi che piccole'' (ok) ma attenzione: se l''aggettivo si riferisce a un nome femminile, va accordato: ''Maria è più alta di Lucia''","Confondere ''di'' come preposizione di luogo: ''Vengo di Roma'' (sbagliato) -> ''Vengo da Roma'' (corretto)"]'::jsonb, '["Nel comparativo di maggioranza, ''di'' si usa con nomi e pronomi, mentre ''che'' si usa con verbi, preposizioni e frasi intere.","Il comparativo di uguaglianza si può formare anche con ''tanto... quanto'' in contesti formali, ma ''così... come'' è più comune e informale.","Con gli aggettivi possessivi, si usa ''di'' + pronome possessivo (es. ''il mio''): ''Il mio libro è più nuovo del tuo''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

