insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-39b4b60b5c51', 'it', 'A2', 'Partitivi e quantità: un po'', molto, tanto', 'Nesta lição, você vai aprender a usar palavras como ''un po'' di'', ''molto'', ''tanto'' e ''un sacco di'' para falar de quantidades em italiano. Essas palavras são muito úteis no dia a dia, por exemplo, ao fazer compras ou cozinhar.', 'Normalmente, usamos ''di'' antes do substantivo. Veja: ''un po'' di pane'' (um pouco de pão), ''molta acqua'' (muita água), ''tanti amici'' (muitos amigos). A palavra ''molto'' muda para ''molta'', ''molti'', ''molte'' conforme o gênero e o número do substantivo. O mesmo acontece com ''tanto''.', '["Para oferecer comida ou bebida: ''Vuoi un po'' di caffè?''","Para dizer que há uma grande quantidade: ''C''è molto traffico oggi.''","Para falar de quantidades com amigos: ''Ho molti amici a Roma.''","Para expressar uma quantidade pequena: ''Ho solo un po'' di tempo.''"]'::jsonb, '["Esquecer de usar ''di'' depois de ''un po'''': ''un po'' pane'' (errado) vs ''un po'' di pane'' (correto).","Usar ''molto'' sem concordância: ''molto amici'' (errado) vs ''molti amici'' (correto).","Usar ''di'' com ''molto'' de forma incorreta: ''molto di pane'' (errado) vs ''molto pane'' (correto).","Confundir ''tanto'' e ''troppo'': ''troppo'' significa ''demais''."]'::jsonb, '["Lembre-se: ''molto'' pode ser advérbio e não muda: ''Grazie molto!'' (errado) vs ''Grazie mille!'' (correto).","Para perguntar a quantidade, use ''quanto/quanta/quanti/quante''.","''Un po'''' é uma forma abreviada de ''un poco''."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

