insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-a7ca10de1ff3', 'it', 'A2', 'Connettivi di base', 'Nesta lição, você vai aprender a conectar palavras e frases em italiano usando conectivos básicos como ''e'', ''ma'', ''o'', ''perché'' e ''quindi''. Esses conectivos ajudam a formar frases mais longas e a expressar ideias com mais clareza no dia a dia.', 'Em italiano, os conectivos são usados para unir palavras ou frases. Os principais são:
- ''e'' (e) para adicionar ideias;
- ''ma'' (mas) para contrastar;
- ''o'' (ou) para alternativas;
- ''perché'' (porque) para explicar razões;
- ''quindi'' (então) para conclusões.
Eles são colocados entre as palavras ou frases que conectam. Exemplos: ''Io parlo italiano e inglese.'' / ''Vorrei uscire, ma fa freddo.'' / ''Preferisci il caffè o il tè?''', '["Usamos ''e'' para adicionar informações: ''Compro pane e latte.''","Usamos ''ma'' para mostrar contraste: ''Il film è lungo, ma è bello.''","Usamos ''o'' para escolhas: ''Vuoi acqua o vino?''","Usamos ''perché'' para dar razões: ''Studio italiano perché voglio lavorare in Italia.''","Usamos ''quindi'' para conclusões: ''Piove, quindi prendo l''ombrello.''"]'::jsonb, '["Não usar vírgula antes de ''ma'' quando conecta duas frases completas: ''Voglio andare, ma sono stanco.'' (apenas antes de ''ma'').","Confundir ''perché'' (porque) com ''perciò'' (por isso): ''Sono stanco, perciò vado a casa.''","Usar ''e'' em vez de ''o'' para alternativas: ''Vuoi tè e caffè?'' (errado) – ''Vuoi tè o caffè?'' (correto)."]'::jsonb, '["Os conectivos são invariáveis, ou seja, não mudam de forma.","Na fala informal, às vezes ''perché'' é abreviado para ''perché''?\nExemplo: ''Perché non vieni?''","Quando usamos ''ma'' ou ''quindi'', a frase pode ser dividida em duas: ''Piove. Quindi prendo l''ombrello.''"]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

