insert into public.grammar_topics (id, language, level, title, overview_pt_br, formation_pt_br, use_cases, common_mistakes, notes_pt_br, sort_order, is_published)
values ('generated-grammar-it-a2-d9d4bc2346d0', 'it', 'A2', 'Pronomi Diretti e Indiretti', 'Nesta lição, você vai aprender a usar os pronomes diretos e indiretos em italiano. Esses pronomes ajudam a evitar repetições e tornar as frases mais naturais. Vamos ver como eles funcionam com verbos comuns e em situações do dia a dia.', 'Os pronomes diretos (mi, ti, lo/la, ci, vi, li/le) substituem o objeto direto (quem ou o quê). Os pronomes indiretos (mi, ti, gli/le, ci, vi, gli) substituem o objeto indireto (a quem). Eles geralmente vêm antes do verbo: ''Io vedo Marco'' → ''Io lo vedo''; ''Parlo a Maria'' → ''Le parlo''.', '["Para evitar repetir um nome ou objeto: ''Compro il pane'' → ''Lo compro''.","Para responder de forma curta: ''Hai visto il film?'' → ''Sì, l''ho visto''.","Com verbos como ''dare'', ''dire'', ''mandare'' para expressar a quem: ''Do un regalo a Luca'' → ''Gli do un regalo''.","No imperativo: ''Compralo!'' (compre-o), ''Digli la verità'' (diga-lhe a verdade)."]'::jsonb, '["Confundir ''lo'' (direto) com ''gli'' (indireto): ''Lo parlo'' (errado) em vez de ''Gli parlo''.","Esquecer de usar o pronome: ''Vedo Marco'' em vez de ''Lo vedo''.","Colocar o pronome depois do verbo em tempos compostos: ''Ho lo visto'' (errado) em vez de ''L''ho visto''.","Usar ''le'' para ''a ela'' e ''gli'' para ''a ele'', mas esquecer que ''gli'' também pode ser usado para ''a eles'' no plural."]'::jsonb, '["Nas respostas curtas, o particípio passado concorda com o pronome direto: ''L''ho comprata'' (a camisa).","Com verbos modais (potere, dovere, volere), o pronome pode vir antes do verbo modal ou depois do infinitivo: ''Lo devo fare'' ou ''Devo farlo''.","Atenção: ''Le'' (indireto feminino singular) é diferente de ''le'' (direto plural feminino)."]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, overview_pt_br=excluded.overview_pt_br, formation_pt_br=excluded.formation_pt_br, use_cases=excluded.use_cases, common_mistakes=excluded.common_mistakes, notes_pt_br=excluded.notes_pt_br, is_published=excluded.is_published, updated_at=now();

