insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-b2458e92e8ed', 'it', 'A2', 'Quantità e Partitivi in Italiano', 'Quando andiamo al mercato o al supermercato, usiamo spesso parole per indicare quantità. In italiano, usiamo il partitivo "di" con l''articolo determinativo (del, dello, della, dei, degli, delle) per dire "some" o "any". Per esempio: "Vorrei del pane" (I would like some bread). Il partitivo cambia secondo il genere e il numero del nome che segue: del pane (maschile singolare), della pasta (femminile singolare), dei biscotti (maschile plurale), delle mele (femminile plurale). Attenzione: davanti a vocale, usiamo "dell''": dell''olio, dell''acqua. Per le quantità specifiche, usiamo parole come un chilo di, un litro di, un pacchetto di, una bottiglia di, un etto di. Per esempio: "un chilo di mele", "una bottiglia di acqua". Nel linguaggio informale, spesso diciamo "un po'' di" per indicare una piccola quantità: "un po'' di zucchero". Ricorda: per le quantità, usiamo "di" senza articolo dopo le parole di misura: "un chilo di pane", non "un chilo del pane". Il partitivo si usa quando non specifichiamo una quantità esatta. Se parliamo di una quantità specifica, usiamo l''articolo determinativo o altre espressioni. Per esempio: "Compro il pane" (tutto il pane che voglio) e "Compro del pane" (una parte del pane).', 'Quale frase usa il partitivo correttamente?', '["Vorrei del acqua.","Vorrei della acqua.","Vorrei dell''acqua.","Vorrei dei acqua."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"Davanti a vocale, usiamo ''dell'' per il partitivo femminile singolare: dell''acqua.","options":["Vorrei del acqua.","Vorrei della acqua.","Vorrei dell''acqua.","Vorrei dei acqua."],"prompt":"Quale frase usa il partitivo correttamente?"},{"answer_index":0,"explanation_pt_br":"Pane è maschile singolare, quindi usiamo ''del''.","options":["del","della","dei","dello"],"prompt":"Completa: \"Compro ___ pane.\" (un po'' di pane)"},{"answer_index":1,"explanation_pt_br":"Un litro di latte indica una quantità esatta, mentre ''del'' indica una quantità non specificata.","options":["del latte","un litro di latte","della latte","dei latte"],"prompt":"Quale espressione indica una quantità specifica?"}]'::jsonb, 0, true)
