insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-8e219ff18bdf', 'it', 'A2', 'Il Futuro Semplice: Parlare di Domani', 'Ciao! Oggi impariamo il futuro semplice. Con questo tempo, possiamo parlare di cose che accadranno. È facile e utile per la vita di tutti i giorni.

Per formare il futuro, prendiamo il verbo all''infinito e aggiungiamo le desinenze: -ò, -ai, -à, -emo, -ete, -anno. Per esempio, "parlare" diventa "parlerò", "parlerai", "parlerà", "parleremo", "parlerete", "parleranno". Attenzione: i verbi in -are e -ere cambiano la vocale: "andare" diventa "andrò", "vedere" diventa "vedrò".

Usiamo il futuro per fare previsioni ("Domani pioverà"), promesse ("Ti chiamerò stasera"), e progetti ("L''anno prossimo andremo in Italia"). Spesso usiamo parole come "domani", "la settimana prossima", "nel 2025".

Attenzione a non confondere il futuro con il presente: "Mangio" è ora, "Mangerò" è dopo. E ricordate: per i verbi riflessivi, il pronome va prima del verbo: "Mi sveglierò alle sette".

Ora, facciamo pratica con tre domande!', 'Quale frase usa il futuro semplice?', '["Ieri ho mangiato una pizza.","Oggi mangio una pizza.","Domani mangerò una pizza.","Sto mangiando una pizza."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A frase ''Domani mangerò una pizza'' usa o futuro semplice ''mangerò''. As outras opções usam passato prossimo, presente e presente progressivo, respectivamente.","options":["Ieri ho mangiato una pizza.","Oggi mangio una pizza.","Domani mangerò una pizza.","Sto mangiando una pizza."],"prompt":"Quale frase usa il futuro semplice?"},{"answer_index":2,"explanation_pt_br":"O futuro semplice de ''parlare'' para ''noi'' é ''parleremo''. ''Parliamo'' é presente, ''parlavamo'' é imperfetto, ''parleremmo'' é condizionale.","options":["Parliamo","Parlavamo","Parleremo","Parleremmo"],"prompt":"Come si dice \"nós falaremos\" in italiano?"},{"answer_index":1,"explanation_pt_br":"A frase ''Ti aiuterò con i compiti'' usa o futuro ''aiuterò'' e expressa uma promessa. As outras opções descrevem ações no presente, passado ou futuro planejado, mas não promessas.","options":["Domani vado al mercato.","Ti aiuterò con i compiti.","Oggi studio italiano.","Ieri ho comprato un libro."],"prompt":"Quale frase esprime una promessa?"}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-1d072d545e65', 'it', 'A2', 'I pronomi diretti e indiretti', 'In italiano, usiamo i pronomi per non ripetere i nomi. Oggi impariamo i pronomi diretti (mi, ti, lo, la, ci, vi, li, le) e indiretti (mi, ti, gli, le, ci, vi, gli). I pronomi diretti rispondono alla domanda "chi?" o "che cosa?" e sostituiscono il complemento oggetto. Per esempio: "Compro il pane" -> "Lo compro". I pronomi indiretti rispondono alla domanda "a chi?" o "a che cosa?" e sostituiscono il complemento di termine. Per esempio: "Parlo a Maria" -> "Le parlo". Attenzione: alla terza persona, il diretto è "lo" (maschile) e "la" (femminile), mentre l''indiretto è "gli" (maschile) e "le" (femminile). Al plurale, i diretti sono "li" (maschile) e "le" (femminile), mentre l''indiretto è "gli" per entrambi. Nel parlato informale, "gli" è spesso usato anche per il femminile plurale. Ricorda che i pronomi di solito vanno prima del verbo ("Lo vedo") o attaccati all''infinito ("voglio vederlo"). Con i verbi modali (potere, dovere, volere), il pronome può stare prima del verbo modale o attaccato all''infinito: "Lo posso fare" o "posso farlo". Nel passato prossimo, il participio passato concorda con il pronome diretto: "L''ho vista" (se "la" è femminile).', 'Quale pronome diretto sostituisce "il libro" nella frase: "Compro il libro"?', '["La","Lo","Gli","Le"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"\"Il libro\" è maschile singolare, quindi si usa il pronome diretto \"lo\". \"La\" è femminile, \"gli\" è indiretto maschile, \"le\" è indiretto femminile.","options":["La","Lo","Gli","Le"],"prompt":"Quale pronome diretto sostituisce \"il libro\" nella frase: \"Compro il libro\"?"},{"answer_index":2,"explanation_pt_br":"\"A Marco\" è complemento di termine maschile singolare, quindi il pronome indiretto corretto è \"gli\".","options":["lo","la","gli","le"],"prompt":"Quale pronome indiretto sostituisce \"a Marco\" nella frase: \"Parlo a Marco\"?"},{"answer_index":0,"explanation_pt_br":"\"La penna\" è femminile, quindi il participio passato concorda al femminile: \"l''ho persa\" (l'' = la). Le altre opzioni hanno errori di concordanza o pronomi sbagliati.","options":["Ho comprato la penna e l''ho persa.","Ho comprato la penna e l''ho perso.","Ho comprato la penna e gli ho persa.","Ho comprato la penna e le ho perso."],"prompt":"Scegli la frase corretta con il pronome diretto."}]'::jsonb, 0, true)
on conflict (id) do update set title=excluded.title, body=excluded.body, question=excluded.question, options=excluded.options, answer_index=excluded.answer_index, questions=excluded.questions, is_published=excluded.is_published, updated_at=now();

insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-afbef3a33c02', 'it', 'A2', 'Una giornata tipica: verbi riflessivi', 'Ciao! Oggi parliamo dei verbi riflessivi in italiano. I verbi riflessivi si usano quando l''azione della persona ricade sulla persona stessa. Per esempio: ''mi alzo'' significa ''io alzo me stesso''. In italiano, molti verbi di routine quotidiana sono riflessivi.

La formazione è semplice: prima del verbo, metti il pronome riflessivo (mi, ti, si, ci, vi, si). Poi coniughi il verbo normalmente. Per esempio: ''io mi alzo'', ''tu ti lavi'', ''lui/lei si veste''. Attenzione: con ''si'' per ''lui/lei'' e per ''loro'', e con ''ci'' per ''noi'' e ''vi'' per ''voi''.

Ecco alcuni verbi riflessivi comuni: svegliarsi, alzarsi, lavarsi, vestirsi, pettinarsi, farsi la doccia, rilassarsi, divertirsi. Li usiamo per parlare delle azioni di ogni giorno.

Ora, leggi la storia di Marco. Marco è un ragazzo brasiliano che vive in Italia. Ogni giorno, si sveglia alle sette, si alza subito e si fa una doccia veloce. Poi si veste e si pettina. Alle otto, esce di casa e va al lavoro. La sera, torna a casa, si rilassa sul divano e si diverte guardando la TV. Prima di dormire, si lava i denti. La sua vita è normale, ma gli piace molto.', 'Quale frase usa un verbo riflessivo?', '["Io mangio la pizza.","Tu leggi un libro.","Lei si lava le mani.","Noi parliamo italiano."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"A opção correta é ''Lei si lava le mani'', porque ''si lava'' é um verbo reflexivo (lavarsi). As outras opções usam verbos não reflexivos.","options":["Io mangio la pizza.","Tu leggi un libro.","Lei si lava le mani.","Noi parliamo italiano."],"prompt":"Quale frase usa un verbo riflessivo?"},{"answer_index":3,"explanation_pt_br":"O pronome reflexivo para ''nós'' em italiano é ''ci''. Por exemplo: ''noi ci laviamo'' (nós nos lavamos).","options":["mi","ti","si","ci"],"prompt":"Qual è il pronome riflessivo per ''noi''?"},{"answer_index":0,"explanation_pt_br":"Para ''io'', o pronome reflexivo é ''mi'' e o verbo é conjugado como ''sveglio''. Portanto, ''mi sveglio'' está correto.","options":["mi sveglio","ti svegli","si sveglia","ci svegliamo"],"prompt":"Completa la frase: ''Io _____ alle sette.'' (svegliarsi)"}]'::jsonb, 0, true)
