insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-6f9535280da8', 'it', 'A2', 'La Città e la Campagna', 'In Italia, ci sono molte città grandi e moderne. Per esempio, Milano è una città molto grande con molti negozi e uffici. La campagna italiana è diversa: ci sono colline, alberi e fattorie. La vita in città è più veloce che in campagna. In città, le persone camminano velocemente e usano i mezzi pubblici. In campagna, la vita è più tranquilla e le persone conoscono i loro vicini. Le città hanno più ristoranti e cinema, ma la campagna ha più natura e aria pulita. Secondo una ricerca, le città italiane sono più care della campagna per vivere. Per esempio, l''affitto in città è più alto che in campagna. Ma in campagna, i servizi come gli ospedali sono più lontani. Ogni luogo ha i suoi vantaggi. Alcune persone preferiscono la città per il lavoro e lo studio. Altre preferiscono la campagna per la pace. Confrontare la città e la campagna è interessante. In Italia, molti giovani vanno in città per l''università, ma poi tornano in campagna per la famiglia.', 'Qual è la differenza principale tra la città e la campagna?', '["La città è più tranquilla.","La campagna è più moderna.","La città è più veloce.","La campagna ha più negozi."]'::jsonb, 2, '[{"answer_index":2,"explanation_pt_br":"O texto diz que a vida na cidade é mais rápida que no campo.","options":["La città è più tranquilla.","La campagna è più moderna.","La città è più veloce.","La campagna ha più negozi."],"prompt":"Qual è la differenza principale tra la città e la campagna?"},{"answer_index":1,"explanation_pt_br":"O texto menciona que algumas pessoas preferem o campo pela paz.","options":["Perché c''è più lavoro.","Perché c''è più pace.","Perché ci sono più cinema.","Perché è più cara."],"prompt":"Secondo il testo, perché alcune persone preferiscono la campagna?"},{"answer_index":1,"explanation_pt_br":"O texto afirma que o aluguel na cidade é mais alto que no campo.","options":["L''affitto in campagna.","L''affitto in città.","Il cibo in campagna.","I trasporti in città."],"prompt":"Cosa è più caro secondo il testo?"}]'::jsonb, 0, true)
