insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-ae837091a3b7', 'it', 'A2', 'Cosa hai fatto ieri?', 'Ieri è stata una giornata importante per Marco. Ha visitato il centro storico di Roma con alcuni amici. Hanno camminato molto e hanno visto il Colosseo, il Foro Romano e il Pantheon. Marco ha fotografato tutto con il suo telefono. Dopo la visita, hanno mangiato una pizza in una trattoria vicino a Piazza Navona. La pizza era buonissima! Nel pomeriggio, hanno preso un gelato e hanno parlato della loro giornata. Marco ha detto: "Oggi ho fatto una cosa fantastica!" Tutti sono stati d''accordo. La sera, sono tornati a casa stanchi ma felici. Marco ha raccontato tutto alla sua famiglia: "Abbiamo camminato per ore, ma ne è valsa la pena!" La sua famiglia ha ascoltato con attenzione. Questa giornata rimarrà nella memoria di Marco per molto tempo.', 'Cosa ha fatto Marco ieri?', '["Ha visitato il centro storico di Roma.","Ha lavorato in ufficio.","Ha studiato italiano a casa.","Ha fatto una passeggiata al parco."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"A resposta correta é a primeira opção, pois o texto diz que Marco visitou o centro histórico de Roma com alguns amigos.","options":["Ha visitato il centro storico di Roma.","Ha lavorato in ufficio.","Ha studiato italiano a casa.","Ha fatto una passeggiata al parco."],"prompt":"Cosa ha fatto Marco ieri?"},{"answer_index":1,"explanation_pt_br":"O texto afirma que eles comeram pizza em uma trattoria perto da Piazza Navona, portanto a segunda opção é a correta.","options":["In un ristorante elegante.","In una trattoria vicino a Piazza Navona.","A casa di Marco.","In un bar veloce."],"prompt":"Dove hanno mangiato la pizza?"},{"answer_index":2,"explanation_pt_br":"Marco disse: \"Ho fatto una cosa fantastica!\" e o texto diz que a giornata rimarrà na memória dele, indicando que foi fantástica e inesquecível. Portanto, a terceira opção é a correta.","options":["Noiosa e brutta.","Difficile e stressante.","Fantastica e indimenticabile.","Tranquilla e normale."],"prompt":"Come è stata la giornata per Marco?"}]'::jsonb, 0, true)
