insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-2efdf08ff4b8', 'it', 'A2', 'La mia giornata: verbi riflessivi', 'Ciao! Oggi parliamo dei verbi riflessivi. In italiano, usiamo i verbi riflessivi quando l''azione è fatta su noi stessi. Per esempio, "mi sveglio" significa "io sveglio me stesso”. I verbi riflessivi sono molto comuni nella vita quotidiana: alzarsi, lavarsi, vestirsi, sentirsi. Per formare un verbo riflessivo, usiamo i pronomi riflessivi: mi, ti, si, ci, vi, si. Questi pronomi vanno prima del verbo. Per esempio, da "chiamare" abbiamo "chiamarsi" (to be called). La coniugazione al presente è: io mi chiamo, tu ti chiami, lui/lei si chiama, noi ci chiamiamo, voi vi chiamate, loro si chiamano. Attenzione: quando il verbo inizia con vocale, si può usare la forma apostrofata: "m''alzo" instead of "mi alzo", but it''s more common to use "mi alzo”. In Italy, people often say "Come ti chiami?" and "Mi chiamo Maria”. Also, "A che ora ti alzi?" (What time do you get up?). Remember that some verbs are reflexive only in Italian, like "sentirsi" (to feel) or "divertirsi" (to have fun). Practice with your daily routine: I wake up (mi sveglio), I wash (mi lavo), I get dressed (mi vesto). Use these to talk about your day. Good luck!', 'What is the correct reflexive pronoun for "io" with the verb "svegliare"?', '["mi","ti","si","ci"]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"Para \"io\", usamos o pronome reflexivo \"mi\", como em \"mi sveglio\".","options":["mi","ti","si","ci"],"prompt":"What is the correct reflexive pronoun for \"io\" with the verb \"svegliare\"?"},{"answer_index":2,"explanation_pt_br":"Para \"loro\", usamos \"si\" como pronome reflexivo, então \"si chiamano\".","options":["ci","vi","si","mi"],"prompt":"Choose the correct form to complete: \"Loro ____ chiamano Luca e Marco.\""},{"answer_index":1,"explanation_pt_br":"\"Alzarsi\" significa \"levantar-se\", então \"mi alzo\" é \"eu me levanto\".","options":["I wash","I get up","I feel","I sleep"],"prompt":"What does \"mi alzo\" mean?"}]'::jsonb, 0, true)
