insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-800fd07cea78', 'it', 'A2', 'Connettori Semplici', 'Oggi impariamo i connettori di base in italiano. I connettori sono parole che uniscono idee e frasi. Sono molto importanti per parlare e scrivere meglio. Usiamo ''e'' per aggiungere informazioni. Per esempio: ''Oggi studio italiano e lavoro.'' Usiamo ''ma'' per mostrare contrasto. Per esempio: ''Vorrei uscire, ma piove.'' Usiamo ''perché'' per spiegare il motivo. Per esempio: ''Studio italiano perché voglio lavorare in Italia.'' Usiamo ''quindi'' per mostrare conseguenza. Per esempio: ''Ho finito il lavoro, quindi posso riposare.'' Usiamo ''oppure'' per offrire alternative. Per esempio: ''Vuoi caffè oppure tè?'' Questi connettori rendono le frasi più chiare e naturali. Pratica con attenzione e vedrai che parlerai meglio!', 'Quale connettore si usa per aggiungere informazioni?', '["ma","e","perché","quindi"]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"''E'' è il connettore per aggiungere informazioni.","options":["ma","e","perché","quindi"],"prompt":"Quale connettore si usa per aggiungere informazioni?"},{"answer_index":2,"explanation_pt_br":"''Ma'' è usato per mostrare contrasto.","options":["e","perché","ma","oppure"],"prompt":"Quale connettore mostra contrasto?"},{"answer_index":1,"explanation_pt_br":"''Perché'' introduce la causa o il motivo.","options":["quindi","perché","oppure","e"],"prompt":"Quale connettore espime causa?"}]'::jsonb, 0, true)
