insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-2ccad68d3cf7', 'it', 'A2', 'Il fine settimana di Marco', 'Marco è un uomo di 35 anni che vive a Roma. Sabato scorso lui e la sua amica Giulia hanno visitato il Colosseo. La mattina è stata molto bella, con il sole e il cielo azzurro. Hanno comprato i biglietti online e sono entrati senza fare la coda. Dentro, hanno visto le antiche pietre e hanno ascoltato una guida che parlava della storia. Marco ha fatto molte foto con il telefono. Dopo la visita, hanno mangiato una pizza in una trattoria vicino. Nel pomeriggio, hanno camminato per il centro e hanno visto la Fontana di Trevi. Hanno lanciato una moneta nell''acqua, come si fa per portare fortuna. Alla sera, sono andati a un concerto di musica jazz in un parco. La musica era molto bella e le persone hanno applaudito tanto. Marco è tornato a casa alle undici. Era molto contento della giornata e ha detto: "Oggi ho imparato cose nuove e mi sono divertito molto!". Giulia ha risposto: "Anche io. Questo fine settimana è stato speciale!"', 'Cosa hanno fatto Marco e Giulia sabato mattina?', '["Hanno visitato il Colosseo.","Hanno mangiato una pizza.","Hanno visto un concerto.","Hanno camminato per il centro."]'::jsonb, 0, '[{"answer_index":0,"explanation_pt_br":"No texto, lê-se: ''Sabato scorso lui e la sua amica Giulia hanno visitato il Colosseo. La mattina è stata molto bella...'' Portanto, a resposta correta é que visitaram o Coliseu.","options":["Hanno visitato il Colosseo.","Hanno mangiato una pizza.","Hanno visto un concerto.","Hanno camminato per il centro."],"prompt":"Cosa hanno fatto Marco e Giulia sabato mattina?"},{"answer_index":1,"explanation_pt_br":"O texto diz: ''hanno mangiato una pizza in una trattoria vicino.'' E ''vicino'' refere-se ao Coliseu, pois é o lugar mencionado antes. Portanto, a resposta correta é ''In una trattoria vicino al Colosseo.''","options":["In un ristorante elegante.","In una trattoria vicino al Colosseo.","A casa di Marco.","In un parco."],"prompt":"Dove hanno mangiato la pizza?"},{"answer_index":1,"explanation_pt_br":"O texto afirma: ''hanno visto la Fontana di Trevi. Hanno lanciato una moneta nell''acqua, come si fa per portare fortuna.'' Portanto, a resposta correta é que lançaram uma moeda.","options":["Hanno fatto una foto.","Hanno lanciato una moneta.","Hanno ascoltato un concerto.","Hanno comprato un gelato."],"prompt":"Cosa hanno fatto alla Fontana di Trevi?"}]'::jsonb, 0, true)
