insert into public.quick_lessons (id, language, level, title, body, question, options, answer_index, questions, sort_order, is_published)
values ('generated-quick-lesson-it-a2-c8b0a1fe448a', 'it', 'A2', 'Quando ero bambino: introduzione all''imperfetto', 'Ciao! Oggi impariamo un tempo del passato molto importante: l''imperfetto. Usiamo l''imperfetto per parlare di azioni abituali nel passato, descrizioni nel passato e azioni in corso nel passato. Per esempio: "Da bambino, giocavo sempre nel parco." Questa frase parla di un''abitudine. Oppure: "La casa era grande e luminosa." Questa frase descrive una situazione nel passato. L''imperfetto si forma con le desinenze: -avo, -avi, -ava, -avamo, -avate, -avano per i verbi in -are; -evo, -evi, -eva, -evamo, -evate, -evano per i verbi in -ere; -ivo, -ivi, -iva, -ivamo, -ivate, -ivano per i verbi in -ire. Attenzione ai verbi essere e avere: "ero, eri, era, eravamo, eravate, erano" e "avevo, avevi, aveva, avevamo, avevate, avevano". Ricorda: l''imperfetto descrive il passato, mentre il passato prossimo indica azioni completate. Per esempio: "Mentre camminavo, ho visto Marco." Camminavo (imperfetto) è l''azione in corso, ho visto (passato prossimo) è l''azione completata. Pratica con gli esercizi!', 'Quale frase usa correttamente l''imperfetto per un''abitudine?', '["Ieri ho mangiato una pizza.","Da piccolo, andavo sempre al mare.","Stasera guardo un film.","Domani visiterò il museo."]'::jsonb, 1, '[{"answer_index":1,"explanation_pt_br":"A frase ''Da piccolo, andavo sempre al mare'' usa o imperfetto ''andavo'' para expressar um hábito no passado. As outras usam passato prossimo, presente e futuro.","options":["Ieri ho mangiato una pizza.","Da piccolo, andavo sempre al mare.","Stasera guardo un film.","Domani visiterò il museo."],"prompt":"Quale frase usa correttamente l''imperfetto per un''abitudine?"},{"answer_index":0,"explanation_pt_br":"Para verbos em -ere, a desinência da terceira pessoa do singular é -eva. Portanto, ''leggeva'' é correto.","options":["leggeva","leggevo","leggevi","leggevano"],"prompt":"Come si forma l''imperfetto del verbo ''leggere'' (leggere) per la terza persona singolare (lui/lei)?"},{"answer_index":1,"explanation_pt_br":"A frase ''Mentre pioveva, io leggevo un libro'' usa ''pioveva'' e ''leggevo'' (imperfetto) para descrever ações contínuas no passado. As outras usam passato prossimo, futuro e presente.","options":["Ieri ho comprato il pane.","Mentre pioveva, io leggevo un libro.","Domani andrò in palestra.","Oggi studio italiano."],"prompt":"Quale frase descrive una scena nel passato usando l''imperfetto?"}]'::jsonb, 0, true)
